window.CJ_MAP = [{"id":"gi-aging-exam","ch":"45","sys":"Digestion & elimination","name":"Abdominal assessment and GI changes with aging","patient":"A 78-year-old admitted with abdominal discomfort hasn’t had a bowel movement in 5 days. You are about to assess the abdomen.","topics":["45-gi-changes-with-aging","45-gi-history-and-the-abdominal-exam"],"report":["During my abdominal assessment I found a pulsating mass above the umbilicus with a bruit over the aorta; BP 172/96, HR 94. I stopped and did not palpate.","74-year-old with hypertension and a long smoking history, admitted for abdominal discomfort.","Possible abdominal aortic aneurysm.","Please evaluate now. The client is on bed rest; requesting orders for imaging and BP control."],"guide":[{"key":"45:0","name":"GI changes with aging"},{"key":"45:1","name":"Organs by quadrant (Table 45.1)"}],"nodes":[{"id":"abd-exam","name":"Abdominal exam & GI labs"}],"drugs":[],"videos":[{"id":"1Xc7RYkz-CE","title":"Abdominal assessment (RegisteredNurseRN)","see":"The order — inspect, auscultate, then percuss and palpate — and where to listen for bowel and vascular sounds"},{"id":"gALl_Yr-PnY","title":"What is peristalsis? (3D animation)","see":"Rings of smooth muscle squeezing behind the food and relaxing ahead of it"}],"steps":[{"k":"rc","gist":"Findings located <b>by quadrant</b>: distention or taut, glistening skin; <b>bowel sounds</b> absent, hypoactive or hyperactive; <b>guarding vs rigidity</b>; tenderness; and the alarms — <b>visible peristaltic waves</b> and a <b>bulging, pulsating mass or aortic bruit</b>. In older adults: <b>constipation and impaction</b>, fatty stools, poor appetite and signs of <b>B₁₂ or iron deficiency</b>.","terms":[{"t":"Right upper quadrant (RUQ)","see":"Most of the liver, the gallbladder, duodenum, head of the pancreas, hepatic flexure, part of the ascending and transverse colon.","why":"Pain or a finding in one quadrant usually comes from the <b>organs underneath</b> it.","means":"RUQ pain or tenderness points to the <b>liver, gallbladder or duodenum</b> — ask about jaundice, fatty-meal pain and dark urine."},{"t":"Left upper quadrant (LUQ)","see":"Left lobe of the liver, stomach, spleen, body and tail of the pancreas, splenic flexure, part of the transverse and descending colon.","why":"The <b>stomach, spleen and most of the pancreas</b> sit here.","means":"LUQ findings suggest the <b>stomach, pancreas or spleen</b> — an enlarged spleen is found by the provider’s percussion."},{"t":"Right lower quadrant (RLQ)","see":"Cecum, appendix, right ureter, right ovary and fallopian tube, right spermatic cord.","why":"The <b>appendix</b> and the start of the colon lie here.","means":"RLQ pain raises <b>appendicitis</b> — <b>no palpation</b> if appendicitis is suspected. Auscultation starts here (ileocecal valve)."},{"t":"Left lower quadrant (LLQ)","see":"Part of the descending colon, sigmoid colon, left ureter, left ovary and fallopian tube, left spermatic cord.","why":"The <b>sigmoid colon</b>, where stool collects before the rectum, lies here.","means":"LLQ findings suggest the <b>sigmoid colon</b> — for example stool, diverticular disease or obstruction."},{"t":"Midline","see":"Abdominal aorta; uterus if enlarged; bladder if distended.","why":"The <b>aorta</b> runs down the midline, so its pulsation and sounds are found there.","means":"A <b>bulging, pulsating mass or an aortic bruit</b> = possible <b>aneurysm</b>: don’t touch it, don’t percuss, notify the provider immediately."},{"t":"Hypoactive or absent bowel sounds","see":"Few or no gurgles (normal is 5–30 high-pitched gurgles a minute).","why":"Peristalsis has slowed or stopped — after abdominal surgery, with <b>peritonitis</b> or <b>paralytic ileus</b>.","means":"After surgery, the more reliable sign that peristalsis is back is <b>flatus within 8 hours or a stool within 12–24 hours</b> — ask."},{"t":"Hyperactive bowel sounds (borborygmus)","see":"Loud, frequent gurgling.","why":"Increased motility with diarrhea or gastroenteritis, or bowel working hard <b>above a complete obstruction</b>.","means":"Combine with distention, vomiting and <b>visible peristaltic waves</b> — report possible <b>obstruction</b>."},{"t":"Guarding vs rigidity","see":"Guarding: the client tenses on purpose. Rigidity: a board-hard abdomen the client can’t relax.","why":"<b>Rigidity is involuntary</b> — a reflex spasm of the abdominal muscles over an inflamed peritoneum.","means":"Rigidity is a sign of <b>peritoneal inflammation</b> — report it. Examine tender areas last and gently."},{"t":"Constipation and impaction in older adults","see":"Infrequent hard stools, straining, fullness; liquid stool seeping around a hard mass.","why":"With aging, <b>peristalsis slows</b> and nerve signals dull, so the urge to defecate is weaker and bowel movements get postponed.","means":"Ask about the usual bowel pattern and laxative use; watch for <b>impaction</b>."},{"t":"Steatorrhea in older adults","see":"Pale, bulky, greasy, foul-smelling stools that float.","why":"The aging pancreas makes <b>less lipase</b>, so fat is poorly digested and absorbed.","means":"Expected direction with aging is <b>less</b> lipase — never more; report fatty stools and weight loss."},{"t":"B₁₂ and iron deficiency in older adults","see":"Fatigue, pallor, a sore smooth tongue, numbness.","why":"The gastric mucosa atrophies and makes <b>less acid</b> (hypochlorhydria), and acid is needed to absorb <b>iron and vitamin B₁₂</b>; bacteria also overgrow (atrophic gastritis).","means":"Check the CBC and B₁₂; older adults may need supplements or injections."}],"cards":[{"t":"Inspect","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"start at the <b>RUQ, then LUQ, LLQ, RLQ</b>; examine <b>painful areas last</b>. Note asymmetry, discoloration, scars, <b>distention</b>, bulging flanks, <b>taut glistening skin</b>, skin folds, fat, pressure injuries; contour (flat, rounded, concave, distended — look across at eye level); the umbilicus; movement with breathing. A pulsation over the aorta is occasionally visible; a <b>bulging</b> pulsating <b>mass</b> is the alarm (below).","bullets":["<b>RUQ → LUQ → LLQ → RLQ</b>; <b>painful area last</b>","Asymmetry, scars, <b>distention</b>, bulging flanks, <b>taut shiny skin</b>","Contour at <b>eye level</b>; umbilicus; breathing movement","Aortic pulsation occasionally visible · <b>bulging pulsating mass</b> = alarm"],"why":"The exam order protects the findings and the patient. Listening first means the bowel sounds you hear are the patient's, not the ones your hands stirred up; examining painful areas last keeps the abdomen relaxed long enough to feel anything; and refusing to press a pulsating mass or an inflamed appendix avoids rupturing what you were trying to assess."},{"t":"Auscultate","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"with the <b>diaphragm</b> (bowel sounds are high pitched), lightly, <b>starting in the RLQ</b> (ileocecal valve), then the other quadrants. Normal: high-pitched irregular gurgles <b>5–30 per minute</b>. <b>Hypoactive or absent</b> after abdominal surgery, with <b>peritonitis</b> or <b>paralytic ileus</b>. <b>Hyperactive, loud gurgling (borborygmus)</b> with diarrhea, gastroenteritis, or <b>above a complete obstruction</b>. Listen for <b>bruits</b> over the aorta, renal and iliac arteries — an <b>aortic bruit suggests an aneurysm: don't percuss or palpate</b>, notify immediately.","bullets":["<b>Diaphragm</b>, start <b>RLQ</b>","Normal <b>5–30/min</b>","<b>Absent/hypo</b>: after surgery, <b>peritonitis</b>, <b>ileus</b>","<b>Hyper (borborygmus)</b>: diarrhea, gastroenteritis, <b>above an obstruction</b>","<b>Aortic bruit</b> → aneurysm → <b>no palpation</b>, notify"],"why":""},{"t":"Light palpation","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"four fingers together, pressing <b>½–1 inch (1.25–2.5 cm)</b> with a rotating motion, quadrant by quadrant, to find large masses and tenderness. Note <b>guarding</b> (voluntary) and <b>rigidity</b> — rigidity is involuntary and a sign of <b>peritoneal inflammation</b>. Tender areas are examined last and cautiously.","bullets":["4 fingers, <b>½–1 inch</b> deep, rotating","<b>Guarding</b> = voluntary · <b>rigidity</b> = <b>peritoneal inflammation</b>"],"why":""},{"t":"Two action alerts","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"<b>visible peristaltic waves</b> are rare — note where they start and which way they go and <b>report them</b> (possible <b>intestinal obstruction</b>). A <b>bulging, pulsating mass</b>: <b>don't touch it</b> with hands or stethoscope — possible <b>abdominal aortic aneurysm</b> — notify the provider <b>immediately</b>.","bullets":["<b>Visible peristalsis</b> → report (<b>obstruction</b>)","<b>Pulsating mass</b> → <b>don't touch</b>, notify <b>now</b> (<b>aneurysm</b>)"],"why":""}]},{"k":"ac","gist":"A finding points to the <b>organs in that quadrant</b>. Aging moves the GI tract in one direction — <b>less</b>: less acid (less <b>B₁₂ and iron</b> absorbed), less motility (<b>constipation</b>), less lipase (<b>fatty stools</b>) and a smaller liver that <b>clears drugs slowly</b>. Lab ranges shift a little with age, but a <b>critical</b> value is never normal.","terms":[{"t":"Slower drug clearance by the aging liver","see":"Usual doses causing side effects or toxicity.","why":"The liver has <b>fewer and smaller cells</b> and more fibrous tissue, so it metabolizes drugs more slowly and they <b>build up</b>.","means":"Watch older adults closely for <b>drug toxicity</b> with any drug the liver clears."},{"t":"Lab values in older adults","see":"ALT, AST, alkaline phosphatase and amylase slightly higher; total calcium slightly lower.","why":"Normal aging shifts some reference ranges slightly.","means":"A value just outside the adult range may be the older adult’s normal — compare with <b>baseline</b>, but report any <b>critical</b> value."}],"cards":[{"t":"Organs by quadrant (Table 45.1)","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"<b>RUQ</b>: most of the <b>liver</b>, <b>gallbladder</b>, <b>duodenum</b>, <b>head of the pancreas</b>, hepatic flexure, part of the ascending and transverse colon. <b>LUQ</b>: left lobe of the liver, <b>stomach</b>, <b>spleen</b>, <b>body and tail of the pancreas</b>, splenic flexure, part of the transverse and descending colon. <b>RLQ</b>: <b>cecum</b>, <b>appendix</b>, right ureter, right ovary and fallopian tube, right spermatic cord. <b>LLQ</b>: part of the descending colon, <b>sigmoid colon</b>, left ureter, left ovary and fallopian tube, left spermatic cord. <b>Midline</b>: <b>abdominal aorta</b>, <b>uterus</b> (if enlarged), <b>bladder</b> (if distended). Asymmetry or a finding in one area points to the structures beneath it.","bullets":["<b>RUQ</b>: most of <b>liver</b>, <b>gallbladder</b>, <b>duodenum</b>, <b>pancreas head</b>, hepatic flexure, part ascending + transverse colon","<b>LUQ</b>: left liver lobe, <b>stomach</b>, <b>spleen</b>, <b>pancreas body + tail</b>, splenic flexure, part transverse + descending colon","<b>RLQ</b>: <b>cecum</b>, <b>appendix</b>, right ureter, right ovary + tube, right spermatic cord","<b>LLQ</b>: part descending colon, <b>sigmoid</b>, left ureter, left ovary + tube, left spermatic cord","<b>Midline</b>: <b>aorta</b>, <b>uterus</b> (if enlarged), <b>bladder</b> (if distended)","Asymmetry → think of the organs beneath"],"why":""},{"t":"Stomach","tag":"","topic":"45-gi-changes-with-aging","text":"<b>gastric mucosa atrophies</b> → less hydrochloric acid (<b>hypochlorhydria</b>) → <b>less iron and vitamin B₁₂ absorbed</b> and <b>bacterial overgrowth</b>, which leads to <b>atrophic gastritis</b>.","bullets":["Mucosa atrophies → ↓ <b>HCl</b>","↓ <b>iron + B₁₂</b> absorption; <b>bacterial overgrowth</b> → atrophic gastritis"],"why":"Aging moves the GI tract in one direction — <b>less</b>: less acid, less motility, less lipase, less liver enzyme. So the expected findings are slower drug clearance, constipation, fatty stools and poor B₁₂ and iron absorption — never more lipase, more frequent stools or better fat absorption. Lab ranges shift a little with age too, so a value just outside the adult range can be an older adult's normal — but a <b>critical</b> value never is."},{"t":"Bowel","tag":"","topic":"45-gi-changes-with-aging","text":"<b>peristalsis slows</b> and nerve signals dull → less urge to defecate → postponed bowel movements → <b>constipation and impaction</b>.","bullets":["↓ <b>peristalsis</b>, dull nerve signals → postponed BMs → <b>constipation, impaction</b>"],"why":""},{"t":"Pancreas","tag":"","topic":"45-gi-changes-with-aging","text":"ducts dilate and vessels calcify; <b>less lipase</b> → poor fat digestion and absorption → <b>steatorrhea</b> (fatty stools).","bullets":["↓ <b>lipase</b> → poor fat digestion → <b>steatorrhea</b>"],"why":""},{"t":"Liver","tag":"","topic":"45-gi-changes-with-aging","text":"fewer and smaller liver cells, more fibrous tissue → less protein synthesis, lower enzyme activity and cholesterol synthesis → <b>drugs metabolized slowly and can build up to toxic levels</b>.","bullets":["Smaller liver, ↓ enzymes → <b>drugs build up</b> → toxicity"],"why":""},{"t":"Gut microbiota","tag":"","topic":"45-gi-changes-with-aging","text":"abnormal microbial activity with age contributes to <b>anorexia and undernutrition</b>.","bullets":["Altered microbiota → <b>anorexia, undernutrition</b>"],"why":""},{"t":"Lab values in older adults (Table 45.2)","tag":"","topic":"45-gi-changes-with-aging","text":"<b>ALT, AST, alkaline phosphatase and amylase</b> may run <b>slightly higher</b> than the adult range, and total <b>calcium slightly lower</b>. (ALT also runs slightly higher in men and African American people; AST slightly lower in females.)","bullets":["Older adults: <b>ALT, AST, alk phos, amylase</b> slightly ↑","<b>Calcium</b> slightly ↓","ALT also ↑ in men, African American people · AST ↓ in females"],"why":""}]},{"k":"ph","gist":"The alarms first: a <b>pulsating mass or aortic bruit</b> (aneurysm — stop and notify), <b>rigidity</b> (peritonitis), <b>visible peristaltic waves</b> or absent sounds with distention (obstruction or ileus). In older adults: <b>impaction</b>, undernutrition and <b>drug toxicity</b>.","terms":[],"cards":[{"t":"Is peristalsis back after surgery?","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"the most reliable sign is not bowel sounds but asking: <b>flatus within the past 8 hours</b> or <b>a stool within 12–24 hours</b>.","bullets":["Best sign: <b>flatus in 8 h</b> or <b>stool in 12–24 h</b>"],"why":""}]},{"k":"gs","gist":"Get accurate findings <b>without causing harm</b>: the right order (<b>inspect → auscultate → palpate</b>), the right scope (the nurse does <b>light palpation</b>; the provider does deep palpation and percussion), and a history that builds a <b>timeline</b> — while adjusting care for the expected changes of aging.","terms":[],"cards":[{"t":"Set-up and order","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"have the patient <b>empty the bladder</b>, lie <b>supine with knees bent</b> and arms at the sides (relaxes the abdominal muscles). Order: <b>inspect → auscultate → palpate</b> (and percuss) — so touching doesn't change bowel sounds. The generalist nurse does <b>inspection, auscultation and light palpation</b>; the provider does <b>deep palpation and percussion</b>. <b>No palpation if appendicitis or an aortic aneurysm is suspected.</b>","bullets":["<b>Empty bladder</b>, <b>supine, knees bent</b>, arms at sides","<b>Inspect → auscultate → palpate</b>","Nurse: inspect, auscultate, <b>light</b> palpation · provider: <b>deep</b> palpation, percussion","<b>No palpation</b> with suspected <b>appendicitis</b> or <b>aneurysm</b>"],"why":""},{"t":"Percussion (provider)","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"<b>tympany</b> — high, loud, musical — over air-filled bowel; <b>dullness</b> — softer, thud-like — over solid organs such as the liver. Used to size the liver (<b>hepatomegaly</b>) and spleen (<b>splenomegaly</b>: dullness in the left anterior axillary line, before it can be felt) and to detect masses, fluid and air.","bullets":["<b>Tympany</b> = air · <b>dull</b> = solid organ or fluid","<b>Hepatomegaly</b>, <b>splenomegaly</b> (dull at left anterior axillary line)"],"why":""}]},{"k":"ta","gist":"Client <b>empties the bladder</b>, lies <b>supine with knees bent</b>; inspect <b>RUQ → LUQ → LLQ → RLQ</b>, painful areas last; auscultate with the <b>diaphragm starting in the RLQ</b>; <b>light palpation ½–1 inch</b>; <b>no palpation</b> if appendicitis or an aneurysm is suspected; take the history with <b>PQRST</b> and ask about flatus and stool after surgery.","terms":[],"cards":[{"t":"Pain — PQRST","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"<b>P</b>recipitating and palliative factors (what started it, what helps or worsens it); <b>Q</b>uality (sharp, dull, burning, crushing, twisting…); <b>R</b>egion and radiation (where, does it spread or move); <b>S</b>everity 0–10 and its effect on activity; <b>T</b>iming — onset, duration, frequency, sudden or gradual, night waking, relation to <b>meals</b>, seasons.","bullets":["<b>P</b>: trigger + what helps · <b>Q</b>: quality","<b>R</b>: region, radiation · <b>S</b>: 0–10, effect on activity","<b>T</b>: onset, duration, frequency, <b>meals</b>, night waking"],"why":""},{"t":"Questions to ask (Box 45.1)","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"daily food; drugs with dose and frequency; <b>vitamins, minerals, herbs</b>; appetite and <b>weight change (intended or not)</b>; special diet; <b>trouble chewing or swallowing</b>, denture fit; heartburn — how often, what triggers and relieves it; past GI disorders and surgery; <b>family history</b>; smoking or vaping, chewing tobacco; <b>alcohol</b>; pain, diarrhea, constipation or gas and the foods involved; <b>travel</b>; usual bowel pattern; <b>laxative use</b>; pain or <b>bleeding with bowel movements</b>; change in stool; past endoscopy or colonoscopy.","bullets":["Diet, drugs, <b>supplements</b>, appetite, <b>weight change</b>","<b>Chewing/swallowing</b>, dentures, <b>heartburn</b>","Past GI disease/surgery, <b>family history</b>","Tobacco, <b>alcohol</b>, travel, <b>laxatives</b>","Bowel pattern, <b>bleeding</b>, stool change, past scopes"],"why":""}]},{"k":"eo","gist":"Findings documented <b>by quadrant</b> and compared with baseline; alarms <b>reported immediately</b>; in an older adult, a regular bowel pattern, adequate nutrition and no signs of drug toxicity.","terms":[],"cards":[{"t":"Psychosocial","tag":"","topic":"45-gi-history-and-the-abdominal-exam","text":"elimination problems are <b>personal and embarrassing</b> — ask privately and matter-of-factly about how daily life is affected. <b>Stress</b> can trigger or worsen <b>IBS</b> and other GI disorders. A cancer diagnosis brings <b>grief</b> (denial, anger, depression) — refer for support when needed.","bullets":["Embarrassing → ask privately, matter-of-factly","<b>Stress</b> → IBS flares","Cancer → <b>grief</b> → refer"],"why":""},{"t":"Who gets what","tag":"","topic":"45-gi-changes-with-aging","text":"older adults have more <b>stomach cancer</b>; younger adults more <b>inflammatory bowel disease</b>; <b>colon cancer is rising in adults under 50</b>. A recent trip abroad or <b>camping near lakes and streams</b> can explain diarrhea.","bullets":["Older: <b>stomach cancer</b> · younger: <b>IBD</b>","<b>Colon cancer rising under 50</b>","Travel or <b>camping by lakes/streams</b> → diarrhea clue"],"why":""}]}]},{"id":"gi-scope","ch":"45","sys":"Digestion & elimination","name":"Before and after a GI scope (EGD, ERCP, colonoscopy)","patient":"A 70-year-old had a colonoscopy with removal of two polyps an hour ago and now feels dizzy when sitting up.","topics":["45-imaging-and-endoscopy-egd-ercp-capsule","45-colonoscopy-sigmoidoscopy-and-colorectal"],"report":["One hour after a colonoscopy with polypectomy, the client is dizzy sitting up and pale; HR 112, BP 96/60 (baseline 138/82); a large maroon stool.","Screening colonoscopy with two polyps removed; takes aspirin, held for 5 days before.","Probable post-polypectomy bleeding with early hypovolemia.","Please evaluate now. The client is flat with the IV running; requesting a CBC, type and screen and fluid orders."],"guide":[],"nodes":[{"id":"scopes","name":"Scopes, sedation & bowel prep"}],"drugs":[{"id":"midazolam","name":"Midazolam (moderate sedation)"},{"id":"pegprep","name":"Polyethylene glycol–electrolyte bowel prep"}],"videos":[{"id":"vItktDQo-mE","title":"Preparing for an upper GI endoscopy (American Gastroenterological Association)","see":"What the patient does before the EGD — fasting, sedation, a ride home — and what happens during it"},{"id":"v-H0rfJ6caY","title":"Preparing for a capsule endoscopy (American Gastroenterological Association)","see":"Swallowing the camera capsule, wearing the recorder, and what to avoid until it passes"},{"id":"wK2imf6w8Pw","title":"What happens during a colonoscopy? (NHS)","see":"Why the bowel must be empty, the scope passing around the colon, and recovery afterward"},{"id":"KJad4HZToxc","title":"Preparing for a colonoscopy (National University Hospital, Singapore)","see":"The low-fiber diet and bowel prep the days before, and why a clear liquid stool matters"}],"steps":[{"k":"rc","gist":"During sedation: <b>RR below 10</b>, shallow breathing, low exhaled CO₂, falling SpO₂, <b>bradycardia</b>. After: <b>absent gag reflex</b> (EGD, ERCP), <b>severe abdominal pain with guarding</b>, fever, <b>falling BP with tachycardia</b>, dizziness, pallor, <b>new confusion</b> in an older adult. <b>Expected</b>: fullness, mild cramping, flatus, a sore throat, a little blood in the first stool after a biopsy.","terms":[{"t":"Hypoventilation during sedation","see":"RR below 10, shallow breathing, low exhaled CO₂ on capnography, then a falling SpO₂.","why":"<b>Midazolam, fentanyl and propofol</b> all depress the brain’s breathing center. Capnography shows rising CO₂ retention <b>before</b> the SpO₂ falls.","means":"Stimulate with a <b>sternal rub</b>, open the airway, and give reversal agents per protocol."},{"t":"Absent gag reflex after EGD or ERCP","see":"The client can’t swallow normally; no gag when the back of the throat is touched.","why":"A <b>local anesthetic spray</b> numbs the throat for the scope, and sedation dulls the reflexes further.","means":"<b>Nothing by mouth until the gag reflex returns</b> (usually 30–60 minutes) — preventing <b>aspiration</b> is the priority."},{"t":"Severe pain, guarding and fever (perforation)","see":"Sharp abdominal pain, rigid abdomen; after EGD, chest or neck pain and fever.","why":"The scope or a biopsy has <b>torn through the wall</b>, letting air and contents leak into the peritoneum or mediastinum.","means":"<b>Report immediately</b>; nothing by mouth. Mild cramping and gas are expected — rigidity and fever are not."},{"t":"Tachycardia, falling BP and dizziness (hemorrhage)","see":"Rising pulse, falling BP, light-headed, pale or ash-gray, large bloody or maroon stool; confusion in an older adult.","why":"Bleeding from a <b>polypectomy or biopsy</b> site lowers circulating volume; the heart speeds up to compensate.","means":"Keep the client flat, check vital signs, report now. A <b>small</b> amount of blood in the first stool is expected; more than that is not."},{"t":"Vasovagal bradycardia during colonoscopy","see":"Heart rate and BP drop suddenly during the procedure.","why":"Stretching the bowel with the scope and air <b>stimulates the vagus nerve</b>.","means":"<b>Atropine</b> is kept ready."},{"t":"Severe pain and fever after ERCP","see":"Hours to 2 days later: severe abdominal pain, fever, nausea and vomiting.","why":"The contrast, instruments and cutting near the <b>pancreatic duct</b> can cause <b>pancreatitis</b>, and bile-duct work can introduce infection.","means":"Teach the client to report severe pain or fever — <b>fever after ERCP can mean sepsis</b>."}],"cards":[{"t":"After (Box 45.2)","tag":"","topic":"45-colonoscopy-sigmoidoscopy-and-colorectal","text":"nothing by mouth until sedation wears off — <b>fluids once flatus is passed</b>; VS <b>every 15–30 minutes</b> until alert; <b>left lateral</b> position to pass gas; <b>side rails up</b>. Expected: <b>fullness, mild cramping and flatus</b> for hours; a <b>small amount of blood</b> in the first stool after biopsy or polypectomy. Watch for <b>perforation</b> (<b>severe abdominal pain and guarding</b>; fever may come later) and <b>hemorrhage or hypovolemic shock</b> (dizziness, light-headedness, <b>falling BP, tachycardia</b>, pallor or ash-gray skin, <b>altered mental status — may be the first sign in older adults</b>). Complications are uncommon, but <b>report excessive bleeding or severe pain</b> immediately. <b>Driver home</b>; <b>no driving, legal decisions or other work that needs focus</b> the rest of the day.","bullets":["NPO until awake; <b>fluids after flatus</b>","VS q15–30 min; <b>left side</b>; rails up","Expected: <b>fullness, cramping, gas</b>; <b>small blood</b> after polypectomy","<b>Perforation</b>: severe pain, guarding (fever later)","<b>Shock</b>: ↓ BP, ↑ HR, dizzy, pale/ash-gray, <b>confusion (older adults)</b>","Report <b>heavy bleeding or severe pain</b> now","<b>Driver</b>; no driving, <b>legal decisions</b> or focused work that day"],"why":""},{"t":"ERCP — after","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"vital signs <b>every 15 minutes</b> until stable; <b>check the gag reflex before food or fluids</b>; stop IV fluids once oral fluids stay down without nausea or vomiting. Teach the complications that can appear <b>hours to 2 days later</b>: <b>pancreatitis, cholecystitis, infection, bleeding, perforation, biloma</b> — all bring <b>severe pain</b>; <b>fever means sepsis</b>. Colicky pain and flatulence from instilled air are expected. Report pain, fever, nausea or vomiting that doesn't resolve. Driver; no driving 12–18 hours.","bullets":["VS <b>q15 min</b>; <b>gag reflex</b> before eating; stop IV once fluids stay down","Hours–<b>2 days</b> later: <b>pancreatitis</b>, cholecystitis, infection, bleeding, <b>perforation</b>, biloma → <b>severe pain</b>; <b>fever = sepsis</b>","Gas pain from air is expected","Driver, <b>no driving 12–18 h</b>"],"why":""}]},{"k":"ac","gist":"Every scope combines <b>sedatives that depress breathing</b>, a <b>throat spray that removes the gag reflex</b> (EGD, ERCP), instruments that can <b>perforate or cause bleeding</b>, and, for colonoscopy, a <b>bowel prep</b> that removes fluid and electrolytes.","terms":[{"t":"Bowel prep fluid loss","see":"Watery diarrhea from the evening before; thirst, dizziness.","why":"The prep floods the colon with fluid the gut can’t absorb, so water and <b>electrolytes</b> are lost with the stool.","means":"Electrolyte or sports drinks replace losses; <b>no red, orange or purple</b> liquids (they look like blood on camera). A poor prep hides polyps."},{"t":"Diabetes and the NPO period","see":"A client on insulin or a sulfonylurea who can’t eat before the test.","why":"Glucose-lowering drugs keep working without food.","means":"Get <b>instructions</b> for diabetes drugs during the NPO period to prevent <b>hypoglycemia</b>."},{"t":"Anticoagulants, aspirin and NSAIDs","see":"Held for several days before, if the provider directs.","why":"They impair clotting, which raises the risk of <b>bleeding</b> from biopsy and polyp sites.","means":"Medication reconciliation before every scope — the provider decides what to stop."}],"cards":[{"t":"Endoscopy — what and why","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"a flexible fiberoptic scope to see <b>bleeding, ulcers, inflammation, tumors</b>; biopsies and samples (e.g., for <b><i>Helicobacter pylori</b></i>) can be taken. Every endoscopic procedure needs <b>signed informed consent</b>.","bullets":["Sees bleeding, ulcers, inflammation, tumors; <b>biopsies</b> (e.g., <i>H. pylori</i>)","<b>Informed consent</b> every time"],"why":""},{"t":"EGD — what it can do","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"views the <b>esophagus, stomach and duodenum</b> (called esophagoscopy or gastroscopy when it focuses on one organ — Fig. 45.5); can <b>stop bleeding</b> (clips, heat, injection, topical agents), <b>dilate a stricture</b>, view gastric lesions and support a <b>celiac</b> diagnosis.","bullets":["Esophagus, stomach, duodenum (esophagoscopy, gastroscopy = one organ)","<b>Stops bleeding</b>, <b>dilates strictures</b>, biopsies (celiac)"],"why":""},{"t":"ERCP — what it does","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"views the liver, gallbladder, <b>bile ducts and pancreatic duct</b> to find the cause of <b>obstruction</b> — now mostly <b>therapeutic</b>: a cannula in the common bile duct, <b>contrast dye</b> and x-rays; a <b>papillotomy</b> (cut in the sphincter at the ampulla of Vater) to remove <b>gallstones</b>; <b>stents</b> for strictures; biopsies.","bullets":["Bile + pancreatic ducts → find <b>obstruction</b>","Mostly <b>treatment</b>: <b>papillotomy</b> to remove <b>stones</b>, <b>stents</b>, biopsies"],"why":""}]},{"k":"ph","gist":"During: <b>airway and breathing</b> (oversedation). After: <b>aspiration</b> until the gag reflex returns, then <b>perforation</b> and <b>bleeding</b>; after ERCP, <b>pancreatitis and sepsis</b>.","terms":[],"cards":[]},{"k":"gs","gist":"A safe <b>prep</b> (consent, NPO, medication plan, bowel prep), <b>continuous respiratory monitoring</b> during sedation, <b>airway protection</b> until the gag reflex returns, early recognition of complications, and discharge with <b>a driver and clear teaching</b>.","terms":[],"cards":[{"t":"EGD — before","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"avoid <b>anticoagulants, aspirin and NSAIDs</b> for several days to a week (unless essential); usual morning meds unless told otherwise; <b>diabetes → get instructions</b> (NPO); <b>NPO 6–8 hours</b> (NPO means no food, no fluids — not even water — and <b>no smoking</b>); <b>remove dentures</b>.","bullets":["Stop <b>anticoagulants, aspirin, NSAIDs</b> days–1 week before","<b>Diabetes</b> → instructions · <b>NPO 6–8 h</b> (no food, water or <b>smoking</b>) · <b>dentures out</b>"],"why":""},{"t":"Preparation","tag":"","topic":"45-colonoscopy-sigmoidoscopy-and-colorectal","text":"first-timers are often anxious — explain sedation and that pain will be controlled. <b>Stop aspirin, anticoagulants and antiplatelets</b> several days before; <b>diabetes → ask about drugs</b> for the NPO day. Bowel prep starts the <b>night before</b> (solutions taste better <b>chilled</b>); <b>clear liquids the day before</b>; <b>electrolyte or sports drinks</b> replace losses; <b>no red, orange or purple (grape) drinks or gelatin</b>; NPO for some hours before. Watery diarrhea starts about <b>an hour</b> after the prep; bisacodyl, suppositories or a small enema may be added. <b>Poor prep hides adenomas</b> and can make the test fail.","bullets":["<b>Stop aspirin, anticoagulants, antiplatelets</b>; diabetes plan","Prep <b>night before</b> (chill it); <b>clear liquids day before</b>","<b>No red, orange or purple</b> liquids/gelatin","Electrolyte drinks; diarrhea ~<b>1 h</b> after starting","<b>Poor prep → missed polyps</b>"],"why":""},{"t":"ERCP — before and during","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"prepare as for EGD: <b>NPO 6–8 hours</b>, dentures out, IV for sedation; <b>medication reconciliation</b> (anticoagulants, NSAIDs, antiplatelets, antihyperglycemics — the provider decides what stops); ask about <b>contrast reactions and allergies</b> and <b>implanted devices</b> (an <b>ICD may need to be deactivated</b> for electrocautery). <b>Left lateral</b>, then <b>prone</b>; a tilt table spreads the contrast; <b>30 minutes to 2 hours</b>.","bullets":["Like EGD: <b>NPO 6–8 h</b>, dentures out, IV","Reconcile <b>anticoagulants, NSAIDs, antiplatelets, diabetes drugs</b>","Ask <b>contrast allergy</b>, <b>ICD</b> (may be turned off)","Left side → prone; <b>30 min–2 h</b>"],"why":""}]},{"k":"ta","gist":"Before: <b>signed consent</b>, <b>NPO 6–8 hours</b>, medications per the provider, dentures out. During: watch <b>RR, depth, SpO₂ and capnography</b> — RR below 10 → <b>sternal rub</b>; atropine ready. After: VS <b>every 15–30 minutes</b> until alert, <b>side rails up</b>, <b>nothing by mouth until the gag reflex returns</b> (EGD, ERCP); after colonoscopy, <b>left side</b> to pass gas and fluids once flatus is passed; report severe pain, fever or bleeding; <b>driver home</b>, no driving for 12–18 hours.","terms":[],"cards":[{"t":"EGD — during","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"<b>moderate sedation</b> (<b>midazolam, fentanyl or propofol</b>) — these <b>depress breathing</b>; <b>atropine</b> may dry secretions; a <b>local anesthetic spray numbs the gag reflex</b> (swallowing will be hard). Head of bed up, <b>bite block</b> in, 15–30 minutes. The nurse watches <b>respiratory rate and depth, SpO₂ and capnography</b>: <b>RR below 10 or exhaled CO₂ below 20% → stimulate with a sternal rub</b>.","bullets":["<b>Moderate sedation</b> (midazolam, fentanyl, propofol) → ↓ breathing","Throat spray → <b>no gag reflex</b> · <b>bite block</b>","<b>RR &lt; 10 or exhaled CO₂ &lt; 20% → sternal rub</b>"],"why":""},{"t":"During","tag":"","topic":"45-colonoscopy-sigmoidoscopy-and-colorectal","text":"IV <b>moderate sedation</b> (midazolam, fentanyl, propofol); music may help but doesn't replace sedation. <b>Left side, knees drawn up</b>; air or <b>carbon dioxide</b> (less pain and distention) is instilled; <b>30–60 minutes</b>. <b>Atropine</b> is kept ready for <b>vasovagal bradycardia</b>. Watch RR, depth and SpO₂ — <b>RR &lt; 10 or exhaled CO₂ &lt; 20% → sternal rub</b>.","bullets":["<b>Left side, knees up</b>; CO₂ insufflation = less pain","<b>30–60 min</b>; <b>atropine</b> ready (<b>vasovagal bradycardia</b>)","<b>RR &lt; 10 / CO₂ &lt; 20% → sternal rub</b>"],"why":""},{"t":"After — prevent aspiration","tag":"","topic":"45-imaging-and-endoscopy-egd-ercp-capsule","text":"vital signs <b>every 15–30 minutes</b> until sedation wears off; <b>side rails up</b>; <b>nothing by mouth until the gag reflex returns</b> (usually <b>30–60 minutes</b>) — the <b>priority is preventing aspiration</b>. Stop IV fluids once oral fluids stay down. Watch for <b>perforation: pain, bleeding, fever</b>. Needs <b>a driver</b>; <b>no driving for 12–18 hours</b>; a hoarse voice or sore throat can last days — <b>throat lozenges</b>.","bullets":["VS <b>q15–30 min</b>, <b>rails up</b>","<b>NPO until gag reflex returns</b> (30–60 min) = <b>prevent aspiration</b>","Perforation: <b>pain, bleeding, fever</b>","<b>Driver</b>, <b>no driving 12–18 h</b>; sore throat → lozenges"],"why":""}]},{"k":"eo","gist":"Awake with RR and SpO₂ at baseline; <b>gag reflex back before</b> any oral intake; tolerating fluids; only mild cramping and gas, <b>no severe pain, fever or bleeding</b>; the client has a driver and can explain what to report.","terms":[],"cards":[{"t":"Health literacy","tag":"","topic":"45-colonoscopy-sigmoidoscopy-and-colorectal","text":"people vary widely in finding, understanding and using health information — and missed prep means missed screening. Have each patient <b>explain the test, prep and follow-up in their own words</b> (<b>teach-back</b>) and clarify gently until it's right.","bullets":["<b>Teach-back</b> for prep and follow-up"],"why":"Bowel prep works by flooding the colon with fluid the gut can't absorb, so the patient loses water and electrolytes along with stool — which is why the prep comes with electrolyte drinks, why red and purple liquids are banned (they look like blood on camera), and why diabetes medicines need a plan when the patient can't eat."}]}]},{"id":"stomatitis","ch":"46","sys":"Digestion & elimination","name":"Stomatitis and oral candidiasis","patient":"A client on chemotherapy has painful mouth ulcers and white patches that wipe off to a red base, and is barely eating or drinking.","topics":["46-stomatitis-the-tissue-integrity-exemplar"],"report":["The client has multiple oral ulcers and white plaques, pain 8/10, and has drunk less than 500 mL in 24 hours; sodium 148 mEq/L.","Receiving chemotherapy for breast cancer and a course of antibiotics.","Severe stomatitis with probable oral candidiasis and early dehydration.","Requesting an antifungal order, a topical analgesic, IV fluids and a dietitian consult."],"guide":[{"key":"46:0","name":"Healthy mouth & oral care (Boxes 46.1–46.2)"}],"nodes":[{"id":"stomatitis","name":"Stomatitis & oral cancer"},{"id":"microbes","name":"Gut microbes & infection"}],"drugs":[{"id":"nystatin","name":"Nystatin"},{"id":"clotrimazole","name":"Clotrimazole troche"},{"id":"lidocainevis","name":"Viscous lidocaine 2%"}],"videos":[],"steps":[{"k":"rc","gist":"<b>Painful ulcers</b>, redness and bleeding of the oral mucosa, <b>white plaques that wipe off to a red, sore base</b> (candidiasis), trouble <b>eating, swallowing or speaking</b>, and signs of <b>poor intake and dehydration</b>.","terms":[{"t":"Aphthous ulcers (canker sores)","see":"Painful, shallow ulcers with a red rim inside the mouth.","why":"Breaks in the <b>mucosal lining</b> expose the tissue underneath to food, acid and bacteria.","means":"<b>Pain, bleeding and infection</b> risk. Document each lesion’s location, size, color and drainage."},{"t":"White plaques that wipe off (oral candidiasis)","see":"White patches on the tongue, palate and cheeks; wiping leaves a red, sore base.","why":"<b><i>Candida albicans</b></i> overgrows when <b>antibiotics</b> kill the normal flora or immunity is low (chemotherapy, steroids, diabetes, older age).","means":"Treat with an antifungal (nystatin swish and spit, clotrimazole troches). Different from <b>leukoplakia</b>, which <b>cannot</b> be scraped off and may be precancerous."},{"t":"Dysphagia and odynophagia","see":"Trouble swallowing, pain with swallowing, food “sticking,” coughing with meals.","why":"Lesions can extend into the <b>pharynx and esophagus</b>.","means":"Risk of <b>aspiration and malnutrition</b> → screen with <b>PASS</b> and refer to speech-language pathology."},{"t":"Dry mucosa with a rising sodium and BUN","see":"Dry, sticky mouth; low intake; sodium and BUN climbing.","why":"Pain keeps the client from drinking, and fluid loss <b>dries the mucosa</b>, which worsens the lesions.","means":"Restore fluids (IV if needed) along with mouth care."},{"t":"Chemotherapy stomatitis","see":"Mouth sores starting days after chemotherapy.","why":"Chemotherapy kills <b>rapidly dividing cells</b>, including the cells that renew the mouth lining, and lowers white cells so infections take hold.","means":"Frequent gentle oral care; watch for infection; pain control so the client can eat."}],"cards":[{"t":"Assess","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"recent infections, nutrition, <b>oral hygiene</b>, trauma, stress; drugs, OTC and herbal products; past episodes; whether lesions affect <b>swallowing, eating or speaking</b>. Document each lesion's location, size, shape, odor, color and drainage. Lesions in the pharynx with <b>dysphagia or throat pain</b> may extend down the esophagus (swallowing studies). <b>Severe stomatitis and edema can obstruct the airway.</b> Assess coping with pain and body image. Watch <b>hydration</b>: fluid loss (for example, persistent vomiting with a climbing sodium and BUN) dries the mucosa — restore fluids (IV if needed) along with mouth care.","bullets":["History: hygiene, drugs, infections, stress","Lesions: <b>location, size, color, drainage</b>","Pharynx + <b>dysphagia</b> → may extend down esophagus","<b>Severe swelling can block the airway</b>","Coping, body image · <b>dehydration</b> (↑ Na, BUN) dries mucosa → <b>restore fluids</b>"],"why":"Commercial mouthwash and lemon-glycerin swabs feel cleansing but work against healing: alcohol and acid <b>dry and sting</b> the mucosa, and dryness lets organisms thrive. Saline and baking-soda rinses clean without chemical irritation and help neutralize acid — which is why the evidence-based mouth-care box replaces the familiar products."},{"t":"Candidiasis","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"<b><i>Candida albicans</b></i> overgrows when <b>long-term antibiotics</b> destroy normal flora: <b>white plaques</b> on the tongue, palate, pharynx and buccal mucosa that <b>wipe off to a red, sore base</b>. <b>Older adults</b> are at high risk (aging immunity, diabetes, malnutrition, stress, drugs that dry the mouth) — teach them <b>mouth care</b>, because preventing candidiasis is far easier than treating it.","bullets":["<b>Antibiotics</b> kill normal flora → <b><i>Candida</b></i> overgrows","<b>White plaques</b> that <b>wipe off → red, sore base</b>","High risk: <b>older adults</b>, diabetes, malnutrition, stress, dry mouth → <b>teach mouth care</b> (prevention)"],"why":""}]},{"k":"ac","gist":"Inflammation of the oral mucosa. <b>Primary</b>: aphthous ulcers, herpes simplex, trauma. <b>Secondary</b>: opportunistic viral, fungal or bacterial infection in clients who are <b>immunocompromised</b> or on <b>chemotherapy, radiation, steroids or long-term antibiotics</b>; also deficiencies of <b>B vitamins, folate, zinc or iron</b>.","terms":[],"cards":[{"t":"Definition","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"inflammation in the mouth, commonly painful <b>aphthous ulcers (\"canker sores\")</b> that break the mucosa → <b>pain, bleeding and infection</b> risk. <b>Recurrent aphthous stomatitis</b> affects about <b>20%</b> of people, more often women.","bullets":["Mouth inflammation; <b>canker sores</b> → pain, bleeding, infection","<b>Recurrent aphthous stomatitis ~20%</b>, more women"],"why":""},{"t":"Primary vs secondary","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"<b>Primary</b> (most common): aphthous (noninfectious), <b>herpes simplex</b>, traumatic ulcers. <b>Secondary</b>: opportunistic viruses, fungi or bacteria in people who are <b>immunocompromised</b> or on <b>chemotherapy, radiation or steroids</b>.","bullets":["<b>Primary</b>: aphthous, <b>herpes simplex</b>, trauma","<b>Secondary</b>: infection in <b>immunocompromised</b>, chemo, radiation, steroids"],"why":""},{"t":"Other causes","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"allergy; <b>deficiencies of B vitamins, folate, zinc or iron</b>; systemic disease; irritants such as <b>tobacco and alcohol</b>; foods that can trigger aphthous ulcers (coffee, potatoes, cheese, nuts, <b>citrus</b>, gluten); possibly a genetic tendency.","bullets":["<b>B vitamins, folate, zinc, iron</b> deficiency","<b>Tobacco, alcohol</b>; trigger foods (coffee, nuts, <b>citrus</b>, gluten)"],"why":""}]},{"k":"ph","gist":"1. <b>Impaired tissue integrity</b> from oral lesions. 2. <b>Pain</b>. Watch for <b>airway</b> swelling in severe cases, <b>aspiration</b> with dysphagia, and poor <b>nutrition and hydration</b>.","terms":[],"cards":[{"t":"Priority problems","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"1. <b>Impaired tissue integrity</b> from oral or esophageal lesions. 2. <b>Pain</b> from the lesions.","bullets":["1. <b>Tissue integrity</b> · 2. <b>Pain</b>"],"why":""},{"t":"Dysphagia action alert (PASS)","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"dysphagia risks <b>airway obstruction, aspiration pneumonia and malnutrition</b>. Watch for coughing or choking when swallowing and food \"sticking\". <b>PASS</b>: is swallowing trouble <b>P</b>robable? <b>A</b>ccount for past problems; <b>S</b>creen for signs; get a <b>S</b>peech-language pathologist referral. Report and start <b>aspiration prevention</b>.","bullets":["Dysphagia → <b>obstruction, aspiration, malnutrition</b>","<b>PASS</b>: Probable? Account for history · Screen · <b>SLP</b> referral","Start <b>aspiration precautions</b>"],"why":""}]},{"k":"gs","gist":"Keep the mouth <b>clean and moist</b>, <b>treat infection</b>, <b>relieve pain</b> so the client can eat and drink, and <b>prevent aspiration</b>.","terms":[{"t":"Why no commercial mouthwash or lemon-glycerin swabs","see":"Rinse with warm saline or baking soda instead.","why":"Alcohol and acid <b>dry and sting</b> the mucosa, and a dry mouth lets organisms thrive. Saline and baking soda clean without irritation and help neutralize acid.","means":"Use a soft brush or gauze and toothpaste without sodium lauryl sulfate."},{"t":"Viscous lidocaine","see":"2% viscous lidocaine, swish and spit, for pain.","why":"It <b>numbs the mouth and throat</b> — including the protective reflexes.","means":"The client may not feel <b>burns from hot drinks</b>, and <b>aspiration risk rises</b>. Use with caution and check swallowing."}],"cards":[{"t":"Drugs","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"for infection: <b>clotrimazole troches</b>, <b>nystatin suspension (swish and spit)</b>, <b>chlorhexidine (swish and spit)</b>. For pain (\"swish and spit\"): <b>2% viscous lidocaine</b>, diphenhydramine liquid, dyclonine lozenges, aluminum-magnesium hydroxide with simethicone, attapulgite. Teach which are <b>swish and swallow, rinse only, or taken by mouth</b>; <b>finish antibiotics</b> even after feeling better. Severe pain may need <b>opioid analgesics</b> — for any prescribed pain drug, teach its side effects and <b>no driving or tasks that need concentration</b>.","bullets":["Infection: <b>clotrimazole troches</b>, <b>nystatin swish + spit</b>, <b>chlorhexidine</b>","Pain: <b>viscous lidocaine</b>, diphenhydramine, dyclonine, antacid mixes","Teach <b>swallow vs spit vs oral</b>; <b>finish antibiotics</b>","Pain drugs (up to <b>opioids</b>): side effects, <b>no driving</b>"],"why":""}]},{"k":"ta","gist":"Oral care <b>twice daily, after meals and as needed</b> (every 2 hours if severe) with a soft brush or gauze; rinse with <b>warm saline or baking soda</b>; antifungals as ordered; topical anesthetics with caution; <b>soft, bland, cool</b> foods and fluids; screen swallowing; inspect the mouth yourself even when AP gives oral care.","terms":[],"cards":[{"t":"Oral care (Box 46.2)","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"remove dentures if the mouth is severely sore; oral hygiene <b>twice daily, after meals and as needed</b> (give the care if the patient can't) — <b>every 2 hours or more</b> if uncontrolled; <b>soft toothbrush or gauze</b>, toothpaste <b>without sodium lauryl sulfate</b>; <b>no commercial mouthwash or lemon-glycerin swabs</b>; rinse often with <b>warm saline and/or baking soda (sodium bicarbonate)</b> solution; <b>soft, bland, nonacidic</b> foods; topical analgesics or anesthetics as prescribed — <b>document their effect</b>. Oral care can be <b>delegated to AP</b> — then <b>inspect the mouth yourself</b>.","bullets":["Dentures out if very sore; care <b>2× daily + after meals</b> (do it if they can't), <b>q2h</b> if uncontrolled","<b>Soft brush</b>, SLS-free paste; <b>no mouthwash, no lemon-glycerin</b>","Rinse: <b>warm saline / baking soda</b>","<b>Soft, bland, nonacidic</b> food; topical analgesics → <b>document effect</b>","AP can do it → <b>nurse inspects</b>"],"why":""},{"t":"Viscous lidocaine alert","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"it numbs the mouth and throat — the patient <b>may not feel burns from hot drinks</b>, and as sensation falls <b>aspiration risk rises</b>. Use with extreme caution.","bullets":["Numb mouth → <b>can't feel hot liquid burns</b>","Numb throat → <b>aspiration risk</b>"],"why":""}]},{"k":"eo","gist":"Healthy mucosa <b>without inflammation or infection</b>, pain minimal, eating and drinking enough; the client can describe mouth care and self-exam.","terms":[],"cards":[{"t":"Comfort and recovery","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"<b>cool or cold liquids</b> soothe; avoid hard, spicy, salty and acidic foods; <b>high-protein</b> foods for healing; vitamin C supplements (citrus may hurt). Most stomatitis is self-limiting; ongoing pain from chemo or radiation may need a support group. <b>Evaluate</b>: healthy mucosa without inflammation or infection; minimal or no pain.","bullets":["<b>Cool liquids</b>; no spicy, salty, acidic, hard foods","<b>High protein</b> to heal","Outcome: <b>healthy mucosa, minimal pain</b>"],"why":""},{"t":"Prevention (Box 46.1)","tag":"","topic":"46-stomatitis-the-tissue-integrity-exemplar","text":"balanced diet and <b>water</b>; manage stress; <b>weekly self-exam</b> of the mouth; report pain, swelling or bite changes; <b>dentures that fit</b>; <b>brush and floss twice daily</b>; <b>no alcohol-containing mouthwash</b>; avoid drugs that inflame the mouth or reduce saliva; <b>regular dental visits</b>.","bullets":["Water, balanced diet, stress control","<b>Weekly mouth self-exam</b>; well-fitting <b>dentures</b>","<b>Brush + floss twice daily</b>; <b>no alcohol mouthwash</b>; dentist regularly"],"why":""}]}]},{"id":"oral-cancer","ch":"46","sys":"Digestion & elimination","name":"Oral cancer","patient":"A 62-year-old who smokes and drinks has a red, raised sore on the side of his tongue that hasn’t healed in a month, and he is losing weight.","topics":["46-oral-tumors-oral-cancer-and-salivary-gla"],"report":["Eight hours after a partial glossectomy and neck dissection, the client has new inspiratory stridor; RR 28, SpO₂ 90%, copious oral secretions.","Squamous cell carcinoma of the tongue; long-term smoker.","Airway compromise from edema or secretions.","I have called the Rapid Response Team, raised the head of the bed, suctioned with a Yankauer and applied oxygen. Please come evaluate now."],"guide":[],"nodes":[{"id":"stomatitis","name":"Stomatitis & oral cancer"}],"drugs":[],"videos":[],"steps":[{"k":"rc","gist":"A <b>painless red, raised or eroded lesion</b> or patch that <b>doesn’t heal in 2 weeks</b>, a lump or thickening in the cheek, mouth bleeding, <b>difficulty chewing or swallowing</b>, thick or absent saliva and <b>unplanned weight loss</b>. Precancerous: <b>leukoplakia</b> and <b>erythroplakia</b>.","terms":[{"t":"A lesion that doesn’t heal in 2 weeks","see":"Red, raised or eroded sore, often painless at first.","why":"Cancer cells <b>multiply without the normal controls</b>, so the tissue keeps growing instead of healing. Early lesions often don’t hurt, so people delay care.","means":"Any mouth lesion lasting <b>more than 2 weeks</b> needs further assessment and a biopsy."},{"t":"Leukoplakia","see":"Thick white patch that <b>cannot be scraped off</b>.","why":"The lining thickens in response to <b>chronic irritation</b> — tobacco, poorly fitting dentures, cheek chewing.","means":"Usually benign, but on the <b>lips or tongue</b> it can become cancer. Ask about tobacco and offer cessation help."},{"t":"Erythroplakia","see":"Red, velvety patch on the floor of the mouth, tongue or palate.","why":"Abnormal, <b>precancerous</b> changes in the lining.","means":"Hard to tell from inflammation — refer for evaluation."},{"t":"Dysphagia and weight loss","see":"Trouble chewing and swallowing; losing weight without trying.","why":"The tumor interferes with the tongue and throat movements needed to chew and swallow.","means":"Risk of <b>aspiration and malnutrition</b> — swallow study, dietitian, possibly a feeding tube."},{"t":"Stridor or wheezes after surgery","see":"High-pitched sound on breathing in; wheezes; dyspnea.","why":"<b>Stridor</b> = partial airway obstruction from swelling or secretions; <b>wheezes</b> can mean aspiration.","means":"<b>Airway is the priority</b> — raise the head of the bed, suction, call for help."}],"cards":[{"t":"Key features (Box 46.3)","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"mouth <b>bleeding</b>, poor appetite, <b>difficulty chewing or swallowing</b>, <b>unplanned weight loss</b>, <b>thick or absent saliva</b>, a <b>painless red, raised or eroded lesion</b>, a lump or thickening in the cheek.","bullets":["<b>Bleeding</b>, chewing/swallowing trouble, <b>weight loss</b>","Thick or no saliva · <b>painless red raised lesion</b> · cheek lump"],"why":""},{"t":"Erythroplakia","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"<b>red, velvety</b> patches on the floor of the mouth, tongue, palate and mandibular mucosa — <b>precancerous</b>, and hard to tell from inflammation.","bullets":["<b>Red, velvety</b>, <b>precancerous</b>"],"why":""},{"t":"Leukoplakia","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"thick <b>white</b> patches firmly attached — <b>can't be scraped off</b>; slightly raised, sharply rounded. Mostly benign, but lesions on the <b>lips or tongue can become cancer</b>. Linked to <b>tobacco</b> and long-term irritation (<b>poorly fitting dentures, cheek chewing, broken teeth</b>). <b>Oral hairy leukoplakia</b> appears with immune compromise — an early sign of <b>HIV</b>, or with Epstein-Barr virus. Ask every patient about tobacco and offer counseling and treatment.","bullets":["<b>White</b>, <b>can't scrape off</b>","Lips/tongue can turn <b>cancerous</b>; <b>tobacco</b>, bad dentures, cheek chewing","<b>Hairy leukoplakia</b> → <b>HIV</b> (early) or EBV"],"why":""}]},{"k":"ac","gist":"Most are <b>squamous cell carcinomas</b> after 40, driven by <b>tobacco, alcohol and HPV</b>; <b>basal cell</b> cancer of the lip from sun. Diagnosed by <b>biopsy</b>, staged with CT or MRI.","terms":[],"cards":[{"t":"Types","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"most are <b>squamous cell carcinomas</b> of the lips, tongue, buccal mucosa and oropharynx after <b>40</b>: a <b>red, raised, eroded</b> lesion, or any lesion <b>not healed in 2 weeks</b>, or a lump in the cheek → assess further. <b>Basal cell</b> cancer on the <b>lips</b> from <b>sun</b>: a raised scab that becomes an ulcer with a <b>pearly border</b>; rarely metastasizes. <b>Kaposi sarcoma</b>: painless purple, red or brown nodule (palate, gums, tongue) — associated with <b>AIDS</b>.","bullets":["<b>Squamous</b> (most): <b>red, raised, eroded</b>; <b>not healed in 2 weeks</b>","<b>Basal cell</b> on lips (<b>sun</b>), <b>pearly border</b>","<b>Kaposi</b>: purple nodule, <b>AIDS</b>"],"why":""},{"t":"Prevention and risk","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"<b>dentist at least twice a year</b> with an oral cancer screening (inspecting and palpating the mouth); <b>stop tobacco and alcohol</b>; protect lips from the <b>sun</b>; avoid <b>HPV</b> (sexually transmitted). <b>White men</b> have much higher HPV-related oropharyngeal cancer than other men — advocate <b>HPV vaccination and regular oral cancer screening for men</b>. Long industrial exposure to <b>polycyclic aromatic hydrocarbons (PAH)</b> — riskier still with HPV — and periodontal disease with jaw bone loss raise risk. <b>Genetics</b>: ask at-risk patients about <b>any history of cancer</b>; oral cancers often carry a <b>TP53</b> mutation (the gene for p53, a protein that regulates cell division and prevents tumors).","bullets":["<b>Dentist 2×/year</b> (inspect + palpate); no tobacco/alcohol; <b>lip sun protection</b>; avoid <b>HPV</b>","<b>White men</b>: ↑ HPV oropharyngeal cancer → <b>vaccinate + screen men</b>","<b>PAH</b> exposure (worse with HPV), gum disease with jaw bone loss","Genetics: ask about <b>any cancer history</b>; <b>TP53</b> (p53 controls cell division)"],"why":""},{"t":"Diagnose","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"inspect every area with gloves, tongue blade and penlight; the provider palpates <b>cervical nodes</b>. <b>Needle or incisional biopsy</b> (excisional removes a small lesion completely); <b>CT or MRI</b> for spread and staging (MRI shows nerve involvement and tongue tumor thickness).","bullets":["Gloves, blade, penlight; provider feels <b>neck nodes</b>","<b>Biopsy</b>; <b>CT/MRI</b> for staging"],"why":""}]},{"k":"ph","gist":"<b>Airway first</b> (edema, secretions, aspiration), then <b>aspiration risk</b>, <b>nutrition</b>, pain, and the effects on <b>speech and self-image</b>.","terms":[],"cards":[{"t":"Airway first","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"<b>airway maintenance is the priority</b>. Assess dyspnea, rate and depth, <b>wheezes</b> (aspiration), <b>stridor</b> (partial obstruction). Promote <b>deep breathing</b> for an effective cough. <b>Semi- or high-Fowler</b>; fluids to thin secretions if the gag reflex is intact; chest physiotherapy; <b>oral suction with a Yankauer (tonsil tip)</b>, teaching family to suction. <b>Steroids</b> for edema, antibiotics for infection, <b>cool mist face tent</b>.","bullets":["<b>Airway = priority</b>: dyspnea, <b>wheeze</b>, <b>stridor</b>; <b>deep breathing</b> to cough","<b>Semi/high-Fowler</b>, fluids if gag intact, <b>Yankauer suction</b>","<b>Steroids</b> (edema), antibiotics, <b>cool mist</b>"],"why":""}]},{"k":"gs","gist":"Treat the tumor (excision, radiation, chemotherapy), <b>maintain the airway</b>, <b>prevent aspiration</b>, maintain <b>nutrition</b> (a gastrostomy tube if needed), and support <b>communication and self-image</b> with the team (speech therapist, dietitian, social worker).","terms":[],"cards":[{"t":"Treatment","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"excision, radiation, cryosurgery, chemotherapy and targeted therapy, often combined (multimodal); <b>Mohs surgery</b> for basal cell cancer of the lip. Surgeries include dental extraction before radiation, <b>glossectomy</b> (tongue), <b>gastrostomy tube</b>, <b>laryngectomy</b>, mandible or maxilla resection, microsurgical or flap reconstruction, <b>neck dissection</b>, <b>tracheostomy</b>, tumor resection with margins. Good <b>oral care before</b> surgery lowers complications. After a small excision: <b>liquids for a day</b>, then advance; keep follow-up.","bullets":["Surgery, radiation, chemo — often <b>combined</b>; <b>Mohs</b> for lip BCC","Glossectomy, <b>G-tube</b>, laryngectomy, jaw resection, <b>neck dissection</b>, <b>tracheostomy</b>","Oral care <b>before</b> surgery; small excision → liquids 1 day"],"why":""},{"t":"Speech, eating and self-image","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"oral tumors and their treatment can impair <b>chewing, swallowing and speaking</b>, and pain limits daily activities and self-care. Removing the <b>tongue or part of the jaw</b>, or a <b>tracheostomy</b>, also changes appearance and speech → assess <b>self-image</b>, the <b>support system</b>, and educational, cultural and spiritual needs. The team includes a <b>speech therapist</b>, registered dietitian nutritionist, social worker and a spiritual leader if the patient wishes.","bullets":["Tumor/treatment → trouble <b>chewing, swallowing, speaking</b>; pain limits self-care","Tongue/jaw removal, <b>tracheostomy</b> → <b>body image</b> + speech change","Assess <b>self-image, support system</b>, cultural/spiritual needs","Team: <b>speech therapist</b>, RDN, social worker, spiritual leader"],"why":""}]},{"k":"ta","gist":"<b>Semi- or high-Fowler</b>, deep breathing, <b>Yankauer suction</b> at the bedside (teach the family); check the <b>gag reflex before any fluids</b>; thickened liquids and a swallow study; oral care <b>every 2 hours</b> with an ultrasoft brush and saline or baking soda — <b>no foam swabs</b>.","terms":[],"cards":[{"t":"Aspiration precautions","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"check <b>LOC, gag reflex (before any fluids) and swallowing</b>; upright; suction at the bedside; AP feed <b>small amounts</b>; family and visitors <b>ask the nurse before giving food or drink</b>; <b>thickened liquids</b> and a swallow study with the <b>SLP</b> as needed.","bullets":["Check <b>LOC + gag reflex before fluids</b>","Upright, <b>suction ready</b>, <b>small bites</b>","Visitors ask before feeding; <b>thickened liquids</b>, <b>SLP</b>"],"why":""},{"t":"Oral care","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"every <b>2 hours</b>; <b>soft-bristle or ultrasoft \"chemobrush\"</b> (especially with low platelets); <b>no foam swabs</b> (don't remove plaque, dry the mouth); <b>water-based lubricant</b> for lips and mucosa; <b>no alcohol mouthwash or lemon-glycerin</b>; rinse with <b>baking soda or warm saline</b>.","bullets":["<b>q2h</b>; <b>ultrasoft \"chemobrush\"</b> (low platelets)","<b>No foam swabs</b>, no alcohol mouthwash, no lemon-glycerin","<b>Water-based</b> lubricant; saline/baking soda rinses"],"why":""}]},{"k":"eo","gist":"<b>Patent airway</b>, no aspiration, weight stable, able to communicate needs; the client inspects the mouth daily and keeps follow-up visits.","terms":[],"cards":[{"t":"At home (Box 46.4)","tag":"","topic":"46-oral-tumors-oral-cancer-and-salivary-gla","text":"<b>inspect the mouth daily</b>; meticulous oral hygiene with an <b>ultrasoft brush</b> cleaned after each use; follow-up visits; <b>thickened liquids</b> for dysphagia; soft foods for stomatitis; <b>saliva substitute</b> as prescribed.","bullets":["<b>Daily mouth check</b>; ultrasoft brush","Thickened liquids; soft foods; <b>saliva substitute</b>"],"why":""}]}]},{"id":"gerd","ch":"46","sys":"Digestion & elimination","name":"GERD, hiatal hernia and fundoplication","patient":"A 50-year-old with obesity has heartburn after meals that is worse lying down, a cough at night and a hoarse voice in the mornings.","topics":["46-gerd-the-nutrition-exemplar","46-treating-gerd-diet-lifestyle-drugs-proce","46-hiatal-hernia-and-fundoplication-care"],"report":["The first day after an open fundoplication: the NG tube has had no drainage for 2 hours; the client is nauseated and retching with a distended abdomen.","Large hiatal hernia with severe GERD; open fundoplication yesterday.","Possible obstructed NG tube — retching puts the wrap’s sutures at risk.","Requesting evaluation and orders for the NG tube (I have not repositioned or irrigated it) and an antiemetic."],"guide":[{"key":"46:1","name":"GERD"},{"key":"46:2","name":"Hiatal hernia"}],"nodes":[{"id":"gerd","name":"GERD, hiatal hernia & the esophagus"},{"id":"acid","name":"Acid & the proton pump"}],"drugs":[{"id":"omeprazole","name":"Omeprazole"},{"id":"famotidine","name":"Famotidine"},{"id":"almag","name":"Magnesium hydroxide with aluminum hydroxide"}],"videos":[{"id":"jP-9AD0wMOk","title":"What causes heartburn? (TED-Ed)","see":"The lower esophageal sphincter failing to close and acid washing up into a lining that can’t resist it"},{"id":"TdK0jRFpWPQ","title":"Heartburn, acid reflux, GERD (Mayo Clinic)","see":"When heartburn becomes GERD, and the lifestyle steps and drugs that treat it"},{"id":"SXvTpUojXeA","title":"Hiatal hernia repair with Nissen fundoplication (animation)","see":"The stomach pulled back below the diaphragm, the opening narrowed, and the fundus wrapped around the esophagus"}],"steps":[{"k":"rc","gist":"<b>Pyrosis (heartburn)</b> and <b>dyspepsia</b> 20 minutes to 2 hours after meals, <b>regurgitation</b>, <b>water brash</b>, <b>dysphagia or odynophagia</b> — worse <b>lying down, bending or straining</b>, relieved by sitting up or antacids. Atypical: <b>chest pain</b>, <b>night cough, wheezing, morning hoarseness</b>, dental caries; older adults: dysphagia, vomiting, anemia.","terms":[{"t":"Pyrosis (heartburn)","see":"Burning behind the sternum after meals or lying down.","why":"A weak <b>lower esophageal sphincter (LES)</b> lets <b>acid and pepsin</b> flow back into the esophagus, which has no protective lining against them.","means":"Follows <b>gravity and pressure</b> — upright position, small meals and antacids relieve it."},{"t":"Regurgitation and water brash","see":"Sour fluid coming up into the mouth; sudden flood of saliva in the throat.","why":"Stomach contents reach the throat; <b>water brash</b> is reflex salivation as the body tries to wash down and neutralize the acid.","means":"Regurgitation can lead to <b>aspiration</b> — listen for crackles."},{"t":"Night cough, wheezing and morning hoarseness","see":"Coughing or wheezing at night, new asthma, hoarse voice in the morning.","why":"Lying flat lets reflux reach the <b>larynx and airways</b>, where acid irritates the vocal cords and bronchi.","means":"Raise the head of the bed on blocks or a wedge; <b>nothing within 3 hours of bedtime</b>."},{"t":"Chest pain that mimics angina","see":"Severe pain spreading to the neck, jaw or back.","why":"The esophagus and heart share <b>nerve pathways</b>, so the brain can’t tell them apart.","means":"<b>Rule out a cardiac cause first.</b> Many clients come to the ED fearing a heart attack — stay with them."},{"t":"Progressive dysphagia","see":"Food sticking, worse over time.","why":"Chronic acid injury heals with <b>scar tissue</b> that narrows the esophagus (<b>stricture</b>).","means":"Report it — it can also signal <b>Barrett’s esophagus or cancer</b>."},{"t":"Fullness or breathlessness after eating","see":"Feeling of suffocation after meals; chest pain that mimics angina; worse lying down.","why":"In a <b>paraesophageal hiatal hernia</b>, part of the stomach sits in the chest and <b>presses on the lungs</b> when full.","means":"Risk of <b>volvulus, obstruction and strangulation</b> — sudden severe pain is an emergency."}],"cards":[{"t":"Ask","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"heartburn or <b>atypical chest pain</b>; new <b>asthma</b>, <b>morning hoarseness</b>, <b>coughing or wheezing at night</b> (reflux reaching the pharynx or lungs); <b>dysphagia</b> and <b>odynophagia</b> (painful swallowing).","bullets":["Heartburn, <b>atypical chest pain</b>","New <b>asthma</b>, <b>morning hoarseness</b>, <b>night cough/wheeze</b>","<b>Dysphagia, odynophagia</b>"],"why":"Every GERD symptom follows gravity and pressure. Bending, straining, a big meal and lying flat all push stomach contents up against a weak sphincter; sitting up, a small meal and an antacid all reverse it. That is why the most effective treatments are not drugs at all but <b>positions, portions and timing</b>."},{"t":"Key features (Box 46.6)","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"the main symptoms are <b>dyspepsia</b> (indigestion) and <b>regurgitation</b> (can cause aspiration or bronchitis). Also <b>water brash</b> (sudden salivation — fluid in the throat <b>without</b> a sour taste), <b>pyrosis</b> (heartburn), epigastric or general abdominal pain, chest pain, <b>globus</b> (something in the throat), pharyngitis, <b>dental caries</b>, belching, flatulence, nausea, bloating. Severe GERD: discomfort after <b>every meal for 20 minutes to 2 hours</b>, <b>worse lying down, bending or straining</b>, <b>relieved by fluids, antacids or sitting up</b>. Severe pain may radiate to the <b>neck, jaw or back like cardiac pain</b>. Listen for <b>crackles</b> (aspiration).","bullets":["Main: <b>dyspepsia + regurgitation</b>","<b>Water brash</b> (no sour taste), <b>pyrosis</b>, <b>globus</b>, dental caries, belching","After meals <b>20 min–2 h</b>; <b>worse lying/bending</b>; <b>better upright, fluids, antacids</b>","Can mimic <b>cardiac pain</b> · listen for <b>crackles</b>"],"why":""},{"t":"Older adults","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"often <b>atypical</b>: <b>dysphagia, vomiting, anorexia, anemia, cough, respiratory problems</b> instead of heartburn; more complications (comorbidity, polypharmacy) → report so a GERD workup can be considered.","bullets":["Older adults: <b>dysphagia, vomiting, anorexia, anemia, cough</b> instead of heartburn"],"why":""},{"t":"Hiatal hernia — key features","tag":"","topic":"46-hiatal-hernia-and-fundoplication-care","text":"<b>sliding</b>: heartburn, regurgitation, chest pain, dysphagia, belching. <b>Paraesophageal</b>: <b>fullness, breathlessness or a feeling of suffocation after eating</b>, chest pain that <b>mimics angina</b>, worse <b>lying down</b>. <b>Most</b> are asymptomatic; when symptoms occur they usually worsen <b>after meals or lying flat</b>.","bullets":["<b>Most asymptomatic</b>; worse after meals, lying flat","<b>Sliding</b>: heartburn, regurgitation, chest pain, dysphagia, belching","<b>Paraesophageal</b>: <b>fullness, breathlessness, suffocation after meals</b>, angina-like pain, worse lying down"],"why":""}]},{"k":"ac","gist":"A weak or inappropriately relaxed <b>LES</b> lets acid and pepsin reflux, injuring the esophagus (<b>esophagitis</b>). <b>Raised abdominal pressure</b> (obesity, pregnancy, tight clothing, bending) and slow stomach emptying push contents up; a <b>sliding hiatal hernia</b> weakens the barrier. Chronic GERD → <b>stricture</b> and <b>Barrett’s esophagus</b>.","terms":[{"t":"Barrett’s esophagus","see":"Found on EGD with biopsy.","why":"Repeated acid injury makes the esophageal lining <b>change into a more acid-resistant, intestine-like lining</b> (metaplasia).","means":"<b>Premalignant</b> — it raises the risk of esophageal adenocarcinoma, so it needs regular surveillance."},{"t":"Ambulatory esophageal pH monitoring","see":"A catheter or capsule records pH for 24–48 hours while the client keeps a diary.","why":"Measures how often and how long acid is in the esophagus, matched to symptoms.","means":"The <b>most accurate</b> test for GERD; manometry only checks function before surgery."}],"cards":[{"t":"Definition","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"<b>gastroesophageal reflux (GER)</b> is backward flow of stomach contents (<b>regurgitation</b>); <b>GERD</b> is the chronic, more serious disease from <b>persistent</b> reflux. The <b>most common upper GI disorder</b> in the US, affecting <b>18–28%</b> of North American adults — most often middle-aged and older adults, but increasingly <b>younger</b> adults, so don't rule it out by age. It may cause <b>no symptoms at first</b>.","bullets":["<b>GER</b> = backflow · <b>GERD</b> = chronic disease from persistent reflux","<b>Most common upper GI disorder</b>; <b>18–28%</b> of adults; mostly middle-aged/older but rising in <b>younger</b> adults","May be <b>silent</b> at first"],"why":""},{"t":"Risk factors","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"<b>overweight and obesity</b> (raised abdominal pressure) are the biggest; <b><i>H. pylori</b></i> (gastritis → slow emptying); <b>NG tubes</b>; pregnancy, tight belts or binders, bending over, ascites; <b>obstructive sleep apnea</b> (night reflux); strong genetic link plus lifestyle.","bullets":["<b>Obesity</b> (biggest), <b><i>H. pylori</b></i>, <b>NG tube</b>","Pregnancy, tight belts, bending, ascites","<b>Sleep apnea</b>; genetics + lifestyle"],"why":""},{"t":"Complications","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"<b>reflux esophagitis</b>; <b>Barrett's esophagus</b> (premalignant); <b>stricture</b> with progressive dysphagia; <b>asthma, laryngitis, dental decay, cardiac disease</b>; <b>hemorrhage</b>; <b>aspiration pneumonia</b>.","bullets":["<b>Esophagitis</b> → <b>Barrett's</b> (premalignant), <b>stricture</b>","Asthma, laryngitis, <b>dental decay</b>, bleeding, <b>aspiration</b>"],"why":""},{"t":"Diagnosis","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"usually from <b>symptoms and history</b>. <b>EGD</b> (with biopsy, moderate sedation, needs a driver) for atypical symptoms. <b>Ambulatory esophageal pH monitoring is the most accurate</b>: a nasal catheter or wireless capsule on the distal esophagus records pH for <b>24–48 hours</b> while the patient keeps a <b>diary</b> of activities and symptoms. <b>Manometry</b> (pressure of the LES and peristalsis) can't diagnose GERD alone — it checks function <b>before surgery</b>.","bullets":["Usually <b>symptoms + history</b>","<b>EGD</b> for atypical symptoms","<b>pH monitoring = most accurate</b> (24–48 h + <b>diary</b>)","<b>Manometry</b> before surgery (not diagnostic alone)"],"why":""},{"t":"Hiatal hernia — types","tag":"","topic":"46-hiatal-hernia-and-fundoplication-care","text":"the stomach pushes through the <b>esophageal hiatus</b> of the diaphragm into the chest. <b>Type I — sliding</b> (most common): the GE junction and part of the fundus slide up and down with position and pressure; main concern is <b>reflux</b> (volvulus and obstruction are rare). <b>Types II–IV — paraesophageal (rolling)</b>: II, the fundus rolls up <b>beside</b> the esophagus while the GE junction stays put; III, both herniate; IV, colon, spleen, pancreas or small bowel in the sac. High risk of <b>volvulus, obstruction and strangulation</b>; slow venous oozing causes <b>iron deficiency anemia</b>.","bullets":["Stomach pushes through the <b>hiatus</b> into the chest","<b>Sliding (I, most common)</b> → <b>reflux</b>","<b>Paraesophageal (II–IV)</b> → <b>volvulus, obstruction, strangulation</b>, <b>iron deficiency anemia</b>"],"why":""}]},{"k":"ph","gist":"1. <b>Acute pain</b> from reflux. 2. <b>Potential for compromised nutrition</b> from food choices. Also <b>aspiration</b>. After fundoplication: <b>lungs</b>, protecting the <b>wrap</b> (NG tube, no retching), and dysphagia.","terms":[],"cards":[{"t":"Priority problems","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"1. <b>Potential for compromised nutrition</b> from food choices. 2. <b>Acute pain</b> from reflux.","bullets":["1. <b>Nutrition</b> · 2. <b>Pain</b>"],"why":""},{"t":"The frightened patient","tag":"","topic":"46-gerd-the-nutrition-exemplar","text":"many come to the ED <b>fearing a heart attack</b> — stay with them until the diagnosis is clear and support coping.","bullets":["ED visit fearing <b>MI</b> → <b>stay with them</b>"],"why":""}]},{"k":"gs","gist":"<b>Positions, portions and timing</b> first; <b>acid suppression</b> (antacids, H₂ blockers, PPIs); stop drugs that lower LES pressure; <b>surgery</b> (laparoscopic Nissen fundoplication, LINX, Stretta) when medical treatment fails or the hiatal hernia is large.","terms":[{"t":"Long-term PPI use","see":"Years of omeprazole or pantoprazole.","why":"Stomach acid frees <b>calcium, iron and B₁₂</b> from food and kills swallowed microbes. Switching it off for years reduces absorption and defense.","means":"Watch for <b>fractures</b> (especially older adults), deficiencies and infections; reassess the need regularly and step down slowly."}],"cards":[{"t":"The three classes","tag":"","topic":"46-treating-gerd-diet-lifestyle-drugs-proce","text":"<b>antacids</b>, <b>histamine (H₂) blockers</b> and <b>proton pump inhibitors (PPIs)</b> — the same drugs used for peptic ulcer disease (Table 47.1). They <b>inhibit acid secretion, speed stomach emptying, or protect the mucosa</b>. IV <b>esomeprazole or pantoprazole</b> prevent <b>stress ulcers</b> after surgery. PPIs heal tissue fast but symptoms <b>recur</b> when stopped; long-term use can <b>mask</b> reflux symptoms, and stopping the drug shows whether reflux has resolved.","bullets":["<b>Antacids, H₂ blockers, PPIs</b>","Lower acid · speed emptying · protect mucosa","IV PPI → <b>stress ulcer</b> prevention","Symptoms <b>recur</b> when PPIs stop; long-term use can <b>mask</b> reflux"],"why":""},{"t":"Drugs that cause reflux","tag":"","topic":"46-treating-gerd-diet-lifestyle-drugs-proce","text":"review with the provider: <b>oral contraceptives, anticholinergics, sedatives, NSAIDs, nitrates, calcium channel blockers</b> all lower LES pressure.","bullets":["Review: <b>contraceptives, anticholinergics, sedatives, NSAIDs, nitrates, CCBs</b>"],"why":""},{"t":"Laparoscopic Nissen fundoplication (LNF)","tag":"","topic":"46-treating-gerd-diet-lifestyle-drugs-proce","text":"the minimally invasive <b>standard surgery</b> for severe GERD — only a small share of patients need it: reflux that fails medical treatment, high-volume reflux, drug intolerance or nonadherence, a <b>large hiatal hernia</b>, sometimes reflux-related respiratory symptoms. The <b>fundus is wrapped around the lower esophagus</b>. Keep following the antireflux diet and antacids — <b>recurrence is common</b>. (Care is in the hiatal hernia topic.)","bullets":["<b>Standard surgery</b>: fundus <b>wrapped around</b> lower esophagus","For: drugs fail, high-volume reflux, intolerance/nonadherence, <b>large hiatal hernia</b>","Keep antireflux habits — <b>recurrence common</b>"],"why":"PPIs block the final step of acid making — the proton pump in every parietal cell — which is why they heal esophagitis faster than any other drug. But stomach acid also frees calcium, iron and B₁₂ from food and kills swallowed microbes; switch it off for years and the bill comes due as fractures, deficiencies and infections."}]},{"k":"ta","gist":"<b>4–6 small meals</b>, eat slowly; <b>nothing within 3 hours of bedtime</b>; <b>upright at least 1 hour after eating</b>; raise the head of the bed with blocks or a wedge; avoid peppermint, chocolate, fatty foods, caffeine, carbonated drinks, alcohol and tobacco; lose weight; loose clothing. After fundoplication: HOB ≥ 30°, <b>secure the NG tube — never reinsert or reposition it</b>, keep it patent, deep breathing, supervise the first oral feedings.","terms":[],"cards":[{"t":"Meals and sleep","tag":"","topic":"46-treating-gerd-diet-lifestyle-drugs-proce","text":"<b>4–6 small meals</b> instead of 3 large ones (large meals raise stomach pressure and slow emptying); <b>eat slowly and chew well</b> (less belching); <b>nothing within 3 hours of bedtime</b> (night reflux does the most damage, and regurgitation lying down risks <b>aspiration</b>); <b>sleep propped up</b> — <b>blocks under the head of the bed or a wedge pillow</b>, not just extra pillows.","bullets":["<b>4–6 small meals</b>; eat slowly","<b>No eating within 3 h of bedtime</b>","<b>HOB on blocks or a wedge pillow</b>"],"why":""},{"t":"Food choices","tag":"","topic":"46-treating-gerd-diet-lifestyle-drugs-proce","text":"GERD is <b>chronic</b> — teaching is the nurse's most important role (treat it more aggressively in older adults). Work with the <b>RDN</b>. <b>Avoid foods that lower LES pressure or irritate</b>: <b>peppermint, chocolate, fatty (especially fried) foods, caffeine, carbonated drinks</b>; limit <b>spicy and acidic</b> foods (orange juice, tomatoes) until healed. Diet apps can help.","bullets":["<b>Chronic</b> → teaching is key; work with <b>RDN</b>","Avoid <b>peppermint, chocolate, fried/fatty food, caffeine, carbonated drinks</b>","Limit <b>spicy + acidic</b> (OJ, tomatoes) until healed"],"why":""},{"t":"Habits","tag":"","topic":"46-treating-gerd-diet-lifestyle-drugs-proce","text":"<b>no alcohol or tobacco</b> (refer to cessation programs); <b>weight loss</b> if needed; <b>upright at least 1 hour after eating</b>; no <b>heavy lifting, straining or working bent over</b>; <b>loose, nonrestrictive clothing</b>. People with obesity often have sleep apnea too — <b>CPAP</b> reduces night reflux. These habits work and can bring prompt relief in uncomplicated cases. Teach the warning signs of complications such as <b>stricture</b> (worsening dysphagia) and <b>Barrett's esophagus</b>; an RDN or support group can help with meal planning.","bullets":["<b>No alcohol, no tobacco</b>; lose weight","<b>Upright ≥ 1 h after eating</b>","No <b>lifting, straining, bending</b>; <b>loose clothes</b>","<b>CPAP</b> helps night reflux","Habits bring <b>prompt relief</b>; teach signs of <b>stricture, Barrett's</b>; RDN/support group"],"why":""},{"t":"The NG tube","tag":"","topic":"46-hiatal-hernia-and-fundoplication-care","text":"a <b>large-bore NG tube</b> keeps the wrap from becoming too tight. Drainage is <b>dark brown (old blood) at first</b>, then <b>yellowish green within 8 hours</b>. Check placement every <b>4–8 hours</b> and <b>anchor it well</b> — <b>reinserting it could perforate the fundoplication</b>. Keep it <b>patent</b> so the stomach stays decompressed (vomiting or retching can rupture the sutures). Frequent <b>oral care</b>; accurate I&amp;O.","bullets":["Large-bore NG: drainage <b>dark brown → yellow-green in 8 h</b>","Placement <b>q4–8h</b>; <b>anchor well</b> — <b>reinsertion can perforate the wrap</b>","Keep <b>patent</b> (no retching/vomiting); oral care; I&amp;O"],"why":"A fundoplication is a sutured cuff around the esophagus, and everything after surgery protects it: the large NG tube sizes the wrap and keeps the stomach empty so retching can't tear it, the tube is never blindly reinserted because the tip could pierce it, and coughing, straining and vomiting are prevented because each is a sudden pressure spike against fresh sutures."},{"t":"After LNF (Box 46.9)","tag":"","topic":"46-hiatal-hernia-and-fundoplication-care","text":"bleeding and infection are possible but uncommon — watch for them, and teach: <b>soft diet about a week</b> (no carbonated drinks, tough foods, raw vegetables); <b>antireflux drugs at least a month</b>; <b>no driving for a week</b> or on opioids; <b>walk daily, no heavy lifting</b>; remove small dressings and <b>shower at 2 days</b>, leave closure strips until <b>day 10</b>; wash incisions with soap and water, report redness or drainage; report <b>fever &gt; 101°F (38.3°C)</b> — <b>&gt; 100°F (37.8°C) if older than 65</b> — nausea, vomiting, uncontrollable bloating or pain; follow-up in <b>3–4 weeks</b>.","bullets":["Watch for <b>bleeding, infection</b> (uncommon)","<b>Soft diet ~1 week</b>; antireflux drugs <b>≥ 1 month</b>","<b>No driving 1 week</b>; walk, <b>no lifting</b>","Shower at <b>2 days</b>; strips stay till <b>day 10</b>","Report <b>fever &gt; 101°F</b> (<b>&gt; 100°F if &gt; 65</b>), vomiting, bloating, pain"],"why":""}]},{"k":"eo","gist":"Symptoms controlled, <b>no aspiration</b>, eating comfortably; the client follows the diet and position changes and reports <b>worsening dysphagia</b>. After surgery: eating without persistent dysphagia or gas bloat.","terms":[],"cards":[{"t":"Long-term PPI cautions","tag":"","topic":"46-treating-gerd-diet-lifestyle-drugs-proce","text":"linked to kidney, liver and heart disease, dementia, GI tumors, <b>poor nutrient absorption</b>, and more respiratory and GI infections — monitor long-term users. In <b>older adults</b>, PPIs reduce <b>calcium absorption</b> (and protein digestion) → brittle bones → <b>hip fracture</b>.","bullets":["Long-term PPIs: <b>poor absorption</b>, infections, kidney/liver/heart/dementia/GI tumor links → <b>monitor</b>","Older adults: ↓ <b>calcium</b> absorption (+ protein digestion) → <b>hip fracture</b>"],"why":""},{"t":"Complications (Box 46.10)","tag":"","topic":"46-hiatal-hernia-and-fundoplication-care","text":"<b>temporary dysphagia</b> when eating starts (<b>persistent</b> dysphagia = wrap too tight → may need dilation); <b>gas bloat syndrome</b> (can't belch to relieve distention); <b>atelectasis or pneumonia</b> (dyspnea, chest pain, fever); <b>obstructed NG tube</b> (nausea, vomiting, distention, no drainage).","bullets":["<b>Temporary dysphagia</b> (persistent → too tight)","<b>Gas bloat</b>: can't belch","<b>Atelectasis/pneumonia</b>","<b>Blocked NG</b>: nausea, vomiting, distention, no drainage"],"why":""}]}]},{"id":"esophageal-cancer","ch":"46","sys":"Digestion & elimination","name":"Esophageal cancer and esophagectomy","patient":"A 66-year-old with years of untreated GERD and a smoking history has had worsening trouble swallowing solids for months and has lost 25 lb.","topics":["46-esophageal-cancer-and-esophagectomy"],"report":["Five days after an esophagectomy, the client has a temperature of 101.6°F, HR 124, RR 28 and new confusion; chest tube drainage has turned cloudy.","Esophagectomy for adenocarcinoma; NPO with jejunostomy feedings.","Suspected anastomotic leak with early sepsis.","I am notifying the surgeon and the Rapid Response Team now. Requesting cultures, a lactate level and antibiotics; keeping the client strictly NPO."],"guide":[],"nodes":[{"id":"gerd","name":"GERD, hiatal hernia & the esophagus"}],"drugs":[],"videos":[],"steps":[{"k":"rc","gist":"Silent early, then <b>persistent, progressive dysphagia</b> with <b>weight loss</b>, food sticking, odynophagia, halitosis, hiccups, chronic cough and <b>hoarseness</b>. After esophagectomy: <b>fever, tachycardia, tachypnea, altered mental status</b> (anastomotic leak), crackles, hypotension, <b>atrial fibrillation</b>.","terms":[{"t":"Progressive dysphagia","see":"Solids first, then soft foods, then liquids.","why":"The tumor <b>narrows the lumen</b>; swallowing problems usually appear only once it is substantially narrowed, which is why the cancer is often found late.","means":"Semisoft foods and thickened liquids, upright for meals; watch every meal for <b>aspiration</b>."},{"t":"Weight loss","see":"Often more than 20 lb over months.","why":"The client <b>can’t get enough food down</b>, and the cancer increases metabolic demands.","means":"Daily weight before breakfast on the same scale; enteral feeding if dysphagia is severe."},{"t":"Hoarseness and chronic cough","see":"Voice changes; cough with more secretions.","why":"The tumor can involve the <b>recurrent laryngeal nerve</b> or let material into the airway.","means":"Assess for <b>aspiration</b> and report changes."},{"t":"Anastomotic leak (days 2–10 after surgery)","see":"Fever, tachycardia, tachypnea, altered mental status, fluid collecting, inflammation.","why":"The new join between the stomach and esophagus sits <b>inside the chest</b>; a leak spills saliva and gastric juice into the <b>mediastinum</b>, causing <b>mediastinitis and sepsis</b>.","means":"<b>Critical rescue</b>: report immediately to the surgeon and the Rapid Response Team; <b>nothing by mouth</b>."},{"t":"Hypotension and atrial fibrillation after surgery","see":"Low BP; new irregular rhythm.","why":"The stomach pulled up into the chest <b>presses on the back of the heart</b>; the surgery irritates the <b>vagus nerve</b>.","means":"Hemodynamic and cardiac monitoring; also watch for <b>fluid overload</b> (crackles, edema, raised JVP)."}],"cards":[{"t":"Key features (Box 46.11)","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"silent early. The most common feature is <b>persistent, progressive dysphagia</b> — often not until the lumen narrows — with <b>weight loss, often more than 20 lb</b> over months. Also food <b>sticking</b>, <b>odynophagia</b>, <b>halitosis</b>, chronic <b>hiccups</b>, chronic <b>cough</b> with more secretions, <b>hoarseness</b>, severe persistent chest or abdominal pain, anorexia, regurgitation, nausea and vomiting, bowel changes.","bullets":["Silent early; <b>progressive dysphagia</b> = most common","<b>Weight loss &gt; 20 lb</b>","Food sticking, odynophagia, <b>halitosis, hiccups</b>, cough, <b>hoarseness</b>, pain"],"why":""},{"t":"Anastomotic leak","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"wound infection can appear at <b>4–5 days</b>; a <b>leak at the anastomosis</b> — the dreaded complication — at <b>2–10 days</b> → <b>stop all oral intake</b> until healed; <b>mediastinitis</b> from a leak can cause <b>fatal sepsis</b>. <b>Critical rescue</b>: <b>fever, fluid accumulation, signs of inflammation, early shock (tachycardia, tachypnea, altered mental status)</b> → report <b>immediately to the surgeon and Rapid Response Team</b>.","bullets":["Infection <b>4–5 days</b>; <b>leak 2–10 days</b> → <b>NPO</b>","Leak → <b>mediastinitis → sepsis</b>","<b>Fever, fluid collection, tachycardia, tachypnea, confusion → surgeon + RRT now</b>"],"why":"After an esophagectomy the stomach is pulled up into the chest and joined to what remains of the esophagus, so the suture line sits next to the lungs, heart and mediastinum. A leak spills swallowed saliva and gastric juice into the chest — that is why nothing goes by mouth until a barium swallow proves the join is sealed, and why fever with tachycardia after day 2 is treated as a leak until proven otherwise."},{"t":"Heart and fluids","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"<b>hypotension</b> from pressure on the back of the heart; <b>fluid overload</b> (older adults, node dissection) — edema, <b>crackles</b>, raised JVP; ICU hemodynamic monitoring every 2 hours; <b>atrial fibrillation</b> from vagus nerve irritation.","bullets":["<b>Hypotension</b>; <b>fluid overload</b> (crackles, JVD)","<b>A-fib</b> from vagus irritation"],"why":""}]},{"k":"ac","gist":"A tumor of the esophagus linked to <b>untreated GERD, smoking, alcohol, obesity</b> and nitrate-rich foods, usually found late. Esophagectomy places the <b>stomach in the chest</b>, joined to the remaining esophagus beside the lungs, heart and mediastinum.","terms":[],"cards":[{"t":"Risk factors","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"<b>alcohol</b>, <b>smoking</b>, diets low in <b>fresh fruits and vegetables</b>, foods high in <b>nitrates and nitrosamines</b> (pickled, fermented), <b>malnutrition</b>, <b>obesity</b>, <b>untreated GERD</b>. <b>Men</b> have higher incidence and mortality regardless of race.","bullets":["<b>Alcohol, smoking</b>, low <b>fruit/veg</b>, <b>pickled/fermented</b> foods","<b>Malnutrition, obesity, untreated GERD</b>","<b>Men</b> higher"],"why":""},{"t":"Diagnose and support","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"<b>EGD with biopsy</b>; staging, often by <b>endoscopic ultrasound</b>; <b>PET</b> finds metastases more accurately than CT and tracks chemotherapy response. The diagnosis brings <b>anxiety</b>, fear of <b>choking at meals</b>, lost pleasure in eating — assess coping and support; refer to counseling, pastoral care, social work; plan end-of-life care when needed.","bullets":["<b>EGD + biopsy</b>; <b>EUS</b> staging; <b>PET</b> for spread","Fear of <b>choking</b>, lost joy in eating → support, referrals"],"why":""}]},{"k":"ph","gist":"<b>Lungs first</b> — atelectasis, pneumonia, aspiration — then <b>anastomotic leak and sepsis</b>, hemodynamic changes and fluid balance, and <b>nutrition</b>.","terms":[],"cards":[{"t":"Lungs first","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"<b>respiratory care is the highest priority</b>. After open surgery: <b>mechanical ventilation for at least 16–24 hours</b>. Then <b>turn, cough and deep breathe every 1–2 hours</b>, check breath sounds and dyspnea every 1–2 hours, <b>splint the incision</b>, give adequate analgesia. Pre-op radiation raises the risk of <b>atelectasis and pneumonia</b>. Keep the patient <b>semi- or high-Fowler</b>; keep the <b>chest tube</b> patent and watch its drainage.","bullets":["<b>Respiratory = highest priority</b>; ventilator <b>16–24 h</b>","<b>TCDB q1–2h</b>, splint, analgesia","<b>Semi/high-Fowler</b>; chest tube patent"],"why":""}]},{"k":"gs","gist":"Before surgery: <b>stop smoking</b>, respiratory rehab and nutrition support. After: protect the <b>lungs</b> and the <b>anastomosis</b>, <b>nothing by mouth</b> until a barium swallow shows it is sealed, and feed through the <b>jejunostomy</b>.","terms":[],"cards":[{"t":"Before","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"removal of all or part of the esophagus — <b>minimally invasive (MIE)</b> for early cancer, but most need open surgery. <b>Stop smoking 2–4 weeks before</b>; <b>respiratory rehab</b> and <b>nutrition support</b> (oral, tube or parenteral) reduce lung complications — teach the patient and caregiver to track <b>weight and I&amp;O</b>; treat dental disease; <b>oral care 4 times a day</b>; teaching and emotional support; <b>prophylactic antibiotics</b> and oxygen on the day.","bullets":["<b>Stop smoking 2–4 weeks before</b>","<b>Respiratory rehab + nutrition support</b>; track <b>weight, I&amp;O</b>","Dental care; <b>oral care 4×/day</b>; antibiotics day of surgery"],"why":""},{"t":"Nutrition and swallowing","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"RDN sets calorie needs; <b>daily weight before breakfast, same scale</b>; <b>upright for several hours after meals, never flat</b>; <b>HOB at least 30°</b>; <b>semisoft foods and thickened liquids</b>; record intake; liquid supplements between meals; <b>enteral feeding</b> if dysphagia is severe; <b>gastrostomy or jejunostomy</b> for complete obstruction or fistula. <b>SLP</b> swallowing therapy; <b>OT</b> feeding techniques. <b>Critical rescue</b>: watch every meal for <b>aspiration</b> (airway obstruction, pneumonia) and teach caregivers to feed safely and respond to choking.","bullets":["<b>Daily weight</b> (same scale, before breakfast)","<b>Upright after meals</b>, <b>HOB ≥ 30°</b>","<b>Semisoft + thickened liquids</b>, supplements; tube feeding if needed","<b>SLP + OT</b>; watch every meal for <b>aspiration</b>"],"why":""},{"t":"Cancer treatments","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"chemotherapy (often before surgery), radiation, or <b>chemoradiation</b>; <b>photodynamic therapy</b> with <b>porfimer sodium</b> (light-sensitive drug) as palliation; <b>esophageal dilation</b> for quick but temporary relief (<b>perforation</b> risk); <b>stents</b> (metal, plastic or biodegradable) to keep it open longer — palliation for patients who can't have surgery; a covered stent can seal a perforation (bacteremia → <b>antibiotics</b> to prevent sepsis and endocarditis; pain, <b>stent migration</b>, recurrent dysphagia); <b>trastuzumab</b> (HER2 target) IV every 3 weeks.","bullets":["<b>Chemoradiation</b>; <b>PDT + porfimer</b> (palliation)","<b>Dilation</b> (perforation risk); <b>stents</b> = palliation (antibiotics vs sepsis/endocarditis; migration)","<b>Trastuzumab</b> (HER2)"],"why":""}]},{"k":"ta","gist":"<b>Turn, cough and deep breathe every 1–2 hours</b>, splint the incision, incentive spirometry, <b>semi- or high-Fowler</b>; keep the chest tube patent; <b>secure the NG tube — never irrigate or reposition it without an order</b>; oral and nasal care every 2–4 hours; J-tube feedings from day 2 (<b>don’t aspirate for residual</b>); report leak signs at once.","terms":[],"cards":[{"t":"NG tube after esophageal surgery (Box 46.12)","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"decompresses the stomach so the suture line isn't strained. Check placement <b>every 4–8 hours</b>; drainage <b>bloody → yellowish green by the end of day 1</b>; <b>secure it well</b>; <b>never irrigate or reposition without an order</b>; <b>oral and nasal care every 2–4 hours</b>; <b>HOB at least 30°</b>; first sips of water <b>upright</b> — watch for dysphagia; watch for leak signs.","bullets":["Placement <b>q4–8h</b>; bloody → <b>yellow-green by end of day 1</b>","<b>Secure it</b>; <b>never irrigate or reposition</b> without order","Oral/nasal care <b>q2–4h</b>; <b>HOB ≥ 30°</b>; first sips <b>upright</b>"],"why":""},{"t":"Feeding after surgery","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"<b>jejunostomy (J-tube) feedings start on day 2</b> — <b>don't aspirate for residual</b> (tears the mucosa) — increased slowly through day 5. <b>Barium swallow on day 7</b>: no leak → NG tube out. <b>Minimal liquid diet for 2 weeks</b>, then as the surgeon orders.","bullets":["<b>J-tube feeds day 2</b>; <b>no residual checks</b>","<b>Barium swallow day 7</b> → NG out if no leak","<b>Liquids for 2 weeks</b>"],"why":""}]},{"k":"eo","gist":"Clear breath sounds, <b>no leak</b> on the barium swallow (day 7), stable vital signs; eating small, soft, high-calorie meals <b>upright</b>; the client reports a <b>weight loss of 5 lb or more in a month</b> and returning dysphagia.","terms":[],"cards":[{"t":"At home","tag":"","topic":"46-esophageal-cancer-and-esophagectomy","text":"keep up <b>walking and the incentive spirometer</b>; avoid bed rest. <b>Small, frequent, high-calorie, high-protein, soft</b> meals and <b>supplement shakes</b>; <b>sit upright to eat and stay upright</b> after. Patients can lose up to <b>10% of body weight</b> — <b>report a loss of 5 lb or more in a month</b>; home <b>tube feeding or parenteral nutrition</b> if oral intake falls short. <b>Handwashing</b>, avoid sick people and crowds, report respiratory infection. Report returning <b>dysphagia or odynophagia</b> (stricture, reflux, recurrence). Focus on <b>quality of life</b>; plan hospice when needed. A rehab program of <b>brisk walking and diet education</b> improved reflux, sleep, mood and quality of life.","bullets":["<b>Walk + spirometer</b>; no bed rest","<b>Small, frequent, high-calorie, high-protein, soft</b>; <b>upright</b>","Report <b>≥ 5 lb loss in a month</b>; home tube feeding/PN if needed","Handwashing; report <b>returning dysphagia</b>","Quality of life; hospice when needed"],"why":""}]}]},{"id":"gastritis","ch":"47","sys":"Digestion & elimination","name":"Gastritis","patient":"A 45-year-old who takes naproxen every day for knee pain and drinks most nights has burning upper abdominal pain and nausea after meals.","topics":["47-gastritis","47-ulcer-and-gastritis-drugs-table-47-1"],"report":["The client admitted with gastritis vomited about 200 mL of coffee-ground emesis; HR 104, BP 118/72 (baseline 132/80).","Takes naproxen daily for knee pain and drinks alcohol most nights; admitted for epigastric pain.","Possible upper GI bleeding from erosive gastritis.","Please evaluate. Requesting a CBC, type and screen, an IV PPI order, NPO status and a decision on stopping the naproxen."],"guide":[{"key":"47:0","name":"Gastritis & peptic ulcer disease"}],"nodes":[{"id":"pud","name":"Gastritis & peptic ulcer"},{"id":"acid","name":"Acid & the proton pump"}],"drugs":[{"id":"omeprazole","name":"Omeprazole"},{"id":"pantoprazole","name":"Pantoprazole"},{"id":"famotidine","name":"Famotidine"},{"id":"sucralfate","name":"Sucralfate"},{"id":"almag","name":"Magnesium hydroxide with aluminum hydroxide"},{"id":"aloh","name":"Aluminum hydroxide"},{"id":"bismuth","name":"Bismuth subsalicylate"},{"id":"misoprostol","name":"Misoprostol"}],"videos":[{"id":"68AxlUXD088","title":"What is gastritis? (GutDr 3D animation)","see":"The stomach lining inflamed by H. pylori, NSAIDs or alcohol, in 3D"},{"id":"Fz871WjMzdU","title":"Proton pump inhibitors (pharmacology animation)","see":"The H⁺/K⁺ pump in the parietal cell being switched off — the last step of acid making"}],"steps":[{"k":"rc","gist":"<b>Epigastric pain and dyspepsia</b> — rapid onset in acute gastritis; in chronic gastritis, vague upper abdominal discomfort <b>after meals</b>, nausea and anorexia. Danger signs: <b>hematemesis, melena</b> and signs of hypovolemia — hemorrhage can be the first sign.","terms":[{"t":"Epigastric pain and dyspepsia","see":"Burning or gnawing pain under the sternum and above the umbilicus; indigestion, fullness.","why":"The inflamed mucosa has lost its protective layer, so <b>acid and pepsin</b> reach and irritate the tissue and its nerve endings.","means":"Ask what makes it better or worse (food, NSAIDs, alcohol). Pain that becomes <b>sudden and severe</b> may mean perforation."},{"t":"Nausea, vomiting and anorexia","see":"Doesn’t want to eat; may vomit after meals.","why":"An inflamed stomach lining is irritated by food and empties more slowly.","means":"Watch <b>fluid and electrolyte</b> balance — persistent vomiting loses fluid, potassium and acid."},{"t":"Hematemesis and melena","see":"Bright red or coffee-ground vomit; black, tarry stools.","why":"<b>Erosive</b> gastritis wears through the mucosa into small blood vessels.","means":"A <b>life-threatening emergency</b> if heavy — vital signs, IV access, report now."},{"t":"Signs of vitamin B₁₂ deficiency (chronic gastritis)","see":"Fatigue, pallor, a smooth sore tongue, numbness and tingling.","why":"Chronic and <b>autoimmune</b> gastritis destroy the <b>parietal cells</b>, which make <b>intrinsic factor</b> — needed to absorb vitamin B₁₂.","means":"May need <b>lifelong B₁₂ injections</b>. Chronic and autoimmune gastritis also raise <b>gastric cancer</b> risk."}],"cards":[{"t":"Acute signs","tag":"","topic":"47-gastritis","text":"<b>rapid onset of epigastric pain and dyspepsia</b>; bleeding shows as <b>hematemesis</b> (bright red or coffee-ground) or <b>melena</b> (black, tarry). Gastric <b>hemorrhage</b> can be the first sign — a life-threatening emergency.","bullets":["<b>Sudden epigastric pain + dyspepsia</b>","Bleeding: <b>hematemesis</b>, <b>melena</b>; hemorrhage = emergency"],"why":"Even decaffeinated coffee is on the avoid list because coffee itself — not just its caffeine — stimulates gastric acid secretion. The rule is about the stomach's acid output, not the stimulant."},{"t":"Chronic gastritis","tag":"","topic":"47-gastritis","text":"few symptoms unless it ulcerates: nausea, vomiting, upper abdominal discomfort, epigastric pain <b>after meals</b>, anorexia. The most common cause is <b><i>H. pylori</b></i> (the more organisms, the more damage). Chronic <i>H. pylori</i> and <b>autoimmune gastritis</b> raise the risk of <b>gastric cancer</b>.","bullets":["Few symptoms; pain after meals, anorexia","Usually <b><i>H. pylori</b></i>; ↑ <b>cancer</b> risk"],"why":""}]},{"k":"ac","gist":"Inflammation of the gastric mucosa when its defenses — <b>mucus, bicarbonate, prostaglandins and blood flow</b> — are overwhelmed. <b>Acute</b>: NSAIDs (the big one), alcohol, caffeine, stress, smoking, corrosives. <b>Chronic</b>: mostly <b><i>H. pylori</b></i>. <b>EGD with biopsy</b> is the gold standard.","terms":[{"t":"NSAIDs and the mucosal barrier","see":"Daily ibuprofen, naproxen or aspirin.","why":"NSAIDs block <b>prostaglandins</b>, which keep the stomach lining protected with mucus, bicarbonate and blood flow.","means":"<b>Remove the cause</b> — the main treatment for acute gastritis. Misoprostol or a PPI protects clients who must keep taking NSAIDs."},{"t":"<i>H. pylori</i>","see":"Positive breath test, stool antigen, serology or biopsy.","why":"The bacterium makes <b>urease</b>, which neutralizes the acid around it, and damages the protective lining.","means":"Treat with a PPI plus antibiotics and <b>finish the whole course</b>. For breath or stool testing, including the test of cure: <b>at least 4 weeks after antibiotics or bismuth</b> and <b>off PPIs at least 2 weeks</b> — <b>antacids are allowed</b> — per the provider’s plan."}],"cards":[{"t":"Acute gastritis","tag":"","topic":"47-gastritis","text":"inflammation of the mucosa or submucosa from local irritants: a thick, red mucosa with prominent folds and some necrosis. If the muscle layer isn't involved it <b>heals in a few days</b>; if it is, <b>bleeding or hemorrhage</b> can occur. Causes: <b>long-term NSAIDs</b> (the big one), <b>alcohol, coffee and caffeine, stress, smoking</b>, radiation, swallowed <b>corrosives</b> (acids, alkalis like lye and drain cleaner), steroids, aldosterone antagonists, SSRIs. Food poisoning from <b>staphylococcal endotoxin</b> starts abruptly with severe vomiting within hours.","bullets":["Irritants → red, thick mucosa; <b>heals in days</b> unless muscle involved (→ <b>bleeding</b>)","Causes: <b>NSAIDs</b>, <b>alcohol, caffeine, stress, smoking</b>, radiation, <b>corrosives</b>, steroids, SSRIs","<b>Staph endotoxin</b> → abrupt vomiting within hours"],"why":""},{"t":"Diagnosis","tag":"","topic":"47-gastritis","text":"<b>EGD with biopsy is the gold standard</b> — symptoms alone can't make the diagnosis, and the biopsy names the type (classed by cause, cell changes or lesion pattern, and as <b>erosive</b> — ulcerating — or <b>nonerosive</b>); several biopsies if lesions are patchy; cytology rules out cancer; tissue tested for <i>H. pylori</i> (<b>rapid urease test</b>, culture, PCR). For <b>urea breath or stool antigen</b> testing, including the <b>test of cure</b>: wait <b>at least 4 weeks after antibiotics or bismuth</b> and stop <b>PPIs (or PCABs) at least 2 weeks</b> before — <b>antacids are allowed</b> — as coordinated with the prescriber (<a href=\"https://gi.org/journals-publications/ebgi/schoenfeld_sep2024/\">ACG guideline summary</a>).","bullets":["<b>EGD + biopsy = gold standard</b>; symptoms alone can't diagnose","Biopsy names the type: <b>erosive</b> vs <b>nonerosive</b>; cytology rules out <b>cancer</b>","Tissue <i>H. pylori</i> tests (<b>rapid urease</b>, culture, PCR)","Breath/stool test (incl. test of cure): <b>≥ 4 wk after antibiotics/bismuth</b>, <b>off PPIs ≥ 2 wk</b>; antacids OK"],"why":""}]},{"k":"ph","gist":"<b>Acute pain</b>; risk for <b>upper GI bleeding</b> and <b>fluid and electrolyte imbalance</b> from vomiting; in chronic gastritis, <b>B₁₂ deficiency</b> and gastric cancer risk.","terms":[],"cards":[]},{"k":"gs","gist":"<b>Remove the cause</b>, <b>reduce acid and protect the mucosa</b> (PPIs, H₂ blockers, sucralfate, antacids), <b>eradicate <i>H. pylori</b></i> when present, and replace <b>B₁₂</b> in chronic gastritis.","terms":[{"t":"Why a PPI goes 30 minutes before the main meal","see":"Omeprazole or pantoprazole before breakfast or the main meal.","why":"PPIs block only proton pumps that are <b>switched on</b>, and <b>food is the switch</b>. Taken before the meal, the drug is in the blood just as the pumps activate.","means":"The most commonly missed PPI teaching point. Don’t crush delayed-release forms; step down slowly rather than stopping abruptly."},{"t":"Why calcium carbonate can backfire","see":"Tums-type antacids.","why":"Calcium stimulates <b>gastrin</b>, which triggers <b>rebound acid</b> secretion.","means":"Aluminum-magnesium antacids are preferred; separate any antacid from other drugs by <b>1–2 hours</b>."}],"cards":[{"t":"Treatment","tag":"","topic":"47-gastritis","text":"usually managed in the community; <b>admitted</b> only for a flare with <b>fluid and electrolyte imbalance, bleeding or worsening pain</b>. <b>Remove the cause</b> — the main treatment for acute gastritis; supportive care; it usually heals within days. Bleeding → transfusion and fluids; major bleeding or ulceration may need partial gastrectomy, pyloroplasty or vagotomy. Diet: avoid what causes distress — <b>caffeine, acidic foods (tomato, citrus), bell peppers and onions</b>; <b>bland, nonspicy, smaller and more frequent meals</b>; no alcohol or tobacco. Drugs: <b>famotidine</b> (H₂ blocker), <b>sucralfate</b>, <b>omeprazole or pantoprazole</b>, aluminum-magnesium antacids. <b>Calcium carbonate</b> is a potent antacid but triggers <b>gastrin</b> → <b>rebound acid</b>. Chronic gastritis may need <b>vitamin B₁₂ injections</b>; treat <i>H. pylori</i> if present.","bullets":["Community care; <b>admit</b> for a flare with <b>F&amp;E imbalance, bleeding, ↑ pain</b>","<b>Remove the cause</b>; supportive care; heals in days","Avoid <b>caffeine, tomato, citrus, peppers, onions</b>; <b>bland, small, frequent</b>","<b>H₂ blockers, PPIs, sucralfate, antacids</b>","<b>Calcium carbonate → rebound acid</b>","Chronic: <b>B₁₂ injections</b>; treat <b><i>H. pylori</b></i>"],"why":""},{"t":"PPIs — the drug of choice","tag":"","topic":"47-ulcer-and-gastritis-drugs-table-47-1","text":"<b>omeprazole, lansoprazole, dexlansoprazole, esomeprazole, rabeprazole, pantoprazole</b> suppress the <b>H⁺/K⁺-ATPase (proton pump)</b>. Give <b>30 minutes before the main meal</b> (food activates the pump the drug blocks) — rabeprazole <b>after the morning meal</b>. <b>Don't crush</b> delayed-release capsules or enteric-coated tablets (rabeprazole, pantoprazole). <b>IV pantoprazole</b>: on a pump <b>with a filter, in a separate line</b>, with <b>no other IV drugs</b> (precipitates). Esomeprazole: low dose with severe liver disease. Watch <b>drug interactions</b> (they change how other drugs are metabolized). <b>Don't stop abruptly — step down over several days</b> (rebound); reassess long-term use (<b>osteoporotic fractures</b>).","bullets":["Block the <b>proton pump</b> (H⁺/K⁺-ATPase) = <b>drug of choice</b>","<b>30 min before the main meal</b> (rabeprazole after breakfast)","<b>Don't crush</b>","<b>IV pantoprazole</b>: pump, <b>filter, own line</b>","<b>Step down</b>, don't stop abruptly; long-term → <b>fractures</b>"],"why":"A proton pump inhibitor only blocks pumps that are <b>switched on</b>, and food is the switch. Given 30 minutes before the main meal, the drug is in the blood just as the pumps activate — taken after the meal, many pumps have already done their work. That timing rule is the most commonly missed PPI teaching point."},{"t":"Current ACG update (2024)","tag":"","topic":"47-ulcer-and-gastritis-drugs-table-47-1","text":"When susceptibility is unknown, ACG recommends <b>14-day optimized bismuth quadruple therapy</b>: a PPI, bismuth, tetracycline and metronidazole. <b>Clarithromycin triple therapy requires proven susceptibility</b>. Confirm eradication ≥ 4 weeks after antibiotics and off PPI/PCAB therapy for ≥ 2 weeks, coordinated with the prescriber. This differs from the book’s older regimen examples. <a href=\"https://gi.org/journals-publications/ebgi/schoenfeld_sep2024/\">ACG guideline summary</a>.","bullets":["Unknown susceptibility → <b>14-day BQT</b>","Clarithromycin triple → <b>proven susceptibility</b>","Test cure <b>≥ 4 weeks after antibiotics</b>, off PPI/PCAB <b>≥ 2 weeks</b>"],"why":""}]},{"k":"ta","gist":"Hold and report NSAIDs; give the <b>PPI 30 minutes before the main meal</b>, <b>sucralfate 1 hour before meals</b> and not within 30 minutes of antacids, and keep <b>antacids 1–2 hours from other drugs</b>; <b>bland, smaller, more frequent meals</b>; avoid caffeine (<b>even decaf coffee</b>), tomato, citrus, peppers and onions; monitor for bleeding.","terms":[],"cards":[{"t":"Antacids","tag":"","topic":"47-ulcer-and-gastritis-drugs-table-47-1","text":"raise gastric pH and deactivate pepsin. <b>Liquid suspensions work better than chewable tablets.</b> <b>No other drugs within 1–2 hours</b> (they block absorption). <b>Magnesium hydroxide with aluminum hydroxide</b>: give <b>2 hours after meals and at bedtime</b>; watch for <b>diarrhea</b>; check for <b>chronic kidney disease or heart failure</b> — poor kidney excretion causes <b>hypermagnesemia</b>. <b>Aluminum hydroxide</b>: give <b>1 hour after meals and at bedtime</b>; causes <b>constipation</b> (alternate with a magnesium antacid); <b>safe in CKD</b> — it binds phosphate and has no magnesium.","bullets":["<b>Liquid &gt; chewable</b>; <b>other drugs 1–2 h apart</b>","<b>Mg-Al</b>: <b>2 h after meals + bedtime</b>; <b>diarrhea</b>; avoid in <b>CKD/HF</b> (↑ Mg)","<b>Aluminum</b>: <b>1 h after meals + bedtime</b>; <b>constipation</b>; <b>OK in CKD</b> (binds phosphate)"],"why":""},{"t":"H₂ blockers","tag":"","topic":"47-ulcer-and-gastritis-drugs-table-47-1","text":"<b>famotidine, nizatidine</b> block <b>histamine receptors on parietal cells</b> → less acid. A <b>single dose at bedtime</b> suppresses <b>night-time acid</b> for heartburn and PUD. <b>IV famotidine</b> prevents surgical <b>stress ulcers</b>.","bullets":["<b>Famotidine</b>: blocks parietal <b>histamine</b> receptors","<b>Bedtime dose</b> → ↓ night acid","<b>IV</b> for stress ulcer prevention"],"why":""},{"t":"Mucosal protectors","tag":"","topic":"47-ulcer-and-gastritis-drugs-table-47-1","text":"<b>sucralfate</b> coats the ulcer: give <b>1 hour before and 2 hours after meals and at bedtime</b> (food interferes), and <b>not within 30 minutes of antacids</b> or other drugs. <b>Bismuth subsalicylate</b> stops <i>H. pylori</i> from binding to the lining and boosts mucosal protection and prostaglandin production. It is a salicylate — <b>no aspirin</b> with it (salicylate overdose); it <b>turns stool and tongue black</b> — temporary and harmless.","bullets":["<b>Sucralfate</b>: <b>1 h before + 2 h after meals + bedtime</b>; <b>30 min from antacids</b>","<b>Bismuth</b>: blocks <i>H. pylori</i> binding; ↑ protection + prostaglandins","<b>Bismuth</b>: <b>no aspirin</b>; <b>black stool/tongue</b> is harmless"],"why":""}]},{"k":"eo","gist":"Pain relieved, <b>no bleeding</b>, eating without distress; the client avoids NSAIDs, alcohol and smoking; <b><i>H. pylori</b></i> eradication confirmed <b>at least 4 weeks</b> after antibiotics.","terms":[],"cards":[{"t":"Prevention (Box 47.1)","tag":"","topic":"47-gastritis","text":"balanced diet and exercise; <b>limit alcohol</b>; <b>avoid long-term aspirin, NSAIDs and corticosteroids</b>; avoid excess coffee (<b>even decaf</b>); safe food and water; <b>manage stress</b> (relaxation, meditation, yoga); <b>stop smoking</b>; protect against workplace toxins (lead, nickel); get GERD treated. Respect patients who can't easily do these (money, time, family duties).","bullets":["Limit alcohol; <b>avoid long-term NSAIDs/aspirin/steroids</b>","Less coffee (<b>even decaf</b>); safe food + water","<b>Stress management</b>, <b>stop smoking</b>, avoid lead/nickel"],"why":""}]}]},{"id":"ugib","ch":"47","sys":"Digestion & elimination","name":"Peptic ulcer with upper GI bleeding","patient":"A client who takes ibuprofen every day for back pain vomits coffee-ground material and feels dizzy standing up.","topics":["47-peptic-ulcer-disease-the-infection-exemp","47-upper-gi-bleeding-and-ulcer-emergencies"],"report":["The client vomited about 300 mL of coffee-ground emesis; HR 118, BP 92/58, dizzy and orthostatic on standing.","Takes ibuprofen daily for chronic back pain; no known GI history.","Suspected upper GI bleed with early hypovolemia. Two large-bore IVs are in and the client is NPO.","Please evaluate now. Requesting a CBC, type and crossmatch, IV fluid orders and a GI consult for EGD."],"guide":[{"key":"47:0","name":"Gastritis & peptic ulcer disease"},{"key":"47:1","name":"Upper GI bleeding & gastric cancer"}],"nodes":[{"id":"pud","name":"Gastritis & peptic ulcer"},{"id":"ugib","name":"Upper GI bleeding & gastric surgery"},{"id":"acid","name":"Acid & the proton pump"}],"drugs":[{"id":"pantoprazole","name":"Pantoprazole"},{"id":"omeprazole","name":"Omeprazole"},{"id":"clarithromycin","name":"Clarithromycin"},{"id":"amoxicillin","name":"Amoxicillin"}],"videos":[{"id":"V_U6czbDHLE","title":"The surprising cause of stomach ulcers (TED-Ed)","see":"How H. pylori, not stress or spicy food, was shown to cause most ulcers — and why antibiotics cure them"}],"steps":[{"k":"rc","gist":"<b>Hematemesis</b> (bright red or coffee-ground), <b>melena</b>, <b>tachycardia</b> with falling BP, <b>orthostatic hypotension</b>, and <b>new confusion</b> in an older adult — signs of <b>hypovolemia from GI blood loss</b>.","terms":[{"t":"Bright red hematemesis","see":"Vomiting fresh red blood or clots.","why":"Brisk, <b>active bleeding</b> at or above the duodenum: the blood comes up before stomach acid has time to change it.","means":"Fast blood loss — ABCs, two large-bore IVs, report <b>now</b>."},{"t":"Coffee-ground emesis","see":"Dark brown, granular vomit.","why":"Blood that <b>sat in the stomach</b> long enough for <b>gastric acid to turn hemoglobin brown</b>.","means":"A slower or older bleed — still a bleed. Report it, measure it and trend the vital signs."},{"t":"Melena","see":"Black, sticky, tarry, foul-smelling stool.","why":"Blood from the upper GI tract <b>digested on its way through the intestines</b> turns black.","means":"Upper GI source (more common with duodenal ulcers). Bright red blood from the rectum usually means a lower source or a very fast upper bleed."},{"t":"Tachycardia","see":"Pulse rising, often before the BP falls.","why":"Losing volume lowers venous return; <b>baroreceptors</b> sense the drop and trigger a <b>sympathetic response</b> that raises the heart rate to keep cardiac output up.","means":"<b>The earliest vital-sign warning</b> of hypovolemia. A rising pulse with a normal BP is compensation, not stability."},{"t":"Orthostatic hypotension and dizziness on standing","see":"BP drops and HR rises when the client sits up or stands; lightheaded, may faint.","why":"With less circulating volume, the body cannot compensate quickly when gravity pools blood in the legs.","means":"Early sign of volume loss and a <b>fall risk</b> — assist with every position change."},{"t":"Hypotension, cool clammy skin and low urine output","see":"BP falling, pale cool moist skin, urine under 30 mL/hr.","why":"Compensation is failing: the body <b>constricts skin vessels</b> to send blood to the heart and brain, and the kidneys conserve water (less perfusion, <b>ADH and aldosterone</b>).","means":"<b>Hypovolemic shock</b> — more than about 1 L lost. Fluids and blood now, report immediately."},{"t":"New confusion in an older adult","see":"Restless, disoriented, or unusually drowsy.","why":"<b>Reduced blood flow and oxygen to the brain</b>; older adults compensate less well.","means":"Can be the <b>first</b> sign of bleeding in an older adult — do not assume it is baseline."},{"t":"Burning, gnawing epigastric pain","see":"Pain between the umbilicus and the xiphoid; may wake the client at night (duodenal).","why":"<b>Acid and pepsin</b> reach the exposed tissue and nerve endings in the ulcer crater.","means":"A change from intermittent pain to <b>constant pain radiating to the back</b> suggests penetration or <b>perforation</b>."},{"t":"Rigid, board-like abdomen","see":"Sudden severe pain spreading over the abdomen; the client lies still with knees drawn up.","why":"The ulcer has <b>perforated</b> and gastric contents spill into the peritoneum (<b>chemical peritonitis</b>); the abdominal muscles spasm involuntarily to guard it.","means":"<b>Surgical emergency</b> — NPO, report immediately, watch for sepsis and shock."}],"cards":[{"t":"Hemorrhage — the most serious","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"more often with <b>gastric and stress ulcers</b> and in <b>older adults</b>; recurs if <i>H. pylori</i> stays untreated or therapy lacks an H₂ blocker or PPI. Massive bleeding → <b>hematemesis</b> (bright red, or <b>coffee-ground</b> when acid has digested the blood) — bleeding at or above the duodenojejunal junction. Slow bleeding → <b>melena</b> (more common with duodenal ulcers). Box 47.2: hematemesis, melena, <b>falling Hgb/Hct and BP, rising heart rate</b>, weak pulses, <b>acute confusion in older adults</b>, vertigo, dizziness, syncope. Early detection decides the outcome: <b>monitor vital signs often</b> and report changes at once. Common sources of upper GI bleeding (Fig. 47.2): <b>esophageal varices</b>, esophageal cancer, <b>gastritis</b>, <b>gastric ulcer</b>, gastric cancer, <b>duodenal ulcer</b>.","bullets":["<b>Most serious</b>; gastric + stress ulcers, <b>older adults</b>","<b>Hematemesis</b> (red/<b>coffee-ground</b>) = upper GI","<b>Melena</b> = slow bleeding (duodenal)","↓ <b>Hgb/Hct, BP</b> · ↑ <b>HR</b> · weak pulses · <b>confusion (older)</b> · dizzy, syncope","<b>Frequent VS</b>; report changes at once (early detection)","Sources (Fig. 47.2): <b>varices</b>, esophageal + gastric <b>cancer</b>, <b>gastritis</b>, <b>gastric + duodenal ulcers</b>"],"why":""},{"t":"Physical","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"<b>epigastric tenderness</b> at the midline between umbilicus and xiphoid; <b>dyspepsia</b> — sharp, burning or gnawing, or pressure, fullness or hunger. Perforation: <b>rigid board-like abdomen, rebound tenderness, intense pain</b>. <b>Orthostatic BP</b> and dehydration signs for blood loss — <b>dizziness on standing</b>; older adults risk <b>falls</b>.","bullets":["<b>Epigastric</b> midline tenderness; <b>burning, gnawing</b> pain","Perforation: <b>rigid</b>, rebound","<b>Orthostatics</b>; dizziness → <b>falls</b> in older adults"],"why":""},{"t":"History","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"past <i>H. pylori</i>; all drugs — <b>NSAIDs, corticosteroids, chemotherapy</b>; radiation; GI surgery (partial gastrectomy, <b>bariatric</b>); alcohol, tobacco, foods that worsen symptoms; stressors; pain pattern with eating and sleep and what relieves it. <b>A change in the pain</b> — intermittent and relieved by food or antacids becoming <b>constant and radiating to the back</b> — suggests <b>perforation</b>. Many people with active ulcers have <b>no symptoms</b>.","bullets":["<i>H. pylori</i>, <b>NSAIDs, steroids</b>, chemo, radiation, <b>bariatric surgery</b>","Pain vs meals + sleep; what helps","Pain becomes <b>constant, radiates to back</b> → <b>perforation</b>","Many have <b>no symptoms</b>"],"why":""}]},{"k":"ac","gist":"Ulceration from <b><i>H. pylori</b></i> or <b>NSAIDs</b> has eroded into a vessel. <b>Bright red</b> = brisk active bleeding; <b>coffee-ground</b> = slower bleeding exposed to gastric acid; <b>melena</b> = blood digested through the intestine.","terms":[{"t":"NSAID-induced ulcer","see":"History of daily ibuprofen, naproxen or aspirin.","why":"NSAIDs block <b>prostaglandins</b>, which normally keep the stomach lining protected (mucus, bicarbonate and blood flow). Without them, acid and pepsin erode the mucosa.","means":"Teach to <b>avoid NSAIDs</b>; misoprostol (a prostaglandin) or a PPI protects clients who must take them."},{"t":"<i>H. pylori</i> infection","see":"Positive urea breath test, stool antigen, serology or biopsy.","why":"The bacterium makes <b>urease</b>, which neutralizes acid around it, and damages the protective lining so acid can reach the tissue.","means":"Curable with antibiotics plus a PPI — the client must <b>finish the whole course</b> or the ulcer recurs."},{"t":"Hemoglobin and hematocrit falling","see":"Hgb/Hct lower than baseline, often falling between draws.","why":"Early in an acute bleed whole blood is lost, so the first value can look <b>near normal</b>; it falls as fluid shifts into the vessels and IV fluids dilute the blood.","means":"<b>Trend</b> the values and treat the vital signs — a normal first Hgb does not rule out a serious bleed."},{"t":"BUN elevated with a normal creatinine","see":"BUN high, creatinine normal.","why":"Blood in the gut is <b>digested protein</b>: it is absorbed and turned into urea by the liver.","means":"Supports an <b>upper GI</b> bleed rather than kidney failure (where creatinine also rises)."}],"cards":[{"t":"Definition and cause","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"mucosal defenses fail and <b>acid and pepsin</b> erode the epithelium. Most ulcers come from <b><i>H. pylori</b></i> or <b>long-term NSAIDs</b>; other risks are the same as gastritis (alcohol, smoking, stress, caffeine). Duodenal ulcers often run in <b>families</b>. About <b>4.5 million</b> Americans a year; visits, admissions and deaths have fallen with <b>PPIs</b> and early <i>H. pylori</i> treatment.","bullets":["Defenses fail → <b>acid + pepsin</b> erode","Causes: <b><i>H. pylori</b></i> + <b>NSAIDs</b>","Duodenal: <b>family history</b>; PPIs + <i>H. pylori</i> treatment → fewer deaths"],"why":""},{"t":"Gastric vs duodenal (Table 47.2)","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"<b>gastric</b>: age <b>50–70</b>; men and women equally; no blood-group link; <b>normal or low acid</b>; pain <b>30–60 minutes after a meal</b>, rarely at night, <b>worsened by eating</b>; bleeds more as <b>hematemesis</b> than melena; cancer risk raised but under 5%; heals with treatment but tends to <b>recur in the same spot</b>; the surrounding mucosa shows <b>atrophic gastritis</b>. <b>Duodenal</b>: age <b>20–50</b>; more often <b>men</b>; most often <b>blood type O</b>; <b>acid hypersecretion</b>; <b>family history</b>; pain <b>1½–3 hours after a meal</b> and often <b>wakes the patient at 1–2 a.m.</b>; <b>relieved by eating</b>; bleeds more as <b>melena</b>; no added cancer risk; remissions and flare-ups — <b>60% recur within 1 year, 90% within 2</b>; no surrounding gastritis.","bullets":["<b>Gastric</b>: <b>50–70</b>, M = F, any blood type, <b>normal/low acid</b>, <b>atrophic gastritis</b> around it","Gastric pain <b>30–60 min after meals</b>, <b>worse with food</b>, rarely at night; <b>hematemesis</b> &gt; melena","Gastric: cancer risk ↑ (&lt; 5%); heals but <b>recurs in the same spot</b>","<b>Duodenal</b>: <b>20–50</b>, <b>men</b>, <b>type O</b>, <b>hypersecretion</b>, <b>family history</b>","Duodenal pain <b>1½–3 h after meals</b> + <b>1–2 a.m.</b>, <b>food relieves</b>; <b>melena</b> &gt; hematemesis","Duodenal: no cancer risk, no surrounding gastritis; remissions + flares — <b>60% recur in 1 yr, 90% in 2</b>"],"why":""},{"t":"Tests for <i>H. pylori</i>","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"<b>serology</b> (antibodies) is the most common; the <b>urea breath test</b> (swallow ¹³C urea, exhale — labeled carbon means urease is present) and <b>stool antigen</b> are <b>more accurate</b>. <b>EGD is the most accurate test for PUD</b>: it shows the crater and takes biopsies (rapid urease test, cancer cytology); may be repeated every <b>4–6 weeks</b> to check healing. <b>Nuclear scan</b> (technetium) finds bleeding — no prep; a repeat scan <b>1–2 days after treatment</b> shows whether it worked. Bleeding → low <b>Hgb/Hct</b>, stool <b>occult blood</b>.","bullets":["<i>H. pylori</i>: <b>serology</b> (most common); <b>breath + stool tests</b> (more accurate)","<b>EGD</b> = most accurate for PUD; repeat q4–6 weeks","<b>Nuclear scan</b> (technetium, no prep) for bleeding; repeat <b>1–2 days</b> after treatment","Bleeding → ↓ <b>Hgb/Hct</b>, stool <b>occult blood</b>"],"why":""}]},{"k":"ph","gist":"<b>Hypovolemic shock</b> is the priority. <b>Sudden severe pain with a rigid, board-like abdomen</b> = <b>perforation</b> with peritonitis — a surgical emergency.","terms":[],"cards":[{"t":"Perforation","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"the ulcer erodes through the <b>full thickness</b> and contents spill into the peritoneum: <b>sudden, sharp mid-epigastric pain spreading over the whole abdomen</b>; <b>tender, rigid, board-like abdomen</b> (<b>peritonitis</b>), rebound tenderness; the patient lies in a <b>fetal position</b>; bowel sounds hyperactive then diminishing → <b>paralytic ileus</b>; <b>septicemia and hypovolemic shock</b> within hours. <b>A surgical emergency.</b>","bullets":["Full-thickness erosion → spill into peritoneum","<b>Sudden sharp epigastric pain → whole abdomen</b>","<b>Board-like rigid abdomen</b> (peritonitis), <b>fetal position</b>","Ileus, <b>sepsis, shock</b> within hours → <b>surgery now</b>"],"why":""},{"t":"Priority problems and goals","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"<b>acute or persistent pain</b> and <b>potential for upper GI bleeding</b>. Pain goal: <b>3 or less on a 0–10 scale</b>. Drug goals: <b>relieve pain, eradicate <i>H. pylori</i>, heal the ulcer, prevent recurrence</b>.","bullets":["Problems: <b>pain</b> + <b>bleeding risk</b>; pain <b>≤ 3/10</b>","Drugs: relieve pain, <b>kill <i>H. pylori</b></i>, heal, prevent recurrence"],"why":"The pain clock separates the two ulcers. A duodenal ulcer hurts when the duodenum is bathed in acid and nothing buffers it — <b>hours after a meal and in the early morning</b> — and food brings relief. A gastric ulcer sits where the food goes, so eating triggers the pain <b>soon after the meal</b> and food makes it worse."},{"t":"Pyloric (gastric outlet) obstruction","tag":"","topic":"47-peptic-ulcer-disease-the-infection-exemp","text":"scarring, edema or inflammation block the pylorus: <b>bloating, nausea, vomiting</b> of retained food. Persistent vomiting loses acid (H⁺ and Cl⁻) → <b>metabolic alkalosis</b> and <b>hypokalemia</b>.","bullets":["Scar/edema at <b>pylorus</b> → bloating, <b>vomiting</b>","Vomiting acid → <b>metabolic alkalosis</b> + <b>hypokalemia</b>"],"why":""}]},{"k":"gs","gist":"Restore <b>circulating volume</b> (isotonic fluids, packed RBCs), achieve <b>hemostasis</b> by endoscopy, and <b>suppress acid with a PPI</b> to stabilize the clot.","terms":[],"cards":[{"t":"Fluids and blood","tag":"","topic":"47-upper-gi-bleeding-and-ulcer-emergencies","text":"start <b>isotonic</b> fluid at once (<b>0.9% normal saline or lactated Ringer's</b>); <b>packed RBCs</b> to restore volume and Hgb/Hct; <b>fresh frozen plasma</b> if the PT is more than <b>1.5 times</b> the control. Watch I&amp;O and, in <b>older adults, fluid overload</b>; check electrolytes and <b>replace</b> what vomiting and NG suction remove (e.g., <b>K⁺</b>); trend <b>Hgb, Hct and coagulation studies</b> against baseline. Under <b>500 mL</b> loss: mild weakness and sweating. <b>Over 1 L in 24 hours</b>: <b>hypovolemic shock</b> — hypotension, chills, palpitations, diaphoresis, weak thready pulse.","bullets":["<b>NS or LR</b> now; <b>PRBCs</b>; <b>FFP</b> if PT &gt; 1.5× control","I&amp;O; <b>older adults → overload</b>","<b>Replace lytes</b> lost to vomiting/NG (K⁺); trend <b>Hgb/Hct + clotting</b> vs baseline","&lt; 500 mL: weak, sweaty · <b>&gt; 1 L/24 h → shock</b>"],"why":"<b>Coffee-ground</b> vomitus means blood has sat in the stomach long enough for acid to turn hemoglobin brown — bleeding that is slower or older. <b>Bright red</b> means fast, fresh bleeding. <b>Melena</b> is blood digested on its way through the small intestine. Reading the color tells you how fast and how far up the bleeding is."},{"t":"NG tube","tag":"","topic":"47-upper-gi-bleeding-and-ulcer-emergencies","text":"a <b>large-bore NG tube</b> to: <b>find blood</b> in the stomach, <b>assess the rate</b> of bleeding, <b>prevent gastric dilation</b>, and <b>decompress</b> to rest the GI tract.","bullets":["<b>Large-bore NG</b>: detect blood, judge rate, prevent dilation, decompress"],"why":""},{"t":"Endoscopic hemostasis","tag":"","topic":"47-upper-gi-bleeding-and-ulcer-emergencies","text":"EGD stops bleeding by <b>injecting chemicals</b>, applying <b>heat, electric current or laser</b>, or <b>banding or clipping</b> the vessel. Before: one or two <b>large-bore IVs</b> (moderate sedation, e.g., <b>midazolam</b> plus an opioid; transfusion), <b>NPO 4–6 hours</b>, signed <b>consent</b>. <b>After: VS, heart rhythm and SpO₂ until baseline; check swallowing — no food or fluid until the gag reflex returns</b> (the throat was numbed).","bullets":["EGD: <b>inject, heat/laser, band or clip</b>","Before: <b>large-bore IVs</b> (midazolam + opioid, blood), <b>NPO 4–6 h</b>, consent","After: VS, rhythm, SpO₂; <b>nothing by mouth until gag reflex returns</b>"],"why":""}]},{"k":"ta","gist":"<b>ABCs</b>: oxygen, <b>two large-bore IVs</b>, isotonic fluid and blood products; trend <b>VS, Hgb/Hct and SpO₂</b>; keep <b>NPO</b> and prepare for <b>EGD</b>.","terms":[],"cards":[{"t":"Critical rescue","tag":"","topic":"47-upper-gi-bleeding-and-ulcer-emergencies","text":"active upper GI bleeding is <b>life-threatening</b>: priority is <b>airway, breathing and circulation</b> — <b>oxygen</b> and ventilatory support as needed, <b>two large-bore IV lines</b> for fluids and blood, and monitoring of <b>vital signs, hematocrit and SpO₂</b>.","bullets":["<b>ABCs</b>: <b>oxygen</b>, <b>2 large-bore IVs</b>","Monitor <b>VS, Hct, SpO₂</b>"],"why":""},{"t":"If bleeding continues","tag":"","topic":"47-upper-gi-bleeding-and-ulcer-emergencies","text":"<b>catheter-directed embolization</b> by interventional radiology (usually femoral access; an arteriogram finds the bleeder and material is injected to stop it) — care like any percutaneous vascular procedure. Then <b>aggressive acid suppression with PPIs</b> to <b>stabilize the clot</b> by raising gastric pH and prevent rebleeding; once bleeding stops, PPIs are also the main drug for <b>healing the ulcer</b>.","bullets":["<b>Embolization</b> (arteriogram, femoral) if scopes fail","<b>PPIs</b> raise pH → <b>stabilize the clot</b>; then <b>heal the ulcer</b>"],"why":""}]},{"k":"eo","gist":"<b>Hemodynamically stable</b>, <b>no orthostatic changes</b>, Hgb/Hct stable, no further bleeding; the client avoids NSAIDs, completes <b><i>H. pylori</b></i> therapy and can state when to seek care.","terms":[],"cards":[{"t":"Evaluate","tag":"","topic":"47-upper-gi-bleeding-and-ulcer-emergencies","text":"no active PUD or <i>H. pylori</i>; pain relieved; the drugs are taken as prescribed (including the full <i>H. pylori</i> course) and the client avoids NSAIDs, alcohol, tobacco, bedtime snacks and the foods that cause pain; no upper GI bleeding — or bleeding controlled promptly.","bullets":["No PUD/<i>H. pylori</i>; pain controlled","Takes drugs (full <i>H. pylori</i> course); <b>no NSAIDs, alcohol, tobacco</b>, bedtime snacks","<b>No bleeding</b>"],"why":""},{"t":"Going home","tag":"","topic":"47-upper-gi-bleeding-and-ulcer-emergencies","text":"discharge when there is <b>no ongoing bleeding, no orthostatic changes and no cardiopulmonary distress</b>. After major surgery or hemorrhage, one or two <b>home care visits</b>, especially for <b>older adults</b>. Home care (Box 47.3): VS with orthostatics, skin color, pain, <b>stool color and consistency</b>, bowel pattern, <b>Hgb/Hct</b>, bowel sounds; diet and <b>caffeine and alcohol</b>; understanding of drugs (<b>avoid NSAIDs</b>), smoking cessation. <b>Action alert — seek care at once</b> for <b>sudden, sharp, severe epigastric or abdominal pain</b>, <b>bloody or black stools</b>, or <b>bloody or coffee-ground vomit</b>.","bullets":["Discharge: <b>no bleeding, no orthostatics</b>, stable heart + lungs","After surgery/hemorrhage: <b>home care visits</b> (esp. <b>older adults</b>)","Home: orthostatics, <b>stool color</b>, Hgb/Hct, <b>no NSAIDs</b>, no smoking","Seek care: <b>sudden severe pain</b>, <b>black/bloody stool</b>, <b>coffee-ground vomit</b>"],"why":""}]}]},{"id":"gastric-cancer","ch":"47","sys":"Digestion & elimination","name":"Gastric cancer, gastrectomy and dumping syndrome","patient":"Two weeks after a subtotal gastrectomy for gastric cancer, a client becomes dizzy, sweaty and tachycardic 15 minutes after a large meal with a milkshake.","topics":["47-gastric-cancer-and-life-after-gastrectom"],"report":["Two weeks after a subtotal gastrectomy, 15 minutes after a large meal with a milkshake, the client is dizzy and diaphoretic; HR 118, BP 102/64. Now lying down and improving.","Gastric adenocarcinoma; subtotal gastrectomy two weeks ago, advancing diet at home.","Early dumping syndrome; at risk for late dumping with hypoglycemia in 1–3 hours.","Requesting a dietitian consult for dumping-diet teaching. I will recheck vital signs and glucose in 1–2 hours."],"guide":[{"key":"47:1","name":"Upper GI bleeding & gastric cancer"}],"nodes":[{"id":"ugib","name":"Upper GI bleeding & gastric surgery"},{"id":"fluids","name":"Water follows solute"},{"id":"insulin","name":"Insulin, glucagon & glucose"}],"drugs":[{"id":"octreotide","name":"Octreotide"},{"id":"fluorouracil","name":"Fluorouracil (5-FU) with leucovorin"}],"videos":[],"steps":[{"k":"rc","gist":"Cancer: <b>chronic dyspepsia relieved by antacids at first</b>, early fullness, then <b>weight loss, iron deficiency anemia, vomiting, an epigastric mass</b>. After gastrectomy: <b>early dumping</b> (within about 20 minutes), <b>late dumping</b> (1–3 hours), and <b>acute gastric dilation</b>.","terms":[{"t":"Early dumping syndrome","see":"Within about 20 minutes of eating: vertigo, tachycardia, palpitations, sweating, pallor, the urge to lie down; abdominal fullness.","why":"Without the stomach and pylorus to hold food back, a <b>concentrated meal rushes into the small intestine</b> and <b>pulls fluid from the blood into the bowel</b>. Circulating volume drops and the bowel distends.","means":"Have the client <b>lie down</b> and report. Prevention: small meals, <b>no liquids with meals</b>, high protein and fat, low carbohydrate, <b>lie flat briefly after eating</b>."},{"t":"Late dumping syndrome","see":"1–3 hours after eating: dizziness, light-headedness, palpitations, diaphoresis, confusion.","why":"Sugar from the meal is absorbed in a rush, glucose spikes, and the pancreas <b>overshoots with insulin</b>, causing <b>hypoglycemia</b>.","means":"Check <b>glucose</b> and treat a low; avoid <b>concentrated sweets</b>. Acarbose or octreotide may be prescribed in severe cases."},{"t":"Acute gastric dilation","see":"Epigastric pain, fullness, <b>hiccups</b>, tachycardia, hypotension; little or no NG drainage.","why":"A <b>clogged NG tube</b> lets the remaining stomach fill with fluid and gas it cannot empty; the distended stomach presses on the diaphragm and strains the suture line.","means":"Notify the surgeon for an order to <b>irrigate or replace</b> the tube — don’t reposition it on your own."},{"t":"Iron deficiency anemia and occult blood","see":"Fatigue, pallor, low Hgb/Hct, positive stool occult blood.","why":"The tumor <b>bleeds slowly</b> into the stomach.","means":"Often found before any obvious bleeding — report and trend Hgb/Hct."},{"t":"B₁₂ deficiency after gastrectomy","see":"Smooth, shiny, “beefy” red tongue (atrophic glossitis), fatigue, megaloblastic anemia, numbness.","why":"The removed stomach made <b>intrinsic factor</b>, which the body needs to absorb <b>vitamin B₁₂</b>.","means":"<b>Lifelong B₁₂ injections</b> as prescribed; iron, folic acid, calcium and vitamin D absorption also fall."}],"cards":[{"t":"Signs (Box 47.4)","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"<b>early</b>: <b>chronic dyspepsia</b> and abdominal discomfort <b>relieved by antacids at first</b> (often ignored), fullness, epigastric, back or retrosternal pain. <b>Advanced</b>: <b>nausea and vomiting</b>, <b>iron deficiency anemia</b>, a <b>palpable epigastric mass</b>, <b>enlarged lymph nodes</b>, weakness, fatigue, <b>progressive weight loss</b>. Labs: low Hgb/Hct (micro- or macrocytic), <b>occult blood</b>, low albumin, abnormal liver tests with metastasis, <b>elevated CEA</b>.","bullets":["<b>Early</b>: dyspepsia <b>relieved by antacids</b> (ignored), fullness","<b>Late</b>: vomiting, <b>anemia</b>, <b>epigastric mass</b>, nodes, <b>weight loss</b>","Labs: anemia, <b>occult blood</b>, ↓ albumin, <b>↑ CEA</b>"],"why":""},{"t":"Early dumping syndrome","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"vasomotor symptoms <b>within about 20 minutes</b> of eating as food rushes into the small intestine and <b>pulls fluid into the gut</b> → distention and a drop in circulating volume: <b>vertigo, tachycardia, syncope, sweating, pallor, palpitations, the urge to lie down</b>. Report and <b>have the patient lie down</b>.","bullets":["<b>~20 min</b> after eating: food rushes in, <b>pulls fluid into gut</b>","<b>Vertigo, tachycardia, sweating, pallor, palpitations, syncope</b>","<b>Lie down</b>, report"],"why":"Without a stomach to hold food and release it slowly, a meal hits the small intestine all at once. The concentrated contents <b>draw water into the bowel</b> (early dumping looks like a sudden drop in blood volume), and the sugar is absorbed in a rush that provokes an <b>insulin overshoot</b> an hour or two later (late dumping looks like hypoglycemia). Every dumping rule — small meals, no fluids with meals, little sugar, more protein and fat, lying down — <b>slows the delivery</b>."},{"t":"Late dumping syndrome","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"<b>1–3 hours</b> after eating: carbohydrate enters the jejunum fast → glucose spikes → <b>too much insulin</b> → <b>hypoglycemia</b>: <b>dizziness, light-headedness, palpitations, diaphoresis, confusion</b>.","bullets":["<b>1–3 h</b>: glucose spike → <b>excess insulin</b> → <b>hypoglycemia</b> (dizzy, sweaty, confused)"],"why":""},{"t":"Acute gastric dilation","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"a <b>clogged NG tube</b> lets the stomach distend: <b>epigastric pain, fullness, hiccups, tachycardia, hypotension</b> → notify the surgeon for an order to <b>irrigate or replace</b> the tube.","bullets":["Clogged NG → <b>pain, fullness, hiccups, tachycardia, hypotension</b>","Get an order to <b>irrigate/replace</b>"],"why":""}]},{"k":"ac","gist":"Mostly <b>adenocarcinoma</b>, arising from chronic <b><i>H. pylori</b></i> and <b>atrophic gastritis</b>; spreads to nodes, liver, lungs, bone and the peritoneum, and is often found late. After gastrectomy the lost reservoir and pylorus cause <b>dumping</b>, and lost <b>intrinsic factor</b> causes <b>B₁₂ deficiency</b>.","terms":[],"cards":[{"t":"The disease","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"mostly <b>adenocarcinoma</b> of the mucosal glands; more common in <b>men</b>, rising sharply <b>after 65</b>. Precancerous: <b>atrophic gastritis</b> and <b>intestinal metaplasia</b> — low acid lets bacteria (<i>H. pylori</i>) multiply; it can also cause <b>MALT lymphoma</b>. Spreads through the wall to <b>lymph nodes</b>, directly into the liver, pancreas and colon, through the <b>portal vein to the liver</b> and blood to <b>lungs and bones</b> (blood-borne spread is the <b>most common</b> route of metastasis), and by <b>peritoneal seeding</b>. <b>5-year survival ~30%</b> (late diagnosis) but <b>~70%</b> if found early.","bullets":["<b>Adenocarcinoma</b>; <b>men</b>, <b>after 65</b>","Precancer: <b>atrophic gastritis</b>, intestinal metaplasia","Spreads: nodes, <b>liver</b> (portal vein), lungs, bones, peritoneum; <b>blood-borne = most common</b>","<b>5-yr survival 30%</b> → <b>70% if early</b>"],"why":""},{"t":"Risk factors","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"<b><i>H. pylori</b></i> is the <b>largest</b> (CagA gene). <b>Pernicious anemia, gastric polyps, chronic atrophic gastritis and achlorhydria</b> raise risk 2–3 times. Diet: <b>pickled foods, nitrates in processed food, added salt</b>, <b>few fruits and vegetables</b> (screen for <b>food insecurity</b> and link the patient to community food resources). Past <b>gastric surgery</b>; <b>Barrett's esophagus</b> (cancer at the cardia). Higher incidence and mortality in <b>non-White groups</b>, especially Black and Hispanic people, and highest in <b>Korean and Japanese Americans</b> — smoking, untreated <i>H. pylori</i>, poor access to care and to pre-surgery chemotherapy.","bullets":["<b><i>H. pylori</b></i> = <b>largest risk</b>","Pernicious anemia, polyps, atrophic gastritis, achlorhydria (<b>2–3×</b>)","<b>Pickled, nitrates, salt</b>; few fruits/veg; <b>food insecurity</b> → food resources","Gastric surgery; Barrett's (cardia)","↑ in <b>non-White</b> groups; highest <b>Korean + Japanese Americans</b>"],"why":""},{"t":"Diagnose and treat","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"<b>EGD with biopsy</b> (definitive) plus <b>endoscopic ultrasound</b> for depth and nodes; CT, PET and MRI for extent. Treatment depends on the <b>stage</b>: <b>chemotherapy</b> before and after surgery (oxaliplatin, fluorouracil, cisplatin, epirubicin — marrow suppression, nausea, vomiting); chemo and radiation <b>prolong survival</b> in advanced disease, but <b>radiation</b> is limited (spread, organ tolerance). <b>Surgery is preferred</b>: <b>subtotal gastrectomy</b> for mid or distal tumors, <b>total gastrectomy</b> (esophagus joined to the jejunum or duodenum; Fig. 47.3) for proximal tumors, with omentum and nodes; in early stages <b>laparoscopic resection plus chemo or radiation may cure</b>, and <b>laparoscopic + ERAS</b> recovers faster. Spread to supraclavicular or inguinal nodes, liver, umbilicus or perirectal wall means <b>cure is no longer possible</b> — <b>palliative</b> surgery (e.g., <b>gastroenterostomy</b> for outlet obstruction) for obstruction, bleeding or pain.","bullets":["<b>EGD + biopsy</b>, <b>EUS</b>; CT/PET/MRI","By <b>stage</b>: <b>chemo</b> around surgery; chemo/radiation <b>prolong survival</b> when advanced; radiation limited","<b>Subtotal</b> (distal) or <b>total</b> (proximal; Fig. 47.3) gastrectomy","Early: <b>lap resection + chemo/radiation may cure</b>; <b>lap + ERAS</b> faster","Distant spread → <b>palliation</b> (gastroenterostomy)"],"why":""}]},{"k":"ph","gist":"After surgery: <b>lungs</b> (atelectasis, pneumonia), <b>bleeding</b>, <b>gastric dilation</b> and anastomotic problems, <b>paralytic ileus</b>, wound infection; then <b>imbalanced nutrition</b> (dumping, B₁₂) and <b>coping</b> with cancer.","terms":[],"cards":[{"t":"Routine care","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"prevent <b>atelectasis, paralytic ileus, wound infection and peritonitis</b>: lung sounds, <b>return of bowel sounds</b>, vital signs for infection or bleeding, aggressive pulmonary exercises and <b>early walking</b> (lungs, DVT), incision checks <b>every 8–12 hours</b>, <b>head of bed up</b> (reflux and aspiration).","bullets":["Watch <b>atelectasis, ileus, infection, peritonitis</b>","Lungs, <b>bowel sounds</b>, VS, <b>walk early</b>","Incision <b>q8–12h</b>; <b>HOB up</b>"],"why":""}]},{"k":"gs","gist":"Surgery (subtotal or total gastrectomy) with chemotherapy as staged; correct <b>malnutrition</b> before surgery; prevent pulmonary and surgical complications; <b>slow food delivery</b> to control dumping; replace <b>B₁₂</b>; support coping and palliative care when needed.","terms":[],"cards":[{"t":"Before surgery","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"open surgery: an <b>NG tube to suction</b> empties the stomach so secretions don't contaminate the peritoneum, and stays a few days after (prevents vomiting and distention). Laparoscopic surgery doesn't need one. Correct <b>malnutrition</b> first — enteral supplements or <b>TPN</b>, vitamins, minerals, <b>iron and protein</b>.","bullets":["Open: <b>NG to suction</b> before + a few days after","Fix <b>malnutrition</b>: supplements or <b>TPN</b>, iron, protein"],"why":""},{"t":"Managing dumping","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"<b>small amounts at a time</b>; <b>no liquids with meals</b>; <b>high-protein, high-fat, low- to moderate-carbohydrate</b> diet (with the dietitian); <b>avoid concentrated sweets</b>; <b>lie down flat for a short time after eating</b> (slows emptying). Drugs: <b>acarbose</b> (slows carbohydrate absorption); in severe cases <b>octreotide</b> (somatostatin analog) 2–4 times a day <b>30 minutes before meals</b> to slow transit and reduce gut hormones.","bullets":["<b>Small meals</b>, <b>no liquids with meals</b>","<b>High protein + fat, low–moderate carbs</b>, no sweets","<b>Lie down after eating</b>","<b>Acarbose</b>; <b>octreotide</b> 30 min before meals (severe)"],"why":""}]},{"k":"ta","gist":"Lung sounds, <b>deep breathing and early walking</b>, <b>head of bed up</b>; keep the <b>NG tube patent</b> and report signs of dilation; check bowel sounds and the incision every 8–12 hours. Dumping diet: <b>small meals, no liquids with meals</b>, high protein and fat, low carbohydrate, <b>no concentrated sweets</b>, <b>lie flat briefly after eating</b>; B₁₂ injections.","terms":[],"cards":[{"t":"Other problems","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"<b>delayed gastric emptying</b> for about a week (edema at the anastomosis, adhesions, or low K⁺, protein or Na⁺) — resolves with NG suction, fluids, electrolytes and nutrition. <b>Vitamin B₁₂, folic acid and iron deficiency</b>, poor <b>calcium and vitamin D</b> absorption — less <b>intrinsic factor</b> and fast transit. Watch for <b>pernicious anemia</b>, <b>atrophic glossitis</b> (shiny, smooth, <b>\"beefy\" tongue</b>), <b>megaloblastic anemia and leukopenia</b> on the CBC → <b>vitamin B₁₂</b> (plus folic acid or iron).","bullets":["<b>Delayed emptying ~1 week</b> (edema, low K⁺/protein/Na⁺)","↓ <b>B₁₂, folate, iron, Ca, vit D</b> (no intrinsic factor)","<b>Beefy tongue</b>, <b>megaloblastic anemia</b> → <b>B₁₂ injections</b>"],"why":""}]},{"k":"eo","gist":"Lungs clear, walking, bowel sounds back; eating small meals <b>without dumping symptoms</b>; weight stable; B₁₂ replaced; the client and family know the diet, infection signs and follow-up — recurrence is common.","terms":[],"cards":[{"t":"Going home","tag":"","topic":"47-gastric-cancer-and-life-after-gastrectom","text":"total gastrectomy or advanced disease → maximal help at home, transitional care or a skilled facility; subtotal gastrectomy without debility → home with partial help with ADLs; <b>recurrence is common</b> — regular follow-up and imaging, coordinated with the case manager. Teach dressing changes and <b>infection signs</b>; chemo and radiation side effects and <b>antiemetics</b>. Diet: <b>small, frequent meals</b>, <b>no liquids with meals</b>, <b>no concentrated sweets</b> (dumping), avoid foods that cause discomfort, <b>no caffeine or alcohol</b>, stop smoking, <b>B₁₂ injections as prescribed</b>, <b>lie flat briefly after eating</b>. Support coping; <b>hospice</b> and end-of-life care when needed; home care, dietitian, counselor or spiritual referral; cancer support groups.","bullets":["Total/advanced → <b>maximal help</b> or SNF; subtotal → partial help","<b>Recurrence common</b> → follow-up + imaging (case manager)","Infection signs; <b>antiemetics</b>","<b>Small meals, no liquids with meals</b>, no caffeine/alcohol, <b>B₁₂ shots</b>, <b>lie flat after eating</b>","Coping, <b>hospice</b> when needed"],"why":""}]}]},{"id":"endo-aging","ch":"53","sys":"Hormones & glucose","name":"The pancreas, thyroid and parathyroid glands, and endocrine aging","patient":"An 84-year-old in long-term care is always cold, drinks little, and has a foot sore that hasn’t healed in three weeks.","topics":["53-pituitary-thyroid-parathyroid-and-pancre","53-aging-and-covid-19-what-changes-in-the-g"],"report":["The 84-year-old resident is newly confused with dry mucous membranes, low urine output and a sodium of 151 mEq/L; temperature 96.6°F, HR 56. A foot wound hasn’t healed in 3 weeks.","Drinks little; no diabetes or thyroid diagnosis on record.","Dehydration, likely from reduced ADH reserve and low intake; the slow-healing wound, persistent low temperature and slow heart rate go beyond expected aging.","Requesting orders for fluids and a BMP, and screening for diabetes (glucose, A1C) and thyroid function (TSH)."],"guide":[{"key":"53:0","name":"Pancreas, thyroid & parathyroid"},{"key":"53:1","name":"Endocrine changes with aging"}],"nodes":[{"id":"endo-axis","name":"Glands, feedback & endocrine tests"},{"id":"thyroid","name":"Thyroid hormone & metabolic rate"},{"id":"calcium","name":"Calcium, PTH & nerve excitability"},{"id":"insulin","name":"Insulin, glucagon & glucose"}],"drugs":[],"videos":[{"id":"eWHH9je2zG4","title":"Endocrine System, Part 1 — Glands & Hormones (Crash Course A&P)","see":"Water-soluble vs lipid-soluble hormones, and why that changes how fast and how long they act"},{"id":"SCV_m91mN-Q","title":"Endocrine System, Part 2 — Hormone Cascades (Crash Course A&P)","see":"Hypothalamus → pituitary → target gland, and the negative feedback that switches each cascade off"}],"steps":[{"k":"rc","gist":"Expected aging changes look like <b>mild hypothyroidism and mild diabetes</b>: less cold tolerance, lower heart rate and BP, less appetite, <b>dilute urine and dehydration risk</b>, thinner skin and bone loss, higher fasting glucose. The cues that go <b>beyond</b> aging: temperature consistently <b>below 97°F</b>, heart rate consistently <b>below 60</b>, a wound <b>not healed in 2 weeks</b>, thirst or hunger that won’t stop, new constipation or slowed thinking.","terms":[{"t":"Dilute urine and dehydration (less ADH)","see":"Pale urine even when intake is low; dry mouth, confusion, rising sodium.","why":"Older adults release <b>less ADH (vasopressin)</b>, so the kidneys can’t concentrate urine and conserve water when intake falls.","means":"<b>High dehydration risk</b> — assess often and offer fluids <b>at least every 2 hours</b> while awake unless restricted."},{"t":"Bone loss, thin skin and cystitis (less estrogen)","see":"Fractures, skin tears, dry perineal and vaginal tissue, UTIs.","why":"Estrogen supports <b>bone density</b>, skin thickness and the health of perineal and vaginal tissue.","means":"Weight-bearing exercise, protein, about <b>2 L of fluid</b> a day unless restricted, skin protection and perineal care."},{"t":"Higher glucose, slow healing and yeast infections (less glucose tolerance)","see":"Elevated fasting or random glucose, wounds that heal slowly, repeated vaginal yeast infections, thirst and frequent urination.","why":"Cells respond less to insulin with age, and <b>high glucose impairs healing and feeds yeast</b>.","means":"Suggest <b>diabetes testing</b> for a wound not healed in 2 weeks, persistent candidiasis, or lasting hunger, thirst or fatigue."},{"t":"Cold intolerance and a lower heart rate (slower metabolism)","see":"Feels cold, less appetite, lower HR and BP.","why":"The <b>basal metabolic rate</b> falls with age.","means":"Dress in layers. A temperature <b>consistently below 97°F</b>, HR <b>consistently below 60</b>, lethargy, new constipation or slowed speech suggest <b>hypothyroidism</b> — report for testing."}],"cards":[{"t":"The general rule","tag":"","topic":"53-aging-and-covid-19-what-changes-in-the-g","text":"aging usually means <b>less glandular function and less hormone</b>. The notable exception: the <b>prostate enlarges</b> (hyperplasia). Ovarian function falls faster and more noticeably, and abruptly after a <b>hysterectomy</b> (surgical menopause). Chronic illness, diet and activity changes, poor sleep, slower metabolism and drugs make normal and abnormal hard to tell apart, so encourage regular screening.","bullets":["Aging → <b>less gland function + less hormone</b>","Exception: <b>prostate enlarges</b> · ovaries decline faster (abrupt after <b>hysterectomy</b>)","Illness, diet, sleep, drugs blur normal vs abnormal → <b>regular screening</b>"],"why":"The older adult's normal changes look like mild hypothyroidism and mild diabetes, so the job is to spot the <b>difference from their own baseline</b> and the findings that go further — a temperature that stays below 97°F, a wound that will not heal in two weeks, thirst that will not stop. Low ADH reserve is the one that turns dangerous fastest: an older patient who simply drinks less becomes dehydrated quickly."},{"t":"Less ADH","tag":"","topic":"53-aging-and-covid-19-what-changes-in-the-g","text":"urine stays <b>dilute</b> and may not concentrate when intake is low → <b>high risk for dehydration</b>. Assess for it often, and teach assistive personnel to <b>offer fluids at least every 2 hours</b> while awake unless restricted.","bullets":["↓ ADH → <b>dilute urine</b>, can't concentrate → <b>dehydration risk</b>","Assess often · AP <b>offer fluids at least every 2 h</b> awake (unless restricted)"],"why":""},{"t":"Less estrogen","tag":"","topic":"53-aging-and-covid-19-what-changes-in-the-g","text":"<b>bone density falls</b>; skin becomes thinner, drier and easier to injure; perineal and vaginal tissues dry and <b>cystitis risk rises</b>. Teach <b>weight-bearing exercise</b>, adequate protein and <b>2 L of fluid</b> daily (unless contraindicated), <b>protect skin integrity</b>, perineal care at least twice a day, voiding right after intercourse, and vaginal lubricants.","bullets":["↓ estrogen → <b>bone loss</b>, thin dry skin, dry perineal tissue → <b>↑ cystitis</b>","Teach <b>weight-bearing exercise</b>, protein, <b>2 L fluid/day</b> (unless contraindicated), perineal care ≥ 2×/day, void after sex, lubricants","<b>Protect skin integrity</b>"],"why":""},{"t":"Less glucose tolerance","tag":"","topic":"53-aging-and-covid-19-what-changes-in-the-g","text":"weight above ideal with <b>elevated fasting or random glucose</b>, <b>slow wound healing</b>, <b>frequent yeast infections</b>, <b>polydipsia and polyuria</b>. Ask about family history of obesity and type 2 diabetes, teach exercise, a healthy weight and the <b>signs of diabetes to report</b> (<b>thirst, frequent urination, constant hunger, slow-healing wounds, repeated yeast infections, blurred vision, fatigue</b>), and suggest diabetes testing for persistent vaginal candidiasis, <b>a wound not healed within 2 weeks</b> (especially leg or foot), persistent hunger and thirst, or a lasting drop in energy.","bullets":["↓ glucose tolerance → weight above ideal, ↑ fasting/random glucose, <b>slow healing</b>, <b>yeast infections</b>, <b>polydipsia + polyuria</b>","Ask family history (obesity, T2DM) · teach exercise, healthy weight","Report: <b>thirst, frequent urination, hunger, slow healing, yeast infections, blurred vision, fatigue</b>","Suggest <b>diabetes testing</b>: persistent candidiasis, <b>wound not healed in 2 weeks</b> (leg/foot), lasting hunger + thirst, ↓ energy"],"why":""},{"t":"Slower general metabolism","tag":"","topic":"53-aging-and-covid-19-what-changes-in-the-g","text":"<b>less cold tolerance</b>, less appetite, lower heart rate and blood pressure. Teach dressing in layers. Look for signs of a real endocrine disorder: lethargy, new constipation, slowed thinking or speech, temperature consistently <b>below 97°F (36°C)</b>, heart rate consistently <b>below 60</b>.","bullets":["↓ metabolism → <b>cold intolerance</b>, ↓ appetite, ↓ HR + BP → dress in layers","Disorder clues: lethargy, new constipation, slow thinking/speech, temp <b>&lt; 97°F (36°C)</b>, HR <b>&lt; 60</b>"],"why":""}]},{"k":"ac","gist":"The glands run on <b>feedback</b>: <b>TRH → TSH → T3/T4</b>, with high hormone switching the axis off; <b>PTH</b> raises calcium from bone, kidney (and vitamin D) and gut while <b>calcitonin</b> lowers it; the pancreas’s <b>alpha cells make glucagon</b> (raises glucose) and <b>beta cells make insulin</b> (the only hormone that lowers it). Aging generally means <b>less</b> gland function and hormone.","terms":[{"t":"The thyroid axis","see":"TRH (hypothalamus) → TSH (pituitary) → T3 and T4 (thyroid).","why":"<b>Negative feedback</b>: high T3/T4 switch off TRH and TSH; low levels turn them up. Cold and stress raise TRH. <b>T4 is converted to T3</b>, the most active form, inside cells.","means":"Read TSH <b>against</b> the thyroid hormone level — high TSH with low T4 means the thyroid itself is failing."},{"t":"What thyroid hormone does","see":"Sets the metabolic rate, heat, heart rate and force, breathing, gut secretion and muscle tone.","why":"It enters cells and switches on the genes that set the <b>basal metabolic rate</b>, so every tissue uses more oxygen and makes more heat.","means":"Too much speeds every system; too little slows every system — the basis of chapter 55."},{"t":"PTH and calcitonin","see":"PTH raises serum calcium; calcitonin lowers it.","why":"<b>PTH</b> releases calcium from <b>bone</b>, makes the <b>kidney</b> keep calcium and excrete phosphorus and <b>activate vitamin D</b>, which raises <b>gut</b> absorption. Low calcium raises PTH; high calcium lowers it. <b>Calcitonin</b> reduces release from bone.","means":"The parathyroids sit on the back of the thyroid — after thyroid surgery calcium can fall within hours."},{"t":"Glucagon, insulin and somatostatin","see":"Alpha cells → glucagon · beta cells → insulin · delta cells → somatostatin.","why":"<b>Glucagon raises glucose</b> when it falls; <b>insulin lowers it</b> by moving it into cells and storing fuel; somatostatin inhibits both. Growth hormone, cortisol, epinephrine and thyroid hormone also push glucose <b>up</b>.","means":"Insulin is the <b>only</b> hormone that lowers glucose — which is why so many illnesses and drugs raise it."}],"cards":[{"t":"Control — the thyroid axis","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"the hypothalamus secretes <b>TRH</b> → the anterior pituitary secretes <b>TSH</b> → the thyroid makes and releases <b>T3 and T4</b>. <b>High</b> thyroid hormone levels inhibit TRH and TSH release; <b>low</b> levels increase it (negative feedback). <b>Cold and stress</b> also make the hypothalamus secrete TRH, which raises TSH.","bullets":["<b>TRH → TSH → T3 + T4</b>","High T3/T4 → ↓ TRH + TSH · low → ↑ (negative feedback)","<b>Cold + stress</b> → ↑ TRH → ↑ TSH"],"why":"Thyroid hormone is the body's <b>thermostat and accelerator</b> at once. Too much speeds every system — heat intolerance, fast heart, diarrhea, weight loss; too little slows every system — cold intolerance, slow heart, constipation, weight gain. Learn the function list in Box 53.2 and you can predict both diseases in chapter 55 without memorizing them separately."},{"t":"T3 and T4 set the metabolic rate","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"both raise metabolism, so every tissue uses more <b>oxygen</b> and makes more <b>heat</b>. Most circulating hormone is bound to plasma proteins; the <b>free</b> hormone enters cells, where <b>T4 is converted to T3, the most active form</b>. Conversion is impaired by <b>stress, starvation, dyes and some drugs</b>; <b>cold</b> increases it.","bullets":["↑ metabolism → ↑ <b>O₂ use</b> + ↑ <b>heat</b>","Mostly protein-bound; <b>free</b> hormone acts","In cells <b>T4 → T3 (most active)</b>; ↓ by stress, starvation, dyes, drugs; ↑ by <b>cold</b>"],"why":""},{"t":"What thyroid hormones do (Box 53.2)","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"regulate the metabolic rate of all cells and <b>body heat</b>; act as <b>insulin antagonists</b>; support growth hormone, skeletal maturation and nervous system development; maintain <b>muscle tone</b>, calcium mobilization and RBC production; maintain <b>cardiac rate, force and output</b>, respiratory rate and oxygen use, and <b>GI secretion</b>; regulate protein, carbohydrate and fat metabolism and stimulate lipid turnover and cholesterol synthesis.","bullets":["Set metabolic rate + <b>body heat</b> · <b>insulin antagonists</b>","Growth, skeleton, nervous system development · muscle tone, Ca²⁺ mobilization, RBCs","<b>Heart rate, force, output</b> · breathing + O₂ use · <b>GI secretion</b>","Protein, carb, fat metabolism; lipid turnover, cholesterol synthesis"],"why":""},{"t":"Parathyroid hormone (PTH) raises calcium","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"four small glands on the back of the thyroid. PTH acts on three targets: <b>bone</b>, the main calcium store — releases calcium and phosphorus into the blood (resorption); <b>kidney</b> — reabsorbs calcium (and magnesium), excretes phosphorus, and <b>activates vitamin D</b>; <b>gut</b> — activated vitamin D increases calcium and phosphorus absorption. <b>Low calcium raises PTH; high calcium lowers it.</b>","bullets":["4 glands behind the thyroid; <b>PTH raises Ca²⁺</b>","<b>Bone</b> (main Ca²⁺ store): releases Ca²⁺ + phosphorus · <b>kidney</b>: keeps Ca²⁺, dumps phosphorus, <b>activates vitamin D</b> · <b>gut</b>: ↑ absorption","<b>Low Ca²⁺ → ↑ PTH</b>; high Ca²⁺ → ↓ PTH"],"why":"Calcium is guarded by two opposing hormones: <b>PTH pulls calcium into the blood</b> (from bone, kidney and gut), <b>calcitonin pushes it back into bone</b>. An older woman with repeated fractures is therefore a calcium question first — and when the parathyroid glands are bruised or removed during thyroid surgery (chapter 55), calcium falls within hours."},{"t":"Calcitonin","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"<b>lowers serum calcium and phosphate</b> by reducing their release from bone — the opposite of PTH. <b>High</b> calcium increases calcitonin secretion; <b>low</b> calcium suppresses it.","bullets":["<b>Lowers Ca²⁺ + phosphate</b> (less bone release) — opposite of PTH","High Ca²⁺ → ↑ calcitonin; low Ca²⁺ → ↓"],"why":""},{"t":"Pancreas — two jobs","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"<b>exocrine</b>: digestive enzymes through ducts into the duodenum. <b>Endocrine</b>: 1–2 million <b>islets of Langerhans</b> with <b>alpha cells (glucagon)</b>, <b>beta cells (insulin)</b> and <b>delta cells (somatostatin)</b>.","bullets":["<b>Exocrine</b>: enzymes → duodenum","<b>Endocrine</b> islets: <b>alpha → glucagon</b>, <b>beta → insulin</b>, <b>delta → somatostatin</b>"],"why":""},{"t":"Glucagon, insulin, somatostatin","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"<b>glucagon raises glucose</b> — released when glucose falls (and amino acids rise) to prevent hypoglycemia. <b>Insulin lowers glucose</b> by moving it into cells and storing carbohydrate, protein and fat; it rises when glucose rises. <b>Somatostatin</b> (pancreas, gut, brain) inhibits glucagon and insulin, and gastrin, secretin and other GI peptides.","bullets":["<b>Glucagon ↑ glucose</b> (released when glucose ↓) · <b>insulin ↓ glucose</b> (moves it into cells, stores fuel)","<b>Somatostatin</b> inhibits insulin, glucagon, gastrin, secretin"],"why":""}]},{"k":"ph","gist":"<b>Dehydration</b> first (low ADH reserve plus blunted thirst), then <b>falls and fractures</b>, <b>skin injury and infection</b>, and <b>missing a real endocrine disorder</b> that looks like normal aging.","terms":[],"cards":[]},{"k":"gs","gist":"Separate <b>normal aging from disease</b> by comparing with the client’s <b>own baseline</b>; prevent dehydration, injury and infection; screen for <b>diabetes and thyroid disease</b> when cues go beyond aging.","terms":[],"cards":[]},{"k":"ta","gist":"Offer fluids <b>at least every 2 hours</b> while awake (unless restricted); weight-bearing exercise and protein; skin and perineal care; dress in layers; teach the <b>signs of diabetes to report</b>; report a temperature consistently below 97°F, HR consistently below 60, or a wound not healed in 2 weeks.","terms":[],"cards":[{"t":"Making the hormone","tag":"","topic":"53-pituitary-thyroid-parathyroid-and-pancre","text":"needs dietary <b>protein and iodine</b>. Iodide absorbed from the gut is trapped and concentrated by the thyroid, joined to the amino acid <b>tyrosine</b> to form T4 and T3, and stored on <b>thyroglobulin</b> in the follicles until TSH releases it. Inside cells the hormones bind DNA receptors and switch on metabolic genes that set the <b>basal metabolic rate</b>.","bullets":["Needs dietary <b>protein + iodine</b>","Thyroid traps iodide + <b>tyrosine</b> → T4/T3 → stored on <b>thyroglobulin</b>","In cells: bind DNA receptors → set <b>basal metabolic rate</b>"],"why":""}]},{"k":"eo","gist":"Hydrated (intake meets needs, no orthostatic drop, clear thinking), skin intact, no falls; findings beyond aging referred for <b>testing</b>; the client or caregiver can name the signs to report.","terms":[],"cards":[]}]},{"id":"endo-testing","ch":"53","sys":"Hormones & glucose","name":"Endocrine assessment and getting tests right","patient":"A client with a round face, a fat pad between the shoulders and purple stretch marks needs a 24-hour urine collection starting at 7 a.m.","topics":["53-endocrine-assessment-history-and-physica","53-diagnostic-tests-and-the-nurse-s-job"],"report":["The 24-hour urine collection that started at 0700 is invalid: a void at 1400 was discarded.","Client being evaluated for adrenal hyperfunction; the collection was ordered to measure hormone output.","The specimen can’t give an accurate result.","Requesting to restart the collection tomorrow at 0700 with a new container. I will notify the lab and post a sign so every void is saved."],"guide":[{"key":"53:2","name":"24-hour urine test"}],"nodes":[{"id":"endo-axis","name":"Glands, feedback & endocrine tests"}],"drugs":[],"videos":[{"id":"Iz0Q9nTZCw4","title":"Homeostasis and negative/positive feedback (Amoeba Sisters)","see":"Negative feedback as the thermostat that keeps a level in range"}],"steps":[{"k":"rc","gist":"Look for <b>the hormone’s fingerprints</b>: a <b>round face, truncal obesity, buffalo hump, purple striae and bruising</b> (cortisol excess); <b>exophthalmos</b>, a <b>visible thyroid</b> or a <b>bruit</b> (thyroid); <b>darkened skin</b> over joints and scars or <b>vitiligo</b> (adrenal hypofunction); <b>orthostatic changes</b>, edema or JVD (fluid hormones); <b>thirst, salt craving, rapid weight change</b>; changes in mood, menses and libido.","terms":[{"t":"Round face, buffalo hump, truncal obesity and purple striae","see":"Moon face, a fat pad between the shoulders, a heavy trunk with thin limbs, reddish-purple stretch marks, easy bruising.","why":"Excess <b>cortisol</b> redistributes fat to the face and trunk and <b>breaks down protein</b>, which thins the skin and vessel walls — so the skin tears into striae and bruises easily.","means":"Points to <b>adrenocortical excess</b> — expect high glucose, infections and slow healing."},{"t":"Darkened skin over joints and scars","see":"Bronze or tan skin, especially over knuckles, elbows, knees and scars.","why":"When the adrenal glands fail, the pituitary makes more <b>ACTH</b>; ACTH and <b>MSH</b> (made from the same precursor) stimulate <b>melanocytes</b>.","means":"A clue to <b>primary adrenal hypofunction</b> — check BP for orthostatic drops and ask about salt craving."},{"t":"A visible thyroid, bruit or exophthalmos","see":"The gland is seen when the client swallows; a whooshing sound over it; protruding eyes.","why":"The thyroid is <b>normally not visible</b>; an enlarged, overactive gland has more blood flow (bruit); Graves antibodies swell the tissues behind the eye.","means":"Needs further assessment. <b>Do not palpate</b> the thyroid if hyperthyroidism is possible — it can trigger <b>thyroid storm</b>."},{"t":"Excessive thirst and salt craving","see":"Drinking large amounts; craving salty foods.","why":"Thirst: too little <b>AVP (ADH)</b> or kidneys that don’t respond to it, so water is lost in the urine — or high glucose. Salt craving: the adrenals make too little <b>aldosterone</b>, so sodium is lost.","means":"Track intake and output, weight and orthostatic vital signs."},{"t":"Orthostatic changes, edema and JVD","see":"BP falls and pulse rises on standing; swelling; distended neck veins.","why":"Hormones such as <b>aldosterone and ADH</b> control sodium and water — too little drops volume, too much expands it.","means":"Record orthostatic BP and pulse lying, sitting and standing as a baseline."}],"cards":[{"t":"Inspection — general and head","tag":"","topic":"53-endocrine-assessment-history-and-physica","text":"height, weight, <b>fat distribution</b> and muscle mass for age; scalp and body hair. Face: <b>prominent forehead or jaw</b>, <b>round or puffy face</b>, dull or flat expression, <b>exophthalmos</b> (protruding eyes with retracted upper lids).","bullets":["Height, weight, <b>fat distribution</b>, muscle mass, hair","Face: <b>prominent forehead/jaw</b>, <b>round puffy face</b>, flat expression, <b>exophthalmos</b>"],"why":"The physical exam is a search for <b>the hormone's fingerprints</b>: cortisol leaves a round face, buffalo hump, striae and bruises; thyroid hormone changes the eyes, nails, heart rate and a visible neck; aldosterone and ADH show up as edema, JVD or orthostatic drops. And the one thing you must not do — pressing on a hyperthyroid gland — follows from the same physiology: the gland is full of stored hormone waiting to be released."},{"t":"Inspection — skin","tag":"","topic":"53-endocrine-assessment-history-and-physica","text":"hypo- or <b>hyperpigmentation</b>; <b>fungal infections, slow healing, bruising and petechiae</b> with adrenal hyperfunction; <b>skin infections, foot ulcers and slow healing</b> with diabetes; <b>darkened skin over joints and scars</b> with some adrenal disorders (high ACTH and MSH); <b>vitiligo</b> with primary adrenal hypofunction (autoimmune loss of melanocytes). Document location, color, size and distribution of any change since the last visit or from the patient's baseline.","bullets":["<b>Adrenal excess</b>: fungal infections, slow healing, bruising, petechiae","<b>Diabetes</b>: skin infections, <b>foot ulcers</b>, slow healing","<b>Dark skin over joints/scars</b> (↑ ACTH, MSH) · <b>vitiligo</b> = primary adrenal hypofunction","Document location, color, size, distribution of changes vs last visit/baseline"],"why":""},{"t":"Inspection — body","tag":"","topic":"53-endocrine-assessment-history-and-physica","text":"nails malformed, thick or brittle (<b>thyroid</b>); <b>edema</b> of extremities and sacrum (fluid balance); chest size and symmetry; <b>truncal obesity and a \"buffalo hump\"</b>, and <b>reddish-purple striae</b> on breasts or abdomen (<b>adrenocortical excess</b>). Look at the <b>breasts in both sexes</b> — size, symmetry, pigment and any discharge — <b>gynecomastia</b> (low testosterone). <b>Hirsutism</b> (excess hair on a woman's face, chest or midline abdomen), excessive scalp hair loss or a change in hair texture, told apart from normal aging. Genitals: the amount and distribution of <b>pubic hair</b> change in <b>hypogonadism</b>; ask whether the <b>scrotum and penis</b> (or <b>labia and clitoris</b>) have changed in size.","bullets":["Nails thick/brittle → <b>thyroid</b> · edema → fluid balance · chest size + symmetry","<b>Truncal obesity + buffalo hump + purple striae</b> → <b>adrenocortical excess</b>","Breasts (<b>men too</b>): size, symmetry, pigment, discharge · <b>gynecomastia</b> (↓ testosterone)","<b>Hirsutism</b> (woman's face, chest, midline abdomen) · scalp hair loss or texture change beyond aging","Genitals: <b>pubic hair</b> change in <b>hypogonadism</b>; ask about change in genital size"],"why":""},{"t":"Nutrition clues","tag":"","topic":"53-endocrine-assessment-history-and-physica","text":"excessive <b>thirst</b> with AVP deficiency or resistance (formerly diabetes insipidus); <b>salt craving</b> with adrenal hypofunction; persistent <b>hunger and thirst</b> with diabetes; <b>rapid weight change without diet change</b> with thyroid or hypothalamic disease. <b>Iodine</b> is needed to make thyroid hormone and the body cannot make it, so it must come from the diet: ask which sources the patient eats and how much (Box 53.3) — <b>dairy</b> (cheese, milk, yogurt), <b>eggs</b>, <b>iodized table salt</b>, <b>saltwater fish</b> (salmon, sardines, tuna), <b>seaweed</b> (kelp, nori), <b>shellfish</b> (scallops, shrimp) and <b>iodine-containing multivitamins</b>.","bullets":["<b>Thirst</b> → AVP deficiency/resistance · <b>salt craving</b> → adrenal hypofunction","Lasting <b>hunger + thirst</b> → diabetes · <b>weight change without diet change</b> → thyroid/hypothalamus","<b>Iodine</b> — body can't make it; ask which + how much (Box 53.3)","<b>Dairy</b> (cheese, milk, yogurt), <b>eggs</b>, <b>iodized salt</b>, <b>saltwater fish</b> (salmon, sardines, tuna), <b>seaweed</b> (kelp, nori), <b>shellfish</b> (scallops, shrimp), iodine multivitamins"],"why":""}]},{"k":"ac","gist":"Every endocrine problem is <b>too much hormone, too little, or a poor response</b>. Most hormones run in <b>negative-feedback loops</b>, so a level means something only next to the hormone that drives it — and many are released in <b>pulses</b>, so timing and collection decide whether the number is true.","terms":[{"t":"Provocative and suppression tests","see":"A measured dose of a stimulating or suppressing substance, then hormone levels.","why":"<b>Provocative</b>: if the gland is underactive, a stimulating hormone <b>fails to raise</b> its output. <b>Suppression</b>: if the gland is overactive, a suppressing substance <b>fails to lower</b> it.","means":"The test drug must be given <b>exactly on time</b> — set an alarm if it is due overnight."},{"t":"Why a 24-hour urine","see":"All urine collected for exactly 24 hours.","why":"Many hormones are released in <b>pulses</b>, so one sample can catch a peak or a trough. A full day’s output shows the gland’s real activity.","means":"<b>One discarded void ruins the test.</b>"}],"cards":[{"t":"Provocative and suppression tests","tag":"","topic":"53-diagnostic-tests-and-the-nurse-s-job","text":"used when a level alone can't separate normal from abnormal. <b>Provocative (stimulation)</b>: for a suspected <b>underactive</b> gland, give a measured stimulating hormone — <b>failure to rise = hypofunction</b>. <b>Suppression</b>: for <b>high or high-normal</b> levels, give a substance that normally suppresses the gland — <b>failure to fall = hyperfunction</b>.","bullets":["Used when one level can't decide","<b>Stimulation</b> for suspected <b>underactivity</b> → <b>no rise = hypofunction</b>","<b>Suppression</b> for high levels → <b>no fall = hyperfunction</b>"],"why":"Most endocrine test errors are made at the bedside, not in the lab: the first morning void kept instead of discarded, a dose of the test drug taken late, a sample drawn from the wrong lumen, a catecholamine tube left at room temperature. Each one changes the number the diagnosis rests on — so the teaching is the intervention."},{"t":"Which fluid","tag":"","topic":"53-diagnostic-tests-and-the-nurse-s-job","text":"blood, urine and <b>saliva</b>. Salivary levels of <b>steroid hormones</b> (cortisol, testosterone, progesterone, estradiol) mirror blood levels; <b>protein hormones</b> (pituitary, thyroid) are <b>not</b> measured in saliva. Check the agency lab for tube type, timing and handling.","bullets":["Blood, urine, <b>saliva</b>","Saliva works for <b>steroids</b> (cortisol, testosterone, progesterone, estradiol), <b>not protein hormones</b> (pituitary, thyroid)","Check the lab for tube, timing, handling"],"why":""}]},{"k":"ph","gist":"<b>Accurate results</b> depend on the specimen and timing; <b>safety</b> (no thyroid palpation in possible hyperthyroidism, orthostatic falls); and the client’s <b>self-image and coping</b> with changes in appearance, mood and sexuality.","terms":[],"cards":[{"t":"Action alert","tag":"","topic":"53-endocrine-assessment-history-and-physica","text":"<b>do not palpate or press on the thyroid</b> of a patient who has or may have <b>hyperthyroidism</b> — it can release a burst of hormone and trigger <b>thyroid storm</b>.","bullets":["<b>Never palpate/press</b> a (possibly) <b>hyperthyroid</b> gland → hormone burst → <b>thyroid storm</b>"],"why":""},{"t":"Psychosocial","tag":"","topic":"53-endocrine-assessment-history-and-physica","text":"endocrine problems can change <b>behavior, personality, mood and self-image</b>: ask about handling stress, crying, patience and anger, and, with permission, ask family — patients often miss these changes. Changes in appearance, <b>infertility or impotence</b> affect sexuality and self-image; invite feelings. Many need <b>lifelong drugs and follow-up</b>: assess readiness to learn, self-management ability and <b>resources</b>, and refer.","bullets":["Mood, personality, behavior, <b>self-image</b> change → ask; ask family (with permission)","Appearance, <b>infertility, impotence</b> → invite feelings","Lifelong drugs → readiness to learn, ability, <b>resources</b>, referrals"],"why":""}]},{"k":"gs","gist":"Collect every specimen <b>exactly right</b>, give test drugs <b>on time</b>, and teach the client and staff their part so the result reflects the gland, not the bedside.","terms":[],"cards":[{"t":"Blood draws done right (Box 53.5)","tag":"","topic":"53-diagnostic-tests-and-the-nurse-s-job","text":"check tube type, timing and test drugs; some samples need special handling — <b>catecholamines go on ice to the lab immediately</b>. Explain restrictions. From an IV line, <b>clear it thoroughly</b> and <b>never sample from a double- or triple-lumen line</b> (contamination or dilution). Stress taking a <b>test drug on time</b> — set an alarm if it is due overnight.","bullets":["Check tube, timing, test drugs · <b>catecholamines on ice, to lab now</b>","IV line: <b>flush/clear first</b>; <b>never from a double/triple lumen</b>","Test drug <b>on time</b> (alarm at night)"],"why":""}]},{"k":"ta","gist":"24-hour urine: <b>preservative in the container first</b>; <b>empty the bladder and discard that urine</b> — the clock starts then; save <b>all</b> urine for exactly 24 hours; <b>empty the bladder at the end</b> and add it; keep it cold if required, away from food. Blood: right tube and timing, <b>catecholamines on ice to the lab at once</b>, never draw from a double- or triple-lumen line.","terms":[],"cards":[{"t":"24-hour urine (Box 53.5)","tag":"","topic":"53-diagnostic-tests-and-the-nurse-s-job","text":"many hormones are released in pulses, so a <b>24-hour collection</b> reflects gland function (e.g., adrenal) better than one sample. Check the lab's handling rules first; any <b>preservative must be in the container when the collection begins</b>. <b>Start by emptying the bladder and discarding that urine</b> — timing starts then; note the time. Collect <b>all</b> urine for <b>exactly</b> 24 hours, then <b>empty the bladder at the end even without the urge</b> and add it. Keep any <b>preservative</b> in the container and avoid splashing (some are caustic); keep it cold if required in a cooler with ice, <b>not with food or drinks</b>. Shorter timed collections (<b>2, 4, 8 or 12 hours</b>) follow the same start and end rules. Check with the provider before any new drug — some interfere. That includes <b>over-the-counter</b> drugs.","bullets":["Better than one sample for <b>pulsed</b> hormones (adrenal)","Check lab rules · <b>preservative in the container from the start</b>","<b>Start: void and discard</b>, note the time","Collect <b>all</b> urine for <b>exactly 24 h</b>; <b>end: void even without urge</b> and add it","Keep the <b>preservative</b> (caustic — don't splash); cold if needed, <b>not with food</b>","2-, 4-, 8-, 12-h collections: same start + end rules","No new drugs, <b>OTC included</b>, without asking (interference)"],"why":""},{"t":"Palpating the thyroid","tag":"","topic":"53-endocrine-assessment-history-and-physica","text":"from <b>behind</b>, patient sitting straight with the head bent slightly forward; thumbs on the back of the neck, fingers curved to the front on either side of the trachea; feel the gland <b>rise on swallowing</b>. For the right lobe, turn the head to the right, displace the trachea gently with the left fingers and palpate with the right hand; reverse for the left. Note size, shape, symmetry, nodules, tenderness.","bullets":["From <b>behind</b>, head slightly forward, fingers beside the trachea","Feel it <b>rise when they swallow</b>","Right lobe: head right, left fingers move trachea, right hand palpates (reverse for left)","Size, shape, symmetry, <b>nodules</b>, tenderness"],"why":""}]},{"k":"eo","gist":"A <b>complete, valid</b> specimen and on-time test doses; the client explains the procedure in their own words (<b>teach-back</b>).","terms":[],"cards":[]}]},{"id":"hypothyroid","ch":"55","sys":"Hormones & glucose","name":"Hypothyroidism and myxedema coma","patient":"A 72-year-old says she has been tired and cold for months, is constipated and has gained weight without eating more.","topics":["55-hypothyroidism-the-cellular-regulation-e","55-myxedema-coma"],"report":["The client with hypothyroidism is increasingly lethargic and difficult to arouse; RR 10 and shallow, temperature 94.8°F (34.9°C), HR 48, BP 88/50.","Hypothyroidism on levothyroxine; family reports missed doses this week. Received an opioid for pain 3 hours ago.","Hypoventilation, hypothermia, bradycardia and hypotension with decreasing LOC — I am concerned about myxedema coma.","Please evaluate now. I have positioned the airway and applied oxygen per protocol; requesting a glucose and sodium level and orders for IV thyroid hormone."],"guide":[{"key":"55:0","name":"Hypothyroidism & myxedema coma"}],"nodes":[{"id":"hypothyroid","name":"Hypothyroidism & myxedema coma"},{"id":"thyroid","name":"Thyroid hormone & metabolic rate"}],"drugs":[{"id":"levothyroxine","name":"Levothyroxine"}],"videos":[{"id":"EIFmHupBNi0","title":"Hypothyroidism & myxedema coma (Level Up RN)","see":"Primary vs secondary causes, the slowed-down signs and labs, and the emergency of myxedema coma"}],"steps":[{"k":"rc","gist":"Signs of a <b>hypometabolic state</b> that develop <b>gradually</b>: cold intolerance, fatigue, constipation, weight gain, <b>bradycardia</b>, <b>hypoventilation</b>, and <b>myxedema</b> (periorbital edema, macroglossia, hoarseness, nonpitting edema). Compare with the client’s <b>baseline a year ago</b>.","terms":[{"t":"Cold intolerance and hypothermia","see":"Wears a sweater in warm weather; temperature below 97°F (36.1°C).","why":"Thyroid hormone (T3) drives heat production: it increases the number of <b>Na⁺/K⁺-ATPase pumps</b> and mitochondrial activity in nearly every cell, and running them burns fuel and releases heat. With too little T3, cells burn less fuel, so the body makes less heat (<b>decreased thermogenesis</b>).","means":"A direct reading of the metabolic rate. A temperature that keeps falling — especially with a falling level of consciousness — points toward <b>myxedema coma</b>."},{"t":"Fatigue, lethargy and somnolence","see":"Sleeps more, tires with ordinary activity, slow to respond.","why":"Lower T3 means <b>less cellular energy turnover</b> in muscle and brain, and slower nerve and muscle function.","means":"Gradual, so ask about activity <b>compared with a year ago</b>. Increasing somnolence is a red flag for myxedema coma."},{"t":"Bradycardia (HR &lt; 60) and decreased cardiac output","see":"Slow pulse, low activity tolerance, dyspnea on exertion.","why":"T3 normally raises heart rate and contractility (in part by increasing <b>beta-adrenergic receptors</b> in the heart). Without it the heart beats slower and weaker, and the myocardium becomes <b>flabby</b> with enlarged chambers, so <b>cardiac output falls</b>.","means":"This is why <b>decreased perfusion</b> is a priority problem — and why replacement starts low: suddenly raising metabolic demand on this heart can cause <b>angina, dysrhythmias or MI</b>."},{"t":"Hypoventilation","see":"Slow, shallow respirations; SpO₂ may drop.","why":"Low thyroid hormone <b>blunts the brain’s drive to breathe</b> in response to low oxygen and high CO₂, and weakens the respiratory muscles, so CO₂ builds up.","means":"The <b>top priority</b> (impaired gas exchange). <b>Sedatives and opioids</b> depress breathing further — avoid them or expect a reduced dose, and monitor RR and SpO₂."},{"t":"Myxedema: periorbital edema and nonpitting edema","see":"Puffy face and eyelids; firm swelling of the hands, feet and shins that does not keep a dent.","why":"<b>Glycosaminoglycans</b> (water-attracting protein–sugar molecules such as hyaluronic acid) build up in the skin and tissues and <b>hold water in a gel</b>. The water is bound in that matrix rather than loose in the tissue spaces, so pressing does not push it away — the edema is <b>nonpitting</b>.","means":"Distinguishes myxedema from heart-failure or kidney edema, which <b>pits</b>. It also explains the thick tongue and the hoarse voice."},{"t":"Macroglossia and hoarseness","see":"Enlarged, thick tongue; slow or slurred speech; deep, hoarse voice.","why":"The same <b>glycosaminoglycan deposits</b> enlarge the tongue and thicken the <b>vocal cords</b>.","means":"An <b>airway</b> consideration — a large tongue can obstruct the airway in a sedated or obtunded client. Slurred speech here is from the tongue, not necessarily a stroke, but assess neurologic status."},{"t":"Constipation","see":"Fewer, harder stools.","why":"Low T3 slows <b>GI smooth-muscle activity</b> (decreased peristalsis, or <b>hypomotility</b>).","means":"Also a dosing clue on treatment: constipation and more sleep suggest <b>underreplacement</b>."},{"t":"Weight gain without overeating","see":"Weight up compared with a year ago despite a normal or lower appetite.","why":"A lower <b>basal metabolic rate</b> burns fewer calories at rest, and myxedema adds retained water.","means":"Weigh and compare with the past year; weight should stabilize on replacement."},{"t":"Dry, coarse, cool, pale skin and hair loss","see":"Dry scaly skin, brittle hair, loss of the outer eyebrows, poor wound healing.","why":"Less <b>sweat and sebaceous secretion</b>; <b>skin vessels constrict</b> to conserve heat (cool, pale); slower cell turnover and protein synthesis slow hair growth and <b>wound healing</b>.","means":"Protect skin integrity; expect slower healing after injury or surgery."},{"t":"Decreased deep tendon reflexes","see":"Sluggish reflexes, with a slow relaxation phase.","why":"Muscle fibers <b>contract and relax more slowly</b> when their metabolic rate is low.","means":"A classic physical-exam sign of hypothyroidism."},{"t":"Cognitive slowing, apathy and depression","see":"Slow answers, poor memory and attention, withdrawn; the family often notices first.","why":"Thyroid hormone supports <b>brain metabolism and neurotransmission</b>; when it is low, thinking and mood slow.","means":"Can look like dementia or depression in older adults. A <b>worsening mental status</b> is the earliest warning of myxedema coma — assess it at least every 8 hours."},{"t":"Myxedema coma: hyponatremia, hypoglycemia, hypotension","see":"Falling LOC with low sodium, low glucose and low BP.","why":"Severe hormone deficiency impairs the kidneys’ ability to excrete free water (<b>dilutional hyponatremia</b>), slows <b>glucose production</b> by the liver, and lowers cardiac output (<b>hypotension</b>).","means":"Each one is treated in the emergency box: saline, IV glucose, IV thyroid hormone, airway. <b>Do not wait for labs</b> to act."}],"cards":[{"t":"Ask","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"activity now <b>compared with a year ago</b> (changes are slow and easily missed, especially in older adults); more <b>sleep</b>; <b>fatigue</b>, weakness, muscle aches, <b>paresthesias</b>; <b>constipation</b>; <b>cold intolerance</b> (extra blankets or a sweater in warm weather); low libido, heavy prolonged periods or amenorrhea, trouble conceiving (anovulation), impotence and infertility in men; <b>lithium or amiodarone</b>; past hyperthyroid treatment and which one; <b>COVID-19</b> (can aggravate autoimmune thyroid disease).","bullets":["Activity vs <b>a year ago</b> (slow change, often missed in older adults), ↑ sleep, <b>fatigue</b>, aches, <b>paresthesias</b>","<b>Constipation</b>, <b>cold intolerance</b> (sweater in warm weather)","Libido, heavy periods/amenorrhea, anovulation, impotence + infertility (men)","<b>Lithium, amiodarone</b>, past hyperthyroid treatment (which one), <b>COVID-19</b>"],"why":"Every finding is the same idea — <b>not enough fuel burning</b>: less heat (cold intolerance, low temperature), less drive (slow pulse, slow breathing, slow gut, slow thinking), and tissues that collect water-holding compounds (puffy face, thick tongue). The danger is in the breathing: slow, shallow respiration plus any sedative can tip into respiratory failure."},{"t":"See","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"<b>coarse dry scaly skin</b> (cool, pale or ash gray) with <b>poor wound healing</b>; dry, coarse, brittle hair that grows less, <b>loss of eyebrow hair</b>, thick brittle nails; <b>puffy face and periorbital edema</b>, <b>thick tongue</b>, <b>hoarseness</b>, <b>nonpitting edema of the hands and feet</b>; slow movement, <b>slow or slurred speech</b> (the thick tongue) and slow answers; <b>weight gain</b> without overeating (weigh and compare with a year ago); possibly a <b>goiter</b>.","bullets":["<b>Coarse dry cool skin</b>, <b>poor wound healing</b>; dry coarse brittle hair, <b>lost eyebrows</b>, thick nails","<b>Puffy face + eyes</b>, <b>thick tongue</b>, <b>hoarse</b>, <b>nonpitting edema of hands + feet</b>","Slow movement, <b>slow or slurred speech</b>, slow answers","<b>Weight gain</b> without overeating (weigh, compare with a year ago) · maybe <b>goiter</b>"],"why":""},{"t":"Measure","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"pulse <b>below 60</b>, slow respirations (<b>hypoventilation</b>), temperature <b>below 97°F (36.1°C)</b>, <b>diastolic hypertension</b>, decreased tendon reflexes, <b>hearing loss</b>, decreased activity tolerance, dyspnea, pericardial or pleural effusion, abdominal distention or ascites.","bullets":["HR <b>&lt; 60</b>, slow RR (<b>hypoventilation</b>), temp <b>&lt; 97°F (36.1°C)</b>","<b>Diastolic hypertension</b>, ↓ reflexes, <b>hearing loss</b>, ↓ activity tolerance, dyspnea, effusions, distention/ascites"],"why":""},{"t":"Mind and mood","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"<b>apathy and depression</b> — sometimes the family brings the patient in; lethargy may keep them from noticing they have changed. <b>Confusion</b>, lethargy or somnolence, inattentiveness; impaired <b>attention and memory</b> and slowed thinking — families describe the patient as <b>withdrawn</b> → <b>social isolation</b>.","bullets":["<b>Apathy, depression</b> (family often notices first)","<b>Confusion</b>, somnolence, inattentive; ↓ attention + memory, slow thinking","Withdrawn → <b>isolation</b>"],"why":""},{"t":"Myxedema coma — what you see","tag":"If it worsens","topic":"55-myxedema-coma","text":"greatly <b>reduced consciousness and cognition</b>, <b>respiratory failure</b>, <b>hypotension</b>, <b>hyponatremia</b>, <b>hypothermia</b>, <b>hypoglycemia</b>, <b>bradycardia</b>.","bullets":["↓ <b>LOC + cognition</b>, <b>respiratory failure</b>","<b>Hypotension, hyponatremia, hypothermia, hypoglycemia, bradycardia</b> (everything low)"],"why":"Read the list of findings as \"everything that depends on metabolism has failed\": no heat (hypothermia), no drive to breathe (respiratory failure), no pump (bradycardia, hypotension), no fuel (hypoglycemia), and dilutional low sodium. Each line of the emergency box answers one of them — and warming is with <b>blankets</b>, not aggressive active rewarming, while the hormone is replaced <b>IV</b> because the slowed gut will not absorb a pill."}]},{"k":"ac","gist":"Deficient T3/T4 lowers the <b>basal metabolic rate</b> in every tissue. <b>Elevated TSH with low free T4</b> = <b>primary hypothyroidism</b>: the gland fails and the pituitary keeps signaling — most often <b>Hashimoto thyroiditis</b>.","terms":[{"t":"TSH elevated, free T4 low","see":"TSH above 5 μU/mL with low T3/T4.","why":"<b>Negative feedback</b>: the pituitary releases TSH until it senses enough thyroid hormone. When the gland cannot respond, hormone stays low and the pituitary keeps raising TSH.","means":"<b>Primary hypothyroidism</b> (the problem is in the thyroid). TSH low or normal with low T4 points to a <b>secondary</b> (pituitary or hypothalamic) cause. On treatment, TSH guides the dose."},{"t":"Goiter","see":"Enlarged thyroid at the front of the neck.","why":"Persistently high <b>TSH stimulates thyroid cells to grow</b> even though they cannot make more hormone (for example, with iodine deficiency or Hashimoto).","means":"A goiter says “thyroid problem,” <b>not which direction</b> — Graves disease also causes one."},{"t":"Hashimoto thyroiditis","see":"The most common cause in the US.","why":"An <b>autoimmune</b> attack destroys thyroid tissue, so the gland gradually loses the ability to make hormone.","means":"Permanent → <b>lifelong replacement</b>. Other causes to ask about: thyroid surgery, radioactive iodine, <b>amiodarone, lithium</b>."}],"cards":[{"t":"Definition","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"reduced or absent thyroid hormone secretion → <b>whole-body slowing of metabolism</b>. Early on it is easily missed: onset is <b>gradual</b> and symptoms mimic many other diseases.","bullets":["↓ or absent thyroid hormone → <b>everything slows</b>","<b>Gradual onset</b>, mimics other diseases → easily missed"],"why":""},{"t":"Causes (Box 55.1)","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"most US cases are <b>Hashimoto thyroiditis</b>, an autoimmune attack on thyroid tissue. Also common in North America: <b>thyroid surgery</b> and <b>radioactive iodine</b> treatment of hyperthyroidism. Worldwide: <b>iodine-poor soil and water</b> (endemic goiter) — the gland needs dietary <b>iodine and tyrosine</b> to make hormone. Drugs: <b>amiodarone, lithium</b>. Cancer (thyroid or metastatic), congenital problems. All of these are <b>primary</b> (the gland itself fails). <b>Secondary</b>: not enough TSH from congenital pituitary defects or pituitary or hypothalamic tumors, trauma, infection or infarction.","bullets":["US: <b>Hashimoto</b> (autoimmune) most common","Also: <b>thyroid surgery</b>, <b>radioactive iodine</b>","Worldwide: <b>iodine deficiency</b> (endemic goiter); hormone needs <b>iodine + tyrosine</b>","Drugs: <b>amiodarone, lithium</b> · cancer (thyroid or metastatic) · congenital → all <b>primary</b> (gland fails)","<b>Secondary</b>: pituitary/hypothalamus can't make TSH (congenital defects, tumors, trauma, infection, infarction)"],"why":""},{"t":"Labs (Table 55.1)","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"<b>T3 and T4 low</b>. <b>TSH high in primary</b> hypothyroidism (the gland fails, the pituitary shouts), <b>low or near normal in secondary</b> (the pituitary or hypothalamus fails). Older adults tend to run higher TSH.","bullets":["<b>T3 + T4 low</b>","<b>TSH high = primary</b> (gland fails) · <b>TSH low/normal = secondary</b> (pituitary/hypothalamus)"],"why":""},{"t":"Who","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"<b>4–10% of adults</b>; women <b>5 to 8 times</b> more often than men. A congenital form is genetic, and thyroid dysfunction is linked to Down syndrome, Turner syndrome and atrial fibrillation. There is <b>no known prevention</b> — catch it early.","bullets":["<b>4–10%</b> of adults; <b>women 5–8×</b> more","No known prevention → <b>watch for symptoms early</b>"],"why":""},{"t":"Older adults","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"secretion falls with age but so does clearance, so <b>don't rely on labs alone</b> — use <b>changes in symptoms</b> to judge replacement (symptoms are often milder at this age). Muscle loss is normal aging, so don't use strength as a sign. Age-related heart and nerve changes make them <b>more sensitive to replacement</b> — <b>start low, increase slowly</b> to avoid cardiac and neurologic toxicity, and assess for <b>chest pain, shortness of breath</b> and mental status changes (<b>confusion</b>, changes in sleep). Amiodarone can change thyroid levels.","bullets":["Labs less reliable (↓ secretion + ↓ clearance) → judge replacement by <b>symptom changes</b>; milder symptoms","Don't use muscle strength as a sign","<b>More sensitive to replacement</b> (heart + nerves) → <b>start low, go slow</b>","Assess <b>chest pain, dyspnea, confusion, sleep changes</b> · amiodarone alters levels"],"why":""}]},{"k":"ph","gist":"1. <b>Impaired gas exchange</b> from hypoventilation. 2. <b>Decreased cardiac output</b> and perfusion. 3. Risk for <b>myxedema coma</b>, which is fatal mostly through <b>respiratory failure</b>.","terms":[],"cards":[{"t":"Priority problems","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"1. <b>Decreased gas exchange</b> from low energy, muscle weakness and fatigue. 2. <b>Reduced perfusion</b> from low cardiac output. 3. Potential for <b>myxedema coma</b>. Respiratory failure is the most common cause of death in myxedema coma.","bullets":["1. <b>↓ Gas exchange</b> · 2. <b>↓ Perfusion</b> (low CO) · 3. <b>Myxedema coma</b> risk","Myxedema coma deaths: mostly <b>respiratory failure</b>"],"why":"Replacement has to be slow because the heart has adapted to a low metabolic demand. Thyroid hormone raises <b>oxygen demand</b> in every tissue, including the myocardium — give a full dose to a 70-year-old with coronary disease and you have created the conditions for angina, dysrhythmia and infarction. That is also why the empty-stomach rule matters: absorption varies with food and minerals, and a dose that is absorbed unevenly cannot be titrated."},{"t":"Myxedema coma — what it is","tag":"","topic":"55-myxedema-coma","text":"a rare but life-threatening complication of <b>untreated or poorly treated hypothyroidism</b>: dangerously reduced <b>cardiopulmonary and neurologic function</b> (few patients are actually comatose). Mortality is extremely high — early recognition is everything. Low cardiac output starves the brain and other organs of blood and oxygen; <b>respiratory failure</b> is the most common cause of death.","bullets":["Untreated/poorly treated hypothyroidism → <b>heart, lungs, brain fail</b>","Few are truly comatose; <b>mortality very high</b> → recognize early","Low cardiac output → organ failure; <b>respiratory failure</b> = most common cause of death"],"why":""},{"t":"Myxedema coma — triggers","tag":"","topic":"55-myxedema-coma","text":"any hypothyroid patient who is <b>newly diagnosed</b> or has other health problems is at risk. Triggers: <b>acute illness, surgery, chemotherapy, stopping thyroid replacement, sedatives or opioids</b>.","bullets":["At risk: <b>newly diagnosed</b> or other illness","Triggers: <b>acute illness, surgery, chemo, stopping replacement, sedatives/opioids</b>"],"why":""}]},{"k":"gs","gist":"Maintain <b>ventilation and perfusion</b>; start <b>levothyroxine at a low dose and titrate slowly</b> by TSH and symptoms; teach <b>lifelong</b> replacement with self-monitoring.","terms":[],"cards":[{"t":"Levothyroxine — how to give it","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"lifelong synthetic thyroid hormone. Start at a set dose and raise gradually over weeks; the <b>lowest starting dose</b> for severe symptoms, older adults, coronary disease or unknown severity — too much or too fast causes <b>dysrhythmias, heart failure and MI</b>. Final dose is set by <b>TSH</b> and how the patient feels. <b>IV</b> in myxedema coma (the gut absorbs poorly).","bullets":["<b>Lifelong</b>; raise gradually over weeks","<b>Lowest start</b>: severe symptoms, older adults, <b>coronary disease</b>","Too much/too fast → <b>dysrhythmias, HF, MI</b>","Dose by <b>TSH</b> + symptoms · <b>IV in myxedema coma</b>"],"why":""},{"t":"Self-monitoring and teaching","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"the two easiest checks are <b>sleep and bowels</b>: needing more sleep and <b>constipated</b> → dose may be too low; <b>trouble falling asleep and more bowel movements</b> → dose may be too high. Teach lifelong therapy, signs of hypo- and hyperthyroidism, <b>medical alert bracelet</b>, periodic blood tests, <b>no OTC drugs without asking</b>, a balanced diet with <b>fiber and fluids</b>, warmth until symptoms improve, rest. One person should be responsible for preparing doses so none are <b>missed or doubled</b>; one-floor living may help for a while. A patient on replacement who is <b>still tired and cold</b> (a sweater in warm weather) shows signs of too little hormone: take <b>vital signs and temperature</b>, <b>review the medication record</b> (dose, missed doses, how and when it is taken) and report — the provider may check the TSH and adjust the dose. Make sure whoever oversees daily care (family, facility staff) knows about the condition; arrange home health if needed.","bullets":["Check <b>sleep + bowels</b>: more sleep + <b>constipation</b> = too low; insomnia + more stools = <b>too high</b>","Lifelong · <b>medical alert</b> · blood tests · <b>no OTC without asking</b>","Fiber + fluids, warmth, rest · one person manages doses (none missed or doubled) · one-floor living","On replacement but <b>still tired + cold</b> → <b>VS + temperature</b>, <b>review med record</b> (dose, missed doses, timing) → report (TSH, dose change)","Caregivers/facility know the diagnosis · home health if needed"],"why":""}]},{"k":"ta","gist":"Monitor <b>RR, depth and SpO₂</b>; <b>avoid or reduce sedatives</b>; monitor HR, rhythm and BP; give <b>levothyroxine on an empty stomach</b> 30–60 minutes before breakfast; report <b>chest pain</b>. Myxedema coma: <b>patent airway</b>, IV saline, glucose and <b>IV thyroid hormone</b>, warm with <b>blankets</b>.","terms":[],"cards":[{"t":"Gas exchange","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"record rate and depth, <b>SpO₂</b>, oxygen for hypoxemia, listen for decreased sounds or crackles; ventilatory support if severe. <b>Avoid sedation</b>; if needed, use <b>reduced doses</b> — hypothyroidism makes patients more sensitive — and watch gas exchange closely.","bullets":["Rate, depth, <b>SpO₂</b>, O₂ if hypoxemic, crackles; ventilator if severe","<b>Avoid sedatives</b>; if needed <b>lower doses</b> (↑ sensitivity) + watch breathing"],"why":""},{"t":"Cardiac output","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"watch for a rising BP and <b>dysrhythmias</b> — monitor <b>BP, heart rate and rhythm</b> and act on changes before complications set in; chronic disease may bring cardiovascular disease. Teach to report <b>chest pain or discomfort immediately</b>.","bullets":["BP may rise, <b>dysrhythmias</b> → monitor <b>BP, HR, rhythm</b>","Chronic → cardiovascular disease · report <b>chest pain</b> at once"],"why":""},{"t":"Levothyroxine — drug alert","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"take it exactly as prescribed, never change the dose alone. <b>With water, on an empty stomach, 30–60 minutes before breakfast.</b> Keep <b>iron, calcium and antacids at least 4 hours apart</b>; fiber supplements can also block absorption. Watch for <b>chest pain and dyspnea</b> when starting, and teach the signs of <b>too much</b> — <b>fast or pounding heartbeat, chest pain, nervousness or tremor, trouble sleeping, feeling hot and sweaty, weight loss, more frequent stools</b>.","bullets":["<b>Water, empty stomach, 30–60 min before breakfast</b>","<b>Iron, calcium, antacids ≥ 4 h apart</b>; fiber supplements interfere","Watch <b>chest pain, dyspnea</b> at start; teach signs of <b>too much</b>: fast heartbeat, chest pain, tremor, <b>insomnia</b>, heat intolerance, weight loss, <b>more stools</b>"],"why":""},{"t":"Myxedema coma — action alert","tag":"If it worsens","topic":"55-myxedema-coma","text":"it can progress to <b>shock, organ damage and death</b>, so assess every hypothyroid patient at least <b>every 8 hours</b>, especially <b>mental status</b>, and report changes promptly. Treatment starts on the symptoms — <b>do not wait for lab confirmation</b>.","bullets":["Can → <b>shock, organ damage, death</b>","Assess hypothyroid patients <b>at least every 8 h</b> (mental status!)","Treat on symptoms — <b>don't wait for labs</b>"],"why":""},{"t":"Myxedema coma — emergency care","tag":"If it worsens","topic":"55-myxedema-coma","text":"keep a <b>patent airway</b>; IV <b>normal or hypertonic saline</b>; <b>IV T3 and/or T4</b>; <b>IV glucose</b>; <b>corticosteroids</b>; temperature and <b>BP hourly</b>; <b>warm blankets</b>; watch mental status; <b>turn every 2 hours</b>; <b>aspiration precautions</b>.","bullets":["<b>Airway</b> first","IV <b>normal/hypertonic saline</b>, <b>IV T3/T4</b>, <b>IV glucose</b>, <b>steroids</b>","Temp + <b>BP hourly</b>, <b>warm blankets</b>, mental status","<b>Turn q2h</b>, <b>aspiration precautions</b>"],"why":""},{"t":"Myxedema coma — IV hormone and drug cautions","tag":"If it worsens","topic":"55-myxedema-coma","text":"thyroid hormone goes <b>IV</b> because the slowed gut absorbs pills poorly, but it carries the same risk as any start of replacement: too much too fast → <b>dysrhythmias, heart failure or MI</b> — watch rhythm, BP, chest pain and dyspnea, especially in <b>older or cardiac</b> patients. <b>Sedatives and opioids</b> both trigger and deepen the coma: avoid them; if one is essential, expect a <b>reduced dose</b> and monitor breathing and SpO₂.","bullets":["<b>IV</b> T3/T4 (gut won't absorb) — same cardiac risk as any start: <b>dysrhythmias, HF, MI</b>","Watch rhythm, BP, chest pain, dyspnea — esp. <b>older/cardiac</b>","<b>Avoid sedatives/opioids</b>; if essential → <b>reduced dose</b> + watch breathing, SpO₂"],"why":""}]},{"k":"eo","gist":"<b>HR above 60</b>, <b>SpO₂ above 93%</b>, improving cognition. Dose check: more sleep and constipation suggest <b>underreplacement</b>; insomnia, palpitations and more frequent stools suggest <b>overreplacement</b>.","terms":[],"cards":[{"t":"Evaluate","tag":"","topic":"55-hypothyroidism-the-cellular-regulation-e","text":"pulse <b>above 60</b> and BP normal for the patient; <b>SpO₂ above 93%</b>; improving cognition.","bullets":["Pulse <b>&gt; 60</b>, BP normal · <b>SpO₂ &gt; 93%</b> · cognition improving"],"why":""}]}]},{"id":"hyperthyroid","ch":"55","sys":"Hormones & glucose","name":"Hyperthyroidism and Graves disease","patient":"A 34-year-old has lost 15 lb in two months despite eating more, feels hot and shaky, can’t sleep, and her eyes look like they are bulging.","topics":["55-hyperthyroidism-and-graves-disease","55-treating-hyperthyroidism-drugs-radioacti"],"report":["The client has a resting HR of 118, BP 152/58, a 15-lb weight loss over 2 months with increased appetite, tremor, heat intolerance and exophthalmos.","No thyroid history; her mother has Graves disease.","Findings consistent with hyperthyroidism, likely Graves disease, with tachycardia and a wide pulse pressure.","Requesting TSH, free T4 and TRAb, an ECG, and an order for a beta blocker for symptom control."],"guide":[{"key":"55:1","name":"Hyperthyroidism, thyroidectomy & thyroid storm"}],"nodes":[{"id":"hyperthyroid","name":"Hyperthyroidism, thyroidectomy & storm"},{"id":"thyroid","name":"Thyroid hormone & metabolic rate"}],"drugs":[{"id":"methimazole","name":"Methimazole"},{"id":"ptu","name":"Propylthiouracil (PTU)"},{"id":"sski","name":"Potassium iodide (SSKI)"},{"id":"rai131","name":"Radioactive iodine (¹³¹I)"},{"id":"propranolol","name":"Propranolol (in hyperthyroidism)"}],"videos":[{"id":"5UTXFU86wK4","title":"Hypothyroidism vs hyperthyroidism (RegisteredNurseRN)","see":"The two side by side — causes, signs, labs and treatment — the way the NCLEX compares them"},{"id":"QBeq0Kf03lI","title":"What is Graves’ disease? (UCLA Health)","see":"An antibody switching the thyroid on, and the three treatments: drugs, radioactive iodine or surgery"}],"steps":[{"k":"rc","gist":"Signs of a <b>hypermetabolic state with sympathetic overactivity</b>: <b>heat intolerance</b> and diaphoresis, <b>weight loss despite increased appetite</b>, <b>tachycardia</b>, palpitations, <b>wide pulse pressure</b>, atrial fibrillation, <b>tremor</b>, hyperreflexia, insomnia, anxiety, more frequent stools — plus <b>exophthalmos</b> and a <b>goiter</b> in Graves disease.","terms":[{"t":"Heat intolerance and diaphoresis","see":"Feels hot in a cool room, sweats, wears light clothes in cold weather — often the <b>first</b> symptom.","why":"Excess thyroid hormone drives every cell to <b>burn more fuel</b>, which produces more heat. The body sheds it by sweating and dilating skin vessels.","means":"Keep the room <b>cool</b>, change damp linens. A <b>rising temperature</b> may be the start of <b>thyroid storm</b> — report a rise of even 1°F."},{"t":"Weight loss with increased appetite","see":"Eating more but losing weight; muscle wasting.","why":"Calories are burned faster than they are eaten, and <b>protein breakdown exceeds protein building</b>. Glucose tolerance also falls.","means":"<b>Imbalanced nutrition</b> is a priority problem: weigh regularly and meet the increased calorie needs."},{"t":"Tachycardia, palpitations and atrial fibrillation","see":"Resting pulse over 100, irregular rhythm, chest pain or dyspnea.","why":"Thyroid hormone increases the heart’s <b>beta-adrenergic receptors</b> and its sensitivity to catecholamines, speeding the rate and raising contractility. It also shortens the atrial refractory period, which favors <b>atrial fibrillation</b>.","means":"Check the <b>apical</b> pulse and BP at least every 4 hours. <b>Beta blockers</b> (propranolol) control these effects while the antithyroid drug takes weeks to work."},{"t":"Wide pulse pressure","see":"Systolic up, diastolic down — e.g., 152/58.","why":"A stronger, faster heart pumps more blood with each beat (<b>higher systolic</b>), while skin vessels dilate to release heat (<b>lower diastolic</b>).","means":"Reflects a <b>high cardiac output</b> state — the heart is working hard, with risk of heart failure in older adults."},{"t":"Tremor, hyperreflexia, anxiety and insomnia","see":"Fine tremor of the hands, brisk reflexes, restless, irritable, emotional swings, can’t sleep.","why":"Excess hormone makes nerves and muscles <b>more excitable</b> and amplifies the <b>sympathetic</b> response.","means":"A <b>quiet, low-stimulation room</b> and rest; explain the mood changes to the family. Muscle weakness can also develop."},{"t":"More frequent stools","see":"Frequent, loose stools.","why":"Increased <b>GI motility</b>.","means":"Adds to weight loss and dehydration risk."},{"t":"Exophthalmos (Graves only)","see":"Bulging eyes, a stare, tearing, redness, photophobia; lids may not close.","why":"The Graves antibodies also inflame the tissues behind the eye: the <b>eye muscles and fat swell</b> and push the eyeball forward.","means":"Risk of <b>dry eyes and corneal ulcers</b> and, with pressure on the optic nerve, <b>vision loss</b>. Often does <b>not</b> fully improve when the hormone level is treated."},{"t":"Lid lag and globe lag","see":"The upper lid lags behind the eye when looking down; it pulls back faster than the eye when looking up.","why":"<b>Sympathetic overactivity</b> keeps the eyelid muscle retracted.","means":"Seen in <b>any</b> cause of hyperthyroidism, not only Graves."},{"t":"Goiter with a bruit","see":"Enlarged thyroid, sometimes 4 times normal size; a whooshing sound over it.","why":"Thyroid-stimulating antibodies make the gland <b>grow</b>; the extra blood flow through it causes the <b>bruit</b>.","means":"<b>Look, don’t touch</b>: palpating the gland can release a flood of hormone and trigger <b>thyroid storm</b>."}],"cards":[{"t":"History","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"weight and usual weight; <b>unplanned weight loss</b> with <b>increased appetite</b> and <b>more bowel movements</b>. <b>Heat intolerance is often the first symptom</b> — sweating, light clothes in cold weather. Palpitations, chest pain, dyspnea. Blurred or <b>double vision</b>, eye fatigue. Fatigue with <b>insomnia</b>; restless or anxious (family notices). Amenorrhea or lighter periods and lower fertility; decreased libido in women and men. Changes can be so gradual that the patient hasn't noticed them. Past <b>thyroid surgery or neck radiation</b> (some stay hyperthyroid after surgery or resist radiation), thyroid hormone or antithyroid drugs.","bullets":["<b>Weight loss + ↑ appetite + ↑ stools</b>","<b>Heat intolerance often first</b>; sweating","Palpitations, chest pain, dyspnea · blurred/double vision","Fatigue + <b>insomnia</b>, restless, anxious · lighter periods, ↓ fertility, ↓ libido","Gradual → patient may not notice","Past <b>surgery/radiation</b> (may stay hyperthyroid), thyroid drugs"],"why":"The excess hormone acts like a <b>permanent sympathetic surge</b> plus a furnace turned up: the heart races, the skin sweats, the gut hurries, the muscles shake, and the patient is hungry yet losing weight. The low TSH is the pituitary obeying negative feedback — it has stopped asking for hormone — which is how you know the gland itself (or an antibody) is driving the excess."},{"t":"Eyes","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"<b>exophthalmos</b> (Graves): edema of the eye muscles and fat behind the eye push the globe forward → focusing problems, <b>optic nerve pressure</b>, and if the lids don't close, <b>dry eyes and corneal ulcers</b>; look for tearing, redness, <b>photophobia</b>. In <b>all</b> hyperthyroidism: <b>eyelid lag</b> (upper lid doesn't follow the eye down) and <b>globe lag</b> (lid pulls back faster than the eye looking up) — ask the patient to look down, then up.","bullets":["<b>Exophthalmos</b> (Graves): swollen eye muscles + fat push eye forward","Lids won't close → <b>dry eyes, corneal ulcers</b>; tearing, redness, <b>photophobia</b>","All hyperthyroid: <b>eyelid lag</b> + <b>globe lag</b> (look down, then up)"],"why":""},{"t":"Neck — look, don't touch","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"note size and symmetry; a goiter may be <b>4 times normal size</b>. The generalist nurse <b>does not palpate</b> the thyroid — in hyperthyroidism it can release a flood of hormone and trigger <b>thyroid storm</b>. A <b>bruit</b> may be heard from increased blood flow.","bullets":["Goiter up to <b>4× normal</b>","<b>Never palpate</b> → can trigger <b>thyroid storm</b>","<b>Bruit</b> from ↑ blood flow"],"why":""},{"t":"Heart, skin, muscles, mood","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"<b>tachycardia</b>, palpitations, <b>higher systolic and lower diastolic BP (wide pulse pressure)</b>, <b>atrial fibrillation</b>, rapid shallow breathing. <b>Warm, smooth, moist skin</b>, diaphoresis, <b>fine silky hair</b>, thinning scalp hair. <b>Tremor</b>, <b>hyperactive reflexes</b>, muscle weakness. Wide <b>mood swings</b>, short attention, anxiety, <b>hyperactivity</b>, restlessness and irritability; \"full speed ahead or completely stopped\" (poor sleep → fatigue); crying or laughing without cause. Men: erectile dysfunction, gynecomastia.","bullets":["<b>Tachycardia</b>, <b>wide pulse pressure</b>, <b>A-fib</b>, rapid shallow breathing","<b>Warm moist skin</b>, sweating, <b>fine silky hair</b>, thin scalp hair","<b>Tremor</b>, <b>hyperactive reflexes</b>, weakness","<b>Mood swings</b>, anxiety, <b>hyperactivity</b>, irritable, short attention","Men: ED, gynecomastia"],"why":""}]},{"k":"ac","gist":"Excess thyroid hormone <b>speeds metabolism in every organ</b> and amplifies the sympathetic response. <b>Graves disease</b> (most common): <b>thyroid-stimulating immunoglobulins</b> bind the TSH receptor and drive the gland. Labs: <b>T3/T4 and free T4 high, TSH low</b>, TRAb positive.","terms":[{"t":"TSH low with high free T4 and T3","see":"TSH below 0.3 μU/mL; free T4 above 2.8 ng/dL.","why":"<b>Negative feedback</b>: the pituitary senses too much thyroid hormone and stops releasing TSH.","means":"The gland (or an antibody) is driving the excess — <b>primary</b> hyperthyroidism. A high TSH with high T4 would point to a rare pituitary cause."},{"t":"Thyroid-stimulating immunoglobulins (TRAb)","see":"Positive antibody test.","why":"In Graves disease the immune system makes antibodies that <b>mimic TSH</b> and switch the gland on continuously.","means":"<b>Confirms Graves.</b> Autoimmune: ask about other autoimmune diseases and family history."},{"t":"Radioactive iodine uptake increased","see":"Uptake scan with a small oral dose of iodine-123.","why":"An overactive gland <b>traps more iodine</b> to make hormone.","means":"A small <b>diagnostic</b> dose of iodine-123 — not the therapeutic iodine-131 dose. Ask about <b>pregnancy and breastfeeding</b> first (iodine-123 passes into <b>breast milk</b>) and follow nuclear medicine’s instructions."}],"cards":[{"t":"Definition","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"<b>excess thyroid hormone</b> — the same name is used when the cause is too much <b>synthetic hormone</b> in someone with a normal gland. It <b>speeds metabolism in every organ</b> and increases sympathetic activity; it can be temporary or permanent.","bullets":["<b>Excess thyroid hormone</b> (incl. too much synthetic = exogenous)","<b>Everything speeds up</b> + ↑ sympathetic activity"],"why":""},{"t":"Graves disease — the most common cause","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"<b>autoimmune</b>: often after thyroid inflammation, antibodies called <b>thyroid-stimulating immunoglobulins (TSIs)</b> bind the <b>TSH receptor</b> and drive the gland — more cells, a <b>goiter</b>, and overproduction. Only Graves adds <b>exophthalmos</b> and <b>pretibial myxedema</b> (dry, waxy swelling on the front of the lower legs). Diagnosed most often in <b>women 30–50</b>; linked to other autoimmune diseases (diabetes, vitiligo, rheumatoid arthritis), often in both identical twins — ask about family. COVID-19 can aggravate it.","bullets":["<b>Autoimmune</b>: <b>TSIs</b> bind the <b>TSH receptor</b> → goiter + overproduction","Only Graves: <b>exophthalmos</b> + <b>pretibial myxedema</b>","Women <b>30–50</b>; other autoimmune disease; ask about family"],"why":""},{"t":"Other causes","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"<b>toxic multinodular goiter</b> — nodules or adenomas in a goiter present for years; milder, <b>no exophthalmos or pretibial myxedema</b>; mostly women until 50, then equal. <b>Exogenous</b> hyperthyroidism — too much replacement hormone.","bullets":["<b>Toxic multinodular goiter</b>: milder, no eye/shin signs","<b>Exogenous</b>: too much replacement"],"why":""},{"t":"Tests","tag":"","topic":"55-hyperthyroidism-and-graves-disease","text":"<b>T3, T4 and free T4 high</b>; <b>TSH low in Graves</b> (high in rare secondary or tertiary disease) — ranges in <b>Table 55.1</b> (free T4 <b>0.8–2.8 ng/dL</b>, TSH <b>0.3–5 μU/mL</b>; T3 and total T4 by age and sex in the hypothyroidism notes); <b>TRAb</b> (antibody to the TSH receptor) confirms Graves. <b>Radioactive iodine uptake</b> (a small oral diagnostic dose of ¹²³I with a short half-life — not the therapeutic ¹³¹I used to treat): ask about <b>pregnancy and breastfeeding</b> first — ¹²³I passes into <b>breast milk</b> — and follow nuclear medicine’s specific instructions (<a href=\"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=493fa2ab-4eb0-4434-9739-3079b2f0e272\">sodium iodide I-123 prescribing information</a>). Uptake is increased and shows active nodules. <b>Ultrasound</b> (30 minutes, painless) for size and nodules. <b>ECG</b>: SVT, atrial fibrillation, PVCs.","bullets":["<b>T3, T4, free T4 ↑</b>; <b>TSH ↓ in Graves</b>; <b>TRAb</b> = Graves","Normal: free T4 <b>0.8–2.8 ng/dL</b> · TSH <b>0.3–5 μU/mL</b> (Table 55.1)","<b>RAIU</b> (diagnostic ¹²³I, not therapeutic ¹³¹I): ask about <b>pregnancy + breastfeeding</b> (enters milk), follow nuclear medicine’s instructions; ↑ uptake","Ultrasound · <b>ECG</b>: SVT, A-fib, PVCs"],"why":""}]},{"k":"ph","gist":"1. <b>Decreased cardiac output</b> — tachycardia and dysrhythmias. 2. Risk for <b>thyroid storm</b>. 3. <b>Imbalanced nutrition</b> from hypermetabolism. 4. Risk for <b>eye injury</b> from exophthalmos.","terms":[],"cards":[{"t":"Monitor","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"<b>apical pulse, BP and temperature at least every 4 hours</b>; teach to report palpitations, dyspnea, vertigo or chest pain at once. A rising temperature may be <b>thyroid storm</b> starting — <b>report an increase of even 1°F (1.8°C) immediately</b> <i>(1.8°C is the book's figure; a 1°F rise is really about 0.5°C)</i>; tell AP to report each temperature as soon as it is taken; if it is up, assess the heart right away and check the monitor for dysrhythmias.","bullets":["<b>Apical pulse, BP, temp at least q4h</b>","<b>Temp ↑ even 1°F → report now</b> (thyroid storm; book adds \"1.8°C\", really ≈ 0.5°C)","AP report temps <b>immediately</b>; if up, check heart + monitor"],"why":""}]},{"k":"gs","gist":"<b>Lower hormone production</b> (methimazole, radioactive iodine or surgery), <b>block the sympathetic effects</b> with a beta blocker meanwhile, <b>reduce metabolic demand</b> (rest, cool and quiet), meet calorie needs, and <b>protect the eyes</b>.","terms":[{"t":"Why treatment is slow","see":"Weeks before methimazole or radioactive iodine brings relief.","why":"The gland is <b>full of stored hormone</b>. Methimazole stops <b>new</b> hormone from being made, and RAI destroys cells, but neither stops the stored hormone from being released.","means":"<b>Beta blockers</b> treat the effects in the meantime. <b>Iodine (SSKI)</b> is the fast one before surgery — it reduces the gland’s blood flow and hormone release."}],"cards":[{"t":"Thionamides — first treatment","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"<b>methimazole is preferred</b> (easier to use); <b>propylthiouracil (PTU)</b> is used much less because of <b>liver toxicity</b>. They block hormone production by <b>stopping iodide binding</b> in the gland. Response is <b>delayed</b> because stored hormone keeps being released. Remission is possible, especially with mild disease and a small goiter. The two are <b>not interchangeable</b> — PTU doses are much higher.","bullets":["<b>Methimazole first-line</b>; PTU less (liver toxicity)","Block production (<b>stop iodide binding</b>) → <b>delayed</b> effect (stored hormone)","<b>Not interchangeable</b>; PTU doses much higher"],"why":""},{"t":"Beta blockers","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"<b>atenolol or propranolol</b> relieve <b>sweating, anxiety, tachycardia and palpitations</b> — supportive only, they <b>do not lower hormone production</b>.","bullets":["<b>Atenolol/propranolol</b>: ↓ sweating, anxiety, tachycardia, palpitations","<b>Don't</b> lower hormone production"],"why":""},{"t":"How it works","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"oral <b>¹³¹I</b>, dosed to gland size and sensitivity. The thyroid takes it up and the local radiation <b>destroys some hormone-producing cells</b>. Stored hormone means relief takes <b>6–8 weeks</b>, so antithyroid drugs may still be needed early on. <b>Not in pregnancy</b> — it crosses the placenta and damages the fetal thyroid. Outpatient; one dose is often enough, but some patients need a second.","bullets":["Oral <b>¹³¹I</b> → gland takes it up → destroys hormone cells","Relief in <b>6–8 weeks</b> (stored hormone) → may need drugs meanwhile","<b>Never in pregnancy</b> · outpatient, often one dose (some need two)"],"why":"Both the drugs and radioactive iodine work slowly for the same reason: the gland is <b>full of stored hormone</b> on thyroglobulin, and nothing that stops new production stops that store from being released. That is why beta blockers are given meanwhile (they treat the effects now), and why iodine is the one drug that acts fast before surgery — it shrinks blood flow and release."}]},{"k":"ta","gist":"<b>Apical pulse, BP and temperature at least every 4 hours</b> — report any <b>1°F rise</b>; quiet, <b>cool</b> room and rest; ice water and dry linens; <b>artificial tears</b>, dark glasses, head of bed raised at night; give methimazole and propranolol; <b>SSKI diluted, 1 hour after the thionamide</b>; teach RAI precautions; <b>never palpate the goiter</b>.","terms":[],"cards":[{"t":"Reduce stimulation","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"rest; a <b>quiet room</b> — door closed, fewer visitors, non-essential care postponed — to keep symptoms and cardiac risk down.","bullets":["Rest, <b>quiet room</b>, few visitors, postpone non-essential care"],"why":""},{"t":"Comfort","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"<b>cool room</b>; AP keep <b>fresh ice water</b> at the bedside and <b>change damp linens</b> from sweating; cool showers or sponge baths several times a day; <b>artificial tears</b> for exophthalmos.","bullets":["<b>Cool room</b>, <b>ice water</b>, change <b>damp linen</b>, cool showers","<b>Artificial tears</b> for exophthalmos"],"why":""},{"t":"Iodine (SSKI)","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"saturated solution of potassium iodide: give <b>orally, diluted in a glass of water or a beverage</b>; give <b>1 hour after a thionamide</b> or <b>1 week after radioactive iodine</b> to avoid worsening hyperthyroidism. Used <b>short term before surgery</b>: it reduces blood flow through the gland and hormone release; improvement within about <b>2 weeks</b>, though metabolism can take weeks longer to normalize. Can cause <b>hypothyroidism</b> — monitor and adjust the drug regimen.","bullets":["SSKI <b>diluted</b> in water/beverage","<b>1 h after thionamide</b> · <b>1 week after RAI</b>","<b>Short term before surgery</b>: ↓ gland blood flow + release; better in ~<b>2 weeks</b> (metabolism normal weeks later)","Can cause <b>hypothyroidism</b> → monitor"],"why":""},{"t":"Precautions at home (Box 55.5)","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"the low dose usually clears the body within <b>a month</b>, but the source is unsealed: some radioactivity is in <b>urine, saliva and stool</b> for the <b>first few days</b> (saliva through the first week), so precautions cover that time. <b>Sit to urinate</b>; <b>flush 2–3 times</b> with the lid closed; condom catheter (men) or <b>flushable tissue layers</b> (women) for incontinence instead of gel pads. Stay <b>at least 6 feet from pregnant women, infants and young children</b> for the prescribed time (usually <b>at least a week</b>), including not sharing a bed. <b>Don't share toothbrushes or toothpaste</b>, <b>don't prepare food or share drinks</b>. Return to work and travel may wait only <b>a few days</b>, depending on the dose.","bullets":["Low dose, usually gone in <b>a month</b>; radioactivity in <b>urine, saliva, stool</b> for the <b>first few days</b>","<b>Sit to urinate</b>, <b>flush 2–3× lid closed</b>","<b>6 feet</b> from pregnant women, infants, young children (~<b>≥ 1 week</b>); no shared bed","No shared <b>toothbrush/toothpaste</b>, no <b>food prep or shared drinks</b>","Back to work/travel in <b>a few days</b> (dose-dependent)"],"why":""},{"t":"Graves eye care","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"treating the hyperthyroidism usually <b>doesn't fully fix</b> the eyes; care is symptomatic: <b>elevate the head of the bed at night</b>, <b>artificial tears</b>, <b>dark glasses</b> for photophobia, <b>gently tape the lids closed at bedtime</b> if they don't close. Pressure behind the eye can cut blood supply → <b>ischemia and blindness</b>: short-term <b>high-dose prednisone, tapered</b>; selenium, <b>teprotumumab</b>; <b>orbital decompression</b> surgery if sight or the eye is threatened.","bullets":["Treatment <b>doesn't fully fix</b> the eyes","<b>HOB up at night</b>, <b>artificial tears</b>, <b>dark glasses</b>, <b>tape lids</b> at bedtime","Pressure → <b>ischemia, blindness</b> → <b>high-dose prednisone</b> (tapered), teprotumumab, <b>orbital decompression</b>"],"why":""}]},{"k":"eo","gist":"Heart rate controlled, <b>no temperature rise</b>, weight stable, eyes protected. Then watch for the opposite: <b>hypothyroidism</b> after RAI or surgery (weight gain, slow pulse, cold intolerance) — follow-up thyroid tests continue for years.","terms":[],"cards":[{"t":"Thionamide teaching","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"<b>avoid crowds and sick people</b> — they lower the immune response; report <b>weight gain, slow heart rate, cold intolerance</b> (signs of hypothyroidism → dose may be too high); <b>methimazole causes birth defects</b> — report pregnancy (may be switched in the first trimester); with <b>PTU, report dark urine or yellow skin or eyes</b> (liver toxicity or failure).","bullets":["<b>Avoid crowds/sick people</b> (↓ immunity)","Report <b>weight gain, slow HR, cold intolerance</b> (now hypothyroid)","<b>Methimazole → birth defects</b>: report pregnancy","<b>PTU: dark urine, jaundice</b> → liver toxicity"],"why":""},{"t":"Afterward","tag":"","topic":"55-treating-hyperthyroidism-drugs-radioacti","text":"many patients become <b>hypothyroid</b> and need <b>lifelong replacement</b>; hypothyroidism can appear <b>years later</b>, so follow-up thyroid tests continue. Radiation thyroiditis (mild, gone within a week) can follow in 5–10 days.","bullets":["Often <b>hypothyroid</b> → <b>lifelong replacement</b>","Can appear <b>years later</b> → lifelong follow-up"],"why":""}]}]},{"id":"thyroid-storm","ch":"55","sys":"Hormones & glucose","name":"Thyroidectomy and thyroid storm","patient":"Six hours after a total thyroidectomy for Graves disease, a client says her lips feel tingly and her voice is hoarse.","topics":["55-thyroidectomy-and-thyroid-storm"],"report":["Six hours after a total thyroidectomy, the client reports tingling around the lips and fingertips; Chvostek sign positive; voice hoarse but unchanged; no stridor, SpO₂ 96%, dressing dry front and back.","Graves disease; total thyroidectomy this morning.","Probable hypocalcemia from parathyroid injury; the airway is currently stable.","Requesting a stat serum calcium and an order for IV calcium gluconate. Emergency airway equipment is at the bedside."],"guide":[{"key":"55:1","name":"Hyperthyroidism, thyroidectomy & thyroid storm"}],"nodes":[{"id":"hyperthyroid","name":"Hyperthyroidism, thyroidectomy & storm"},{"id":"calcium","name":"Calcium, PTH & nerve excitability"}],"drugs":[{"id":"cagluconate","name":"Calcium gluconate (IV)"},{"id":"propranolol","name":"Propranolol (in hyperthyroidism)"},{"id":"methimazole","name":"Methimazole"},{"id":"ptu","name":"Propylthiouracil (PTU)"},{"id":"sski","name":"Potassium iodide (SSKI)"}],"videos":[{"id":"iXNOHZTE5VM","title":"Surgery for Graves’ disease (UCLA Health)","see":"When surgery is the right treatment for Graves’ disease, and what the operation involves"},{"id":"_JdLagGMiLg","title":"Hypocalcemia and Chvostek’s sign (emergency physician)","see":"A real positive Chvostek sign — the facial twitch when the facial nerve is tapped — after thyroid surgery"}],"steps":[{"k":"rc","gist":"After thyroid surgery: <b>stridor</b>, dyspnea, <b>bleeding behind the neck</b>, <b>tingling around the mouth and fingers</b>, twitching, <b>Chvostek and Trousseau signs</b>, and <b>hoarseness</b>. Thyroid storm: <b>fever and tachycardia</b>, then agitation, delirium, vomiting, diarrhea, seizures.","terms":[{"t":"Laryngeal stridor","see":"Harsh, high-pitched sound on breathing in; dyspnea, falling SpO₂, drooling, can’t swallow.","why":"The upper airway is <b>narrowing</b> — from a <b>hematoma</b> pressing on the trachea, swelling, <b>laryngospasm</b> from low calcium, or injury to both laryngeal nerves.","means":"<b>Acute airway obstruction</b> → call the <b>Rapid Response Team</b>. Keep the tracheostomy tray, oxygen and suction in the room."},{"t":"Bleeding behind the neck","see":"Dressing dry in front but blood pooled at the back of the neck; neck feels tight; respiratory distress.","why":"Blood flows down with <b>gravity</b> to the back of the neck. A <b>hematoma</b> in the closed neck can <b>compress the trachea</b>.","means":"Most likely in the <b>first 24 hours</b>. Check behind the neck every time you check the dressing. Moderate serosanguineous drainage in the drain is expected."},{"t":"Perioral and fingertip tingling, muscle twitching","see":"Numbness or tingling of the lips, fingers and toes; twitching of the face.","why":"The <b>parathyroid glands</b> sit on the back of the thyroid and can be removed, bruised or lose blood supply. <b>PTH falls → calcium falls.</b> Calcium normally steadies nerve membranes, so low calcium makes nerves <b>fire too easily</b>.","means":"Early sign of <b>hypocalcemia</b> → report, check calcium, have <b>IV calcium gluconate</b> ready. It can progress to tetany and <b>laryngospasm</b>."},{"t":"Chvostek and Trousseau signs","see":"Chvostek: tapping the facial nerve in front of the ear makes the corner of the mouth twitch. Trousseau: a BP cuff inflated on the arm causes a hand spasm.","why":"Both show <b>neuromuscular irritability</b> from low calcium.","means":"A positive sign means <b>report now</b> — tetany may be developing."},{"t":"Hoarseness and a weak voice","see":"Voice softer or rough after surgery.","why":"Irritation or injury of the <b>recurrent laryngeal nerve</b>, which runs beside the thyroid and moves the vocal cords.","means":"Usually <b>temporary</b> — check the voice every 2 hours. Hoarseness alone is common; <b>stridor is not</b>."},{"t":"Thyroid storm: fever and tachycardia","see":"High fever, HR often very fast, agitation, delirium, vomiting, diarrhea, seizures, coma.","why":"A sudden release of thyroid hormone in <b>uncontrolled hyperthyroidism</b> drives the metabolic rate and sympathetic activity to extremes.","means":"<b>Life-threatening.</b> Report a temperature rise of <b>even 1°F</b> in any hyperthyroid client — even after thyroidectomy."}],"cards":[{"t":"Hemorrhage","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"most likely in the <b>first 24 hours</b>. Inspect the dressing <b>and behind the neck</b> — blood pools there. A <b>moderate amount of serosanguineous drainage</b> in a drain is normal. Bleeding can show as <b>respiratory distress</b> from tracheal compression.","bullets":["<b>First 24 h</b>","Look <b>behind the neck</b>","Moderate <b>serosanguineous</b> drain output = normal","Can present as <b>respiratory distress</b> (tracheal compression)"],"why":"Every complication after thyroidectomy is an <b>anatomy problem</b>: the gland sits on the trachea (bleeding and swelling compress it), the parathyroids are glued to its back (calcium falls), and the recurrent laryngeal nerves run beside it (the voice changes, or the cords close). Hoarseness alone is common and usually temporary; <b>stridor is not</b> — it is the airway closing."},{"t":"Hypocalcemia and tetany","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"if the <b>parathyroids</b> are removed, bruised or lose blood supply, PTH falls → <b>hypocalcemia</b>. Ask about <b>tingling around the mouth or in the fingers and toes</b>; watch for <b>muscle twitching</b>. Keep <b>IV calcium gluconate</b> available.","bullets":["Parathyroids injured → ↓ PTH → <b>↓ Ca²⁺</b>","Ask: <b>tingling around mouth, fingers, toes</b>; watch <b>twitching</b>","<b>IV calcium gluconate</b> on hand"],"why":""},{"t":"Laryngeal nerve damage","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"<b>hoarseness and a weak voice</b>. Check the voice <b>every 2 hours</b> and document; reassure that hoarseness is <b>usually temporary</b>.","bullets":["<b>Hoarse, weak voice</b>","Check voice <b>q2h</b>; usually <b>temporary</b>"],"why":""},{"t":"Thyroid storm — what you see","tag":"Thyroid storm","topic":"55-thyroidectomy-and-thyroid-storm","text":"key signs: <b>fever and tachycardia</b>. Also abdominal pain, nausea, vomiting, diarrhea; anxiety and tremors → <b>restlessness, confusion, psychosis, seizures, coma</b>.","bullets":["Key: <b>fever + tachycardia</b>","Abdominal pain, N/V/D; anxiety, tremor → <b>confusion, psychosis, seizures, coma</b>"],"why":"The antipyretic must be <b>non-salicylate</b> because aspirin displaces thyroid hormone from its carrier proteins and raises the <b>free</b> hormone — the active form — making the storm worse. Propranolol does double duty: it blocks the racing heart and also slows the conversion of T4 to the more active T3."}]},{"k":"ac","gist":"Every complication is <b>anatomy</b>: the gland sits on the <b>trachea</b> (bleeding and swelling compress it), the <b>parathyroids</b> are on its back (calcium falls), and the <b>recurrent laryngeal nerves</b> run beside it (voice changes or airway closure). <b>Thyroid storm</b> is a surge of hormone in uncontrolled hyperthyroidism, triggered by <b>infection, trauma, surgery, DKA, pregnancy, RAI or palpating the goiter</b>.","terms":[{"t":"Why no aspirin in thyroid storm","see":"Fever treated with acetaminophen, not aspirin.","why":"Aspirin (a salicylate) <b>displaces thyroid hormone from its carrier proteins</b>, raising the <b>free</b>, active hormone and making the storm worse.","means":"Use <b>acetaminophen</b> plus a cooling blanket or ice packs."},{"t":"Why propranolol in thyroid storm","see":"Oral propranolol for the heart rate.","why":"Blocks the <b>beta-adrenergic</b> effects (racing heart, tremor) and also <b>slows conversion of T4 to the more active T3</b>.","means":"Continuous cardiac monitoring; watch BP and heart rate."},{"t":"Preparing the gland before surgery","see":"Thionamides until euthyroid, then iodine for a short time.","why":"A <b>euthyroid</b> client is far less likely to go into storm. <b>Iodine</b> shrinks the gland’s size and <b>blood supply</b>, so there is less bleeding.","means":"Hypertension, dysrhythmias and tachycardia must be <b>controlled before surgery</b>."}],"cards":[{"t":"When and how","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"for hyperthyroidism that doesn't respond to other treatment, <b>severe disease</b>, patients who <b>can't tolerate</b> other treatment, or a large goiter <b>compressing the trachea or esophagus</b>. <b>Total</b> (then lifelong replacement) or <b>subtotal</b> thyroidectomy, often minimally invasive; surgeons avoid the <b>parathyroid glands</b> and <b>recurrent laryngeal nerves</b>.","bullets":["When drugs fail, <b>severe disease</b>, can't tolerate other treatment, or goiter <b>compresses trachea/esophagus</b>","<b>Total</b> (lifelong replacement) or <b>subtotal</b>","Surgeon protects <b>parathyroids</b> + <b>recurrent laryngeal nerves</b>"],"why":""},{"t":"Thyroid storm — what and why","tag":"Thyroid storm","topic":"55-thyroidectomy-and-thyroid-storm","text":"a life-threatening surge in <b>uncontrolled hyperthyroidism</b>, usually Graves: excess hormone release drives the metabolic rate dramatically up; <b>fatal if untreated</b>, and deadly even with treatment. Triggers: <b>trauma, infection, DKA, pregnancy</b>, <b>vigorous palpation of the goiter</b>, iodine exposure, <b>RAI</b>. Rare after surgery now, thanks to drugs beforehand.","bullets":["Uncontrolled hyperthyroidism (Graves) → <b>hormone surge</b>; <b>fatal untreated</b>","Triggers: <b>trauma, infection, DKA, pregnancy</b>, <b>palpating the goiter</b>, iodine, <b>RAI</b>"],"why":""}]},{"k":"ph","gist":"<b>Airway first</b>: obstruction from a hematoma, edema, laryngospasm (low calcium) or nerve injury. Then <b>hemorrhage</b>, <b>hypocalcemia and tetany</b>, and <b>thyroid storm</b>.","terms":[],"cards":[{"t":"Airway","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"swelling, tetany or <b>laryngeal nerve damage</b> can cause obstruction; <b>laryngeal stridor</b> (harsh, high-pitched) means acute obstruction. Keep <b>emergency tracheostomy equipment</b> in the room and oxygen and suction working. <b>Critical rescue</b>: stridor, dyspnea, <b>falling SpO₂, inability to swallow, drooling</b> → <b>call the Rapid Response Team</b>.","bullets":["Causes: swelling, tetany, <b>laryngeal nerve</b> damage","<b>Stridor</b> = acute obstruction","<b>Trach kit in room</b>, O₂ + suction ready","Stridor, dyspnea, ↓ SpO₂, <b>can't swallow, drooling</b> → <b>Rapid Response</b>"],"why":""}]},{"k":"gs","gist":"Keep the <b>airway patent</b> with emergency equipment ready, find <b>bleeding and low calcium early</b>, and in thyroid storm: support the airway, <b>block hormone production</b> (thionamide, then iodide), <b>block the heart effects</b> (propranolol), <b>cool</b> the client and replace fluids.","terms":[],"cards":[{"t":"Before surgery","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"thionamides first so the patient is <b>euthyroid</b>; <b>iodine</b> to shrink the gland's size and <b>vascularity</b> (less bleeding, less storm risk). <b>Hypertension, dysrhythmias and tachycardia must be controlled.</b> Teach deep breathing, to <b>support the neck with both hands behind it</b> when coughing or moving, and to expect a drain and dressing.","bullets":["Thionamides → <b>euthyroid</b>; <b>iodine</b> ↓ size + <b>vascularity</b>","Control <b>HTN, dysrhythmias, tachycardia</b>","Teach deep breathing + <b>both hands behind the neck</b> to cough/move; drain + dressing"],"why":""}]},{"k":"ta","gist":"VS <b>every 15 minutes until stable</b>; <b>semi-Fowler</b>, neck supported, <b>no neck extension</b>; check the dressing <b>and behind the neck</b>; <b>trach tray, oxygen and suction</b> at the bedside; voice <b>every 2 hours</b>; ask about <b>tingling</b>, check Chvostek/Trousseau and calcium; <b>IV calcium gluconate</b> available; stridor or falling SpO₂ → <b>Rapid Response</b>. Storm: cooling, <b>acetaminophen</b>, propranolol, methimazole or PTU then iodide, glucocorticoids, continuous cardiac monitoring, normal saline.","terms":[],"cards":[{"t":"After surgery — the routine","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"monitoring for complications is <b>the most important nursing action</b>. Vital signs <b>every 15 minutes until stable</b>, then every 30. Pain relief; pillows supporting head and neck; <b>semi-Fowler</b> while awake; <b>avoid neck extension</b>; deep breathe every <b>30–60 minutes</b>; suction as needed.","bullets":["<b>Watching for complications = top priority</b>","VS <b>q15 min until stable</b>, then q30","<b>Semi-Fowler</b>, pillows, <b>no neck extension</b>, deep breaths q30–60 min, suction"],"why":""},{"t":"Critical rescue","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"in any hyperthyroid patient — <b>even after thyroidectomy</b> — check temperature often: a rise of <b>even 1°F (1.8°C)</b> <i>(the book's Celsius figure; really about 0.5°C)</i> may mean impending crisis → <b>report immediately</b>.","bullets":["Check temp often, <b>even after surgery</b>","<b>↑ 1°F → report now</b> (book adds \"1.8°C\", really ≈ 0.5°C)"],"why":""},{"t":"Thyroid storm — emergency care","tag":"Thyroid storm","topic":"55-thyroidectomy-and-thyroid-storm","text":"<b>airway and ventilation</b>; oral <b>methimazole or PTU</b> (if not possible, <b>cholestyramine</b>, a bile acid sequestrant, to lower hormone levels); <b>iodide</b>, <b>non-salicylate antipyretics</b> (acetaminophen) and <b>glucocorticoids</b>; oral <b>propranolol</b> for heart rate; <b>continuous cardiac monitoring</b>; VS every <b>15–30 minutes</b>; <b>cooling blanket or ice packs</b>; <b>normal saline</b> for dehydration.","bullets":["<b>Airway + ventilation</b>","<b>Methimazole/PTU</b> (or <b>cholestyramine</b>)","<b>Iodide</b>, <b>acetaminophen (not aspirin)</b>, <b>steroids</b>","<b>Propranolol</b> for HR; <b>continuous ECG</b>; VS q15–30 min","<b>Cooling blanket/ice</b>, <b>normal saline</b>"],"why":""}]},{"k":"eo","gist":"Airway patent, SpO₂ stable, <b>no hematoma</b>; calcium in range <b>without tetany</b>; voice stable or improving; temperature and heart rate normal. After a total thyroidectomy the client knows <b>replacement is lifelong</b>.","terms":[],"cards":[{"t":"Long-term teaching","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"report any <b>return or increase</b> of hyperthyroid symptoms; know the signs of <b>hypothyroidism</b> and the possible need for <b>lifelong replacement</b>; keep follow-up — hypothyroidism can appear <b>years after RAI</b>, and most patients need <b>1–2 dose adjustments</b> after surgery.","bullets":["Report return of hyper symptoms; know <b>hypo</b> signs","Lifelong follow-up: hypo can appear <b>years after RAI</b>; <b>1–2 dose adjustments</b> after surgery"],"why":""}]}]},{"id":"hypopara","ch":"55","sys":"Hormones & glucose","name":"Hypoparathyroidism and hypocalcemia","patient":"A client who had neck surgery for thyroid cancer last year ran out of calcium pills a week ago and now has numb lips and cramping hands.","topics":["55-hypoparathyroidism-and-hyperparathyroidi"],"report":["The client’s serum calcium is 6.9 mg/dL; reports perioral numbness and hand cramps; Trousseau sign positive. Voice normal, no stridor, SpO₂ 97%.","Total thyroidectomy for thyroid cancer last year with hypoparathyroidism afterward; ran out of calcium carbonate and calcitriol a week ago.","Symptomatic hypocalcemia with impending tetany.","Requesting an order for IV calcium gluconate, a magnesium and phosphorus level, and cardiac monitoring. Seizure precautions are in place."],"guide":[{"key":"55:2","name":"Parathyroid disorders & calcium"}],"nodes":[{"id":"pth","name":"Parathyroid & calcium"},{"id":"calcium","name":"Calcium, PTH & nerve excitability"}],"drugs":[{"id":"cagluconate","name":"Calcium gluconate (IV)"},{"id":"calcitriol","name":"Calcitriol"}],"videos":[{"id":"_JdLagGMiLg","title":"Hypocalcemia and Chvostek’s sign (emergency physician)","see":"A real positive Chvostek sign — the facial twitch when the facial nerve is tapped — after thyroid surgery"},{"id":"3SaxyLDMlaA","title":"Hypoparathyroidism and hyperparathyroidism (Level Up RN)","see":"PTH’s effects on calcium and phosphorus, and the opposite signs of too little and too much"}],"steps":[{"k":"rc","gist":"<b>Neuromuscular irritability</b> from low calcium: <b>numbness and tingling around the mouth and in the hands and feet</b>, muscle cramps, twitching, <b>carpopedal spasm</b>, <b>positive Chvostek and Trousseau signs</b>, and in severe cases <b>laryngospasm</b> and <b>seizures</b>.","terms":[{"t":"Perioral and digital paresthesias","see":"Numbness or tingling around the mouth and in the fingers and toes.","why":"Calcium normally sits on nerve membranes and <b>steadies the sodium channels</b>. When calcium is low, the channels open too easily, so nerves <b>fire spontaneously</b>.","means":"The <b>earliest</b> sign — check the calcium and report."},{"t":"Carpopedal spasm and tetany","see":"Fingers, hands and elbows flex involuntarily; feet cramp.","why":"Overexcitable nerves make the muscles <b>contract and stay contracted</b>.","means":"Flexing of the fingers, hands and elbows signals <b>impending tetany</b> — an emergency."},{"t":"Chvostek and Trousseau signs","see":"Chvostek: tap in front of the ear → corner of the mouth twitches. Trousseau: BP cuff on the arm → hand spasm.","why":"Both show that the nerves are <b>hyperexcitable</b>.","means":"Positive = significant hypocalcemia → report."},{"t":"Laryngospasm","see":"Stridor, crowing respirations, difficulty breathing.","why":"Tetany of the <b>muscles of the larynx</b> closes the airway.","means":"<b>Airway emergency</b> — IV calcium, rapid response, airway equipment."},{"t":"Seizures","see":"Seizures, often without loss of consciousness or incontinence; irritability up to psychosis.","why":"Overexcitable <b>brain neurons</b>.","means":"<b>Seizure precautions</b>; IV calcium."}],"cards":[{"t":"Ask and look","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"head or neck <b>surgery or radiation</b>; serious neck injury (car crash, strangulation). <b>Mild–moderate</b>: <b>tingling and numbness around the mouth and in the hands and feet</b>. <b>Severe</b>: <b>muscle cramps, carpopedal spasms, seizures</b> (without loss of consciousness or incontinence); irritability to psychosis. Muscle contractions flexing the fingers, hands and elbows signal <b>impending tetany</b>. <b>Trousseau</b> and <b>Chvostek</b> signs; bands or pits on the teeth.","bullets":["Neck <b>surgery/radiation</b>, neck injury","Mild: <b>tingling/numbness lips, hands, feet</b>","Severe: <b>cramps, carpopedal spasm, seizures</b>; irritability → psychosis","Finger/hand/elbow flexion = <b>tetany coming</b> · <b>Trousseau + Chvostek</b>"],"why":""}]},{"k":"ac","gist":"Too little <b>PTH</b> — most often after <b>thyroid or parathyroid surgery</b> — so the bones, kidneys and gut release less calcium: <b>calcium low, phosphorus high</b>, magnesium and PTH low.","terms":[{"t":"Low calcium with high phosphorus","see":"Calcium below 9.0 mg/dL; phosphorus above 4.5 mg/dL.","why":"PTH normally makes the kidney <b>keep calcium and excrete phosphorus</b>. Without it, calcium is lost and phosphorus builds up — they move in <b>opposite</b> directions.","means":"This pattern points to the parathyroids."},{"t":"Low magnesium","see":"Magnesium below 1.3 mEq/L.","why":"The parathyroids need <b>magnesium to release PTH</b>, so a low magnesium keeps the calcium low.","means":"Calcium may not correct until <b>magnesium is replaced</b>."},{"t":"Albumin and calcium","see":"A low total calcium with a low albumin.","why":"Much of the calcium in blood is carried on <b>albumin</b>; when albumin is low, the total calcium reads low even if the active (ionized) calcium is normal.","means":"That is why <b>albumin</b> is checked with calcium — the provider may order an ionized calcium."}],"cards":[{"t":"What and why","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"rare: too little PTH (or PTH that doesn't work) → <b>hypocalcemia</b>. Most often <b>after surgery</b> — thyroidectomy, parathyroidectomy, or head and neck cancer surgery; also autoimmune or genetic. Box 55.7 also lists <b>radiation ablation</b> of the thyroid and <b>congenital dysgenesis</b> (glands that never developed properly).","bullets":["↓ PTH → <b>↓ Ca²⁺</b>","Most often <b>after neck surgery</b>","Also autoimmune, genetic/congenital, <b>thyroid ablation</b> by radiation (Box 55.7)"],"why":""},{"t":"Diagnose","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"serum <b>calcium, magnesium, PTH and albumin</b>; then a <b>24-hour urine calcium</b>; vitamin D (correct any deficiency).","bullets":["<b>Ca, Mg, PTH, albumin</b> → <b>24-h urine Ca</b> → vitamin D"],"why":""},{"t":"Parathyroid labs","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"total <b>calcium 9.0–10.5 mg/dL</b> (2.25–2.62 mmol/L; slightly lower in older adults); <b>phosphorus 3–4.5 mg/dL</b> (0.97–1.45 mmol/L; critical below 1 mg/dL); <b>magnesium 1.3–2.1 mEq/L</b> (0.65–1.05 mmol/L; critical below 0.5 or above 3 mEq/L); <b>PTH 10–65 pg/mL</b> (10–65 ng/L); <b>vitamin D 25–80 ng/mL</b> (62.5–200 nmol/L). Hypoparathyroidism: calcium, magnesium, PTH and vitamin D <b>down</b>, phosphorus <b>up</b>. Hyperparathyroidism: calcium, magnesium and PTH <b>up</b>, phosphorus <b>down</b>, vitamin D <b>variable</b>. The table lists high calcium for <b>primary</b> hyperparathyroidism; in secondary disease (e.g., CKD) the trigger is low calcium (Box 55.7).","bullets":["<b>Ca 9.0–10.5 mg/dL</b> (2.25–2.62 mmol/L; a bit lower in older adults) · <b>P 3–4.5 mg/dL</b> (0.97–1.45 mmol/L)","<b>Mg 1.3–2.1 mEq/L</b> (0.65–1.05 mmol/L) · <b>PTH 10–65 pg/mL</b> (ng/L) · <b>vit D 25–80 ng/mL</b> (62.5–200 nmol/L)","Critical: <b>P &lt; 1 mg/dL</b> · <b>Mg &lt; 0.5 or &gt; 3 mEq/L</b>","Hypopara: Ca, Mg, PTH, vit D <b>↓</b>, <b>P ↑</b>","Hyperpara: Ca, Mg, PTH <b>↑</b>, <b>P ↓</b>, vit D <b>variable</b>; high Ca = <b>primary</b> (secondary starts with low Ca, e.g., CKD)"],"why":""}]},{"k":"ph","gist":"<b>Airway</b> (laryngospasm), then <b>seizures</b> and <b>injury</b> from tetany; <b>cardiac dysrhythmias</b> from low calcium.","terms":[],"cards":[]},{"k":"gs","gist":"<b>Raise calcium</b>: IV calcium gluconate for acute tetany; <b>oral calcium carbonate and calcitriol</b> long term; keep calcium in the <b>low-normal range</b> to prevent symptoms without kidney stones.","terms":[],"cards":[{"t":"Treat","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"acute severe hypocalcemia: <b>IV calcium gluconate</b>. Milder: oral <b>calcitriol</b> (active vitamin D) and <b>calcium carbonate</b>; vitamin D for mild cases; <b>daily calcium</b> long term. Keep calcium in the <b>low-normal range</b> — enough to prevent symptoms, low enough to keep <b>urine calcium</b> down and prevent <b>kidney stones</b>. Teach calcium-rich foods <b>in moderation</b> (milk, yogurt, cheese, ice cream), that therapy is <b>lifelong</b>, and a <b>medical alert bracelet</b>; sticking to the drug and diet plan usually prevents a <b>hypocalcemic crisis</b>.","bullets":["Acute: <b>IV calcium gluconate</b>","Ongoing: <b>calcitriol + calcium carbonate</b>, vitamin D","Keep Ca <b>low-normal</b> → no symptoms, <b>no kidney stones</b>","Calcium foods <b>in moderation</b>, <b>lifelong</b>, <b>medical alert</b> · adherence prevents <b>hypocalcemic crisis</b>"],"why":""}]},{"k":"ta","gist":"<b>IV calcium gluconate</b> per order with <b>cardiac monitoring</b> and a watched IV site; <b>seizure precautions</b>; airway equipment ready; check <b>every calcium result</b>; teach <b>lifelong</b> calcium and vitamin D, calcium-rich foods in moderation and a <b>medical alert bracelet</b>.","terms":[],"cards":[{"t":"Hypocalcemia and tetany","tag":"","topic":"55-thyroidectomy-and-thyroid-storm","text":"if the <b>parathyroids</b> are removed, bruised or lose blood supply, PTH falls → <b>hypocalcemia</b>. Ask about <b>tingling around the mouth or in the fingers and toes</b>; watch for <b>muscle twitching</b>. Keep <b>IV calcium gluconate</b> available.","bullets":["Parathyroids injured → ↓ PTH → <b>↓ Ca²⁺</b>","Ask: <b>tingling around mouth, fingers, toes</b>; watch <b>twitching</b>","<b>IV calcium gluconate</b> on hand"],"why":"Every complication after thyroidectomy is an <b>anatomy problem</b>: the gland sits on the trachea (bleeding and swelling compress it), the parathyroids are glued to its back (calcium falls), and the recurrent laryngeal nerves run beside it (the voice changes, or the cords close). Hoarseness alone is common and usually temporary; <b>stridor is not</b> — it is the airway closing."}]},{"k":"eo","gist":"No tingling, twitching or spasm; <b>Chvostek and Trousseau negative</b>; calcium <b>low-normal</b>; airway clear; the client takes calcium and calcitriol daily and knows the early signs to report.","terms":[],"cards":[]}]},{"id":"hyperpara","ch":"55","sys":"Hormones & glucose","name":"Hyperparathyroidism and hypercalcemia","patient":"A 64-year-old woman has had two kidney stones this year, aching bones, constipation and is more forgetful. Her calcium is 12.4 mg/dL.","topics":["55-hypoparathyroidism-and-hyperparathyroidi"],"report":["The client’s calcium is 12.8 mg/dL, up from 11.6; she is more confused today, nauseated and constipated; urine output adequate.","Primary hyperparathyroidism awaiting parathyroidectomy; takes hydrochlorothiazide for hypertension.","Worsening hypercalcemia with a change in mental status.","Please evaluate. Requesting IV fluid orders, repeat calcium and kidney function, and a review of the thiazide."],"guide":[{"key":"55:2","name":"Parathyroid disorders & calcium"}],"nodes":[{"id":"pth","name":"Parathyroid & calcium"},{"id":"calcium","name":"Calcium, PTH & nerve excitability"}],"drugs":[{"id":"cinacalcet","name":"Cinacalcet"}],"videos":[{"id":"_JdLagGMiLg","title":"Hypocalcemia and Chvostek’s sign (emergency physician)","see":"A real positive Chvostek sign — the facial twitch when the facial nerve is tapped — after thyroid surgery"},{"id":"3SaxyLDMlaA","title":"Hypoparathyroidism and hyperparathyroidism (Level Up RN)","see":"PTH’s effects on calcium and phosphorus, and the opposite signs of too little and too much"}],"steps":[{"k":"rc","gist":"“<b>Stones, bones, groans and moans</b>”: <b>kidney stones</b>, <b>bone pain, fractures and osteoporosis</b>, <b>anorexia, nausea, constipation and peptic ulcer</b>, and <b>fatigue, weakness and confusion</b> that worsen as calcium rises — above <b>12 mg/dL</b>, psychosis and coma.","terms":[{"t":"Kidney stones","see":"Flank pain, hematuria; calcium deposits in the kidneys.","why":"Excess calcium is filtered into the urine, where it <b>precipitates</b> into stones.","means":"<b>Hydration</b> prevents stones; strain urine if a stone is suspected."},{"t":"Bone pain, fractures and osteoporosis","see":"Aching bones, fractures with little trauma, loss of height.","why":"PTH <b>speeds osteoclasts</b> (bone breakdown) and slows osteoblasts, pulling calcium out of bone.","means":"Fragile bones: use a <b>lift sheet</b> to reposition — never pull; prevent falls; encourage weight-bearing activity."},{"t":"Anorexia, nausea, constipation and peptic ulcer","see":"Poor appetite, nausea, hard stools, epigastric pain.","why":"High calcium makes smooth muscle <b>less excitable</b>, so the gut slows. It also raises <b>gastrin</b>, which increases stomach acid → <b>ulcers</b>.","means":"Fluids, fiber, mobility; ask about epigastric pain and black stools."},{"t":"Fatigue, weakness, lethargy and confusion","see":"Tired, weak muscles, depressed, forgetful; confusion or psychosis at higher levels.","why":"The opposite of low calcium: high calcium makes nerves and muscles <b>less excitable</b>.","means":"Calcium <b>above 12 mg/dL</b> → confusion, coma and death if untreated. A change in mental status = <b>report now</b>."}],"cards":[{"t":"Ask and look","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"fractures, weight loss, arthritis, stress, head or neck radiation. Chronic: <b>waxy pallor</b>, bone deformities. <b>Kidney stones</b> and calcium in the kidneys; <b>bone lesions, fractures, cysts, osteoporosis</b>. GI: <b>anorexia, nausea, vomiting, epigastric pain, constipation, weight loss</b>; high calcium raises <b>gastrin</b> → <b>peptic ulcer</b>. Fatigue and lethargy worsen as calcium rises; <b>above 12 mg/dL</b> (3.0 mmol/L): <b>psychosis and confusion → coma and death</b> if untreated. X-rays: stones, deposits, lesions; bone density loss.","bullets":["<b>Kidney stones</b> · <b>fractures, cysts, osteoporosis</b>","GI: anorexia, N/V, epigastric pain, <b>constipation</b>; ↑ gastrin → <b>peptic ulcer</b>","Fatigue, lethargy; <b>Ca &gt; 12 mg/dL (3.0 mmol/L) → confusion, psychosis, coma, death</b>"],"why":"Hypercalcemia's old mnemonic — <b>stones, bones, abdominal groans and psychic moans</b> — is just PTH's targets turned against the patient: calcium dumped into urine forms stones, calcium pulled from bone leaves fractures, high calcium slows the gut and stimulates gastrin, and it dulls the brain. After surgery the problem flips overnight, because glands that were suppressed for years cannot restart at once."}]},{"k":"ac","gist":"Too much <b>PTH</b> → calcium pulled from <b>bone</b>, kept by the <b>kidney</b> and absorbed from the <b>gut</b>: <b>calcium high, phosphorus low</b>. <b>Primary</b>: a gland ignores calcium feedback (often an adenoma). <b>Secondary</b>: <b>vitamin D deficiency or chronic kidney disease</b> keeps calcium low, so PTH stays high.","terms":[{"t":"High calcium, low phosphorus, high PTH","see":"Calcium above 10.5 mg/dL, phosphorus below 3, PTH above 65 pg/mL.","why":"PTH makes the kidney <b>keep calcium and excrete phosphorus</b>, and releases calcium from bone.","means":"Confirms <b>primary</b> hyperparathyroidism. Thiazide diuretics and lithium can also raise calcium — review the drug list."}],"cards":[{"t":"What and why","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"too much PTH → <b>hypercalcemia and hypophosphatemia</b>. In bone, PTH <b>slows osteoblasts and speeds osteoclasts</b> → calcium and phosphorus leave bone, <b>density falls</b>; chronic excess calcium <b>deposits in soft tissues</b>. <b>Primary</b>: one or more glands ignore calcium feedback. <b>Secondary</b>: <b>vitamin D deficiency</b> and <b>chronic kidney disease</b>. Others (Box 55.7): a <b>parathyroid tumor or cancer</b>, <b>congenital hyperplasia</b>, CKD with hypocalcemia, poor calcium absorption (celiac disease, bariatric surgery), drugs (diuretics, bisphosphonates), inherited <b>MEN1</b>, neck trauma or radiation, PTH-secreting cancers of the <b>lung, kidney or GI tract</b>.","bullets":["↑ PTH → <b>↑ Ca²⁺, ↓ phosphorus</b>","Bone: ↓ osteoblasts, ↑ osteoclasts → <b>density ↓</b>; Ca deposits in soft tissue","<b>Primary</b>: gland ignores feedback · <b>secondary</b>: <b>vit D deficiency, CKD</b>","Box 55.7 also: <b>parathyroid tumor/cancer</b>, congenital hyperplasia, malabsorption, diuretics, bisphosphonates, MEN1, neck trauma/radiation, PTH-secreting cancers"],"why":""}]},{"k":"ph","gist":"<b>Risk for injury</b> (fractures, falls, confusion), <b>kidney stones and kidney injury</b>, and after surgery a <b>hypocalcemic crisis</b> while the remaining glands recover.","terms":[],"cards":[]},{"k":"gs","gist":"<b>Parathyroidectomy</b> — usually curative. Without surgery: <b>cinacalcet</b> to lower PTH, <b>bisphosphonates</b> for the bones, <b>hydration</b>, <b>activity</b> and <b>avoiding lithium</b>.","terms":[],"cards":[{"t":"Without surgery","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"for patients who aren't surgical candidates or want to delay surgery, monitor <b>calcium, kidney function and bone density</b> closely; nursing priorities are monitoring and <b>preventing injury</b>. Drug therapy: <b>cinacalcet</b> (a calcimimetic) binds calcium-sensing receptors on the parathyroids → <b>less PTH</b> → lower calcium, steadier minerals and slower bone damage; used for <b>more severe symptoms</b> or hypercalcemia from <b>parathyroid cancer</b>; monitor calcium routinely. <b>Bisphosphonates</b> are preferred for osteoporosis or fracture risk. Teach <b>regular exercise</b>, <b>good hydration</b> (prevents stones), <b>avoid lithium</b> if possible (it can raise calcium), <b>avoid prolonged bed rest</b>, a diet with <b>moderate</b> calcium and vitamin D. Bones are fragile: AP use a <b>lift sheet</b> to reposition — never pull.","bullets":["Not operating (or delaying): monitor <b>Ca, kidney function, bone density</b>; prevent injury","<b>Cinacalcet</b> (severe symptoms, parathyroid cancer): tricks the gland into sensing high Ca → ↓ PTH; monitor Ca","<b>Bisphosphonates</b> for bone","Teach: <b>exercise</b>, <b>hydration</b>, <b>avoid lithium</b> (raises Ca), no prolonged bed rest, <b>moderate</b> Ca + vit D","Fragile bones → <b>lift sheet</b>, never pull"],"why":""}]},{"k":"ta","gist":"Encourage <b>fluids</b> and <b>mobility</b> (no prolonged bed rest); move with a <b>lift sheet</b>; monitor calcium, kidney function and mental status. After parathyroidectomy: check <b>every calcium</b> result, ask about <b>tingling</b>, test <b>Chvostek and Trousseau</b>, and check the voice.","terms":[],"cards":[{"t":"Parathyroidectomy","tag":"","topic":"55-hypoparathyroidism-and-hyperparathyroidi","text":"the treatment of choice — usually <b>curative</b> (calcium returns to normal). Minimally invasive for a single adenoma, a transverse lower-neck incision when more than one gland must come out; all four glands are examined and only diseased glands are removed (all four if all are diseased). Pre- and post-op care match thyroidectomy; recurrent laryngeal nerve injury is <b>rare</b> — check for voice changes and hoarseness. The remaining glands have <b>atrophied</b> and take <b>days to weeks</b> to recover → <b>hypocalcemic crisis</b> risk: check every calcium result until stable, watch <b>tingling and twitching</b> of face and extremities, <b>Trousseau and Chvostek</b>. If it persists, hypoparathyroidism is <b>permanent</b> → lifelong calcium and vitamin D.","bullets":["<b>Parathyroidectomy</b> = usually <b>curative</b>","Only diseased glands removed (all four if all diseased); care = thyroidectomy","Remaining glands <b>atrophied</b> → <b>hypocalcemic crisis</b> for days–weeks","Check <b>every Ca²⁺</b>, tingling/twitching, <b>Trousseau/Chvostek</b>","Voice changes (laryngeal nerve, rare) · may become <b>permanent</b> hypopara"],"why":""}]},{"k":"eo","gist":"Calcium back in range, no new stones or fractures, clearer thinking; after surgery, <b>no tetany</b> — and if calcium stays low, the client knows replacement may be <b>lifelong</b>.","terms":[],"cards":[]}]},{"id":"dm-new","ch":"56","sys":"Hormones & glucose","name":"Diabetes mellitus: diagnosis, insulin and drugs","patient":"A 52-year-old with a BMI of 33 reports fatigue, thirst and blurred vision for two months. A1C is 8.4% and fasting glucose 168 mg/dL.","topics":["56-types-risk-and-screening","56-diagnosing-and-monitoring-glucose-a1c-cg","56-insulin-types-timing-injection-and-stora","56-antidiabetic-drugs-non-insulin","56-eating-and-exercise-with-diabetes","56-teaching-self-management"],"report":["The client’s A1C is 8.4% and fasting glucose 168 mg/dL; reports polyuria, polydipsia, fatigue and blurred vision.","BMI 33, hypertension, father with type 2 diabetes; no prior diabetes diagnosis.","Findings meet diagnostic criteria for diabetes, most consistent with type 2; no signs of a hyperglycemic crisis.","Requesting a confirmatory test if needed, orders for the initial drug therapy, and referrals to diabetes education and a registered dietitian."],"guide":[{"key":"56:0","name":"Diagnosing & monitoring diabetes"},{"key":"56:1","name":"Insulin & diabetes drugs"}],"nodes":[{"id":"dm-dx","name":"Diabetes: types & diagnosis"},{"id":"dm-rx","name":"Insulin & diabetes drugs"},{"id":"insulin","name":"Insulin, glucagon & glucose"}],"drugs":[{"id":"metformin","name":"Metformin"},{"id":"glipizide","name":"Glipizide"},{"id":"semaglutide","name":"Semaglutide"},{"id":"empagliflozin","name":"Empagliflozin"},{"id":"lispro","name":"Insulin lispro"},{"id":"regular","name":"Regular insulin"},{"id":"nph","name":"NPH insulin"},{"id":"glargine","name":"Insulin glargine"}],"videos":[{"id":"Q_epStvzGyc","title":"Type 1 vs type 2 diabetes (Stanford Medicine animation)","see":"Lost insulin production in type 1 vs insulin resistance with failing beta cells in type 2"},{"id":"uRRBUcO9KiA","title":"Blood glucose monitoring (Open RN nursing skills)","see":"The full bedside check, step by step, from hand hygiene and patient identification to the reading"},{"id":"YU8tib41-_4","title":"Dexcom G7 — how to insert the sensor (Dexcom)","see":"The applicator placing the sensor just under the skin — a CGM reads the fluid between cells, not blood"},{"id":"_fCqEIn7ccA","title":"How to use an insulin pen (Mayo Clinic)","see":"New needle, a priming “air shot”, dialing the dose, and holding the needle in before withdrawing"},{"id":"inVExovmAgE","title":"Mixing insulin (Level Up RN)","see":"Air into cloudy, air into clear, draw clear first, then cloudy — so the vials don’t contaminate each other"},{"id":"OoiX6jx48L8","title":"The 15:15 rule (Dish on Diabetes)","see":"15 g of fast carbohydrate, recheck in 15 minutes, repeat until the glucose is back in range"}],"steps":[{"k":"rc","gist":"Classic hyperglycemia: <b>polyuria, polydipsia, polyphagia</b>, fatigue, <b>blurred vision</b>, recurrent infections and slow healing. <b>Type 1</b>: abrupt onset with <b>weight loss</b>. <b>Type 2</b>: gradual, often <b>no symptoms</b> — found by screening.","terms":[{"t":"Polyuria and polydipsia","see":"Urinating large amounts, often at night; constant thirst.","why":"When blood glucose rises above what the kidney tubules can reabsorb (about 180 mg/dL), glucose spills into the urine and <b>pulls water with it</b> (<b>osmotic diuresis</b>). The water loss raises serum osmolality, which triggers <b>thirst</b>.","means":"Fluid loss from osmotic diuresis is what makes DKA and HHS dehydration emergencies. Watch intake and output and signs of dehydration."},{"t":"Polyphagia and weight loss","see":"Hungry all the time yet losing weight — most marked in type 1.","why":"Without insulin, cells cannot take in glucose, so they are <b>starving in a sea of sugar</b> and signal hunger. The body breaks down <b>fat and protein</b> for fuel, and calories are lost as glucose in the urine.","means":"Rapid unexplained weight loss suggests <b>absolute insulin deficiency</b> (type 1) and a risk of <b>ketones</b>."},{"t":"Fatigue and weakness","see":"Tired despite rest.","why":"Cells cannot use glucose for energy, and dehydration adds to the weakness.","means":"Improves as glucose comes into target."},{"t":"Blurred vision","see":"Vision blurs and fluctuates with glucose levels.","why":"High glucose shifts fluid in and out of the <b>lens</b>, changing its shape and how it focuses light.","means":"Usually <b>temporary</b> — eye refraction is checked only once glucose is normal. Persistent vision loss suggests <b>retinopathy</b>; refer for a dilated eye exam."},{"t":"Recurrent infections and slow wound healing","see":"Yeast infections, UTIs, skin infections, cuts that heal slowly.","why":"High glucose <b>impairs white blood cell function</b>, reduces tissue oxygen and <b>feeds microbes</b>.","means":"Inspect skin and feet, teach infection signs. An infection also raises glucose further (stress hormones)."},{"t":"Acanthosis nigricans","see":"Dark, velvety skin in the folds of the neck and armpits.","why":"A sign of <b>insulin resistance</b>: persistently high insulin levels stimulate skin cells to thicken and darken.","means":"Part of the metabolic syndrome picture — a cue to <b>screen</b> for type 2 diabetes."}],"cards":[{"t":"Type 1 (T1DM)","tag":"","topic":"56-types-risk-and-screening","text":"<b>autoimmune</b> destruction of beta cells → <b>absolute insulin deficiency</b>; viral infections (mumps, coxsackievirus, COVID-19) may trigger it. Usually before <b>age 30</b>, <b>abrupt</b> onset: thirst, hunger, polyuria, <b>weight loss</b>. Ketosis-prone; <b>everyone needs insulin</b>. Same obesity rate as everyone else. Ask about family type 1, type 2 and other autoimmune disease.","bullets":["<b>Autoimmune</b> beta-cell destruction → <b>no insulin</b>","Usually <b>&lt; 30</b>, <b>abrupt</b>, weight loss, <b>ketosis-prone</b>","<b>All need insulin</b>"],"why":""},{"t":"Type 2 (T2DM)","tag":"","topic":"56-types-risk-and-screening","text":"<b>insulin resistance</b> first (cells respond poorly), then <b>declining beta-cell secretion</b>; strong heredity plus environment (walkability, food security, air quality, access to care). Any adult age, often <b>no symptoms</b> — or thirst, fatigue, blurred vision, or a complication is the first sign. <b>60–80% obese</b>; usually less ketosis-prone, <b>but DKA can occur</b>; the book reports <b>20–30% need insulin</b>. About <b>90–95%</b> of adults with diabetes.","bullets":["<b>Insulin resistance → beta cells decline</b>","Any age, often <b>no symptoms</b>; complications may be first sign","Book: <b>60–80% obese</b>, <b>20–30% need insulin</b>; <b>DKA can occur in type 2</b>","<b>90–95%</b> of diabetes"],"why":""},{"t":"Metabolic syndrome","tag":"","topic":"56-types-risk-and-screening","text":"risk factors that cluster for type 2 diabetes and heart disease: <b>waist ≥ 40 in (men) / ≥ 35 in (women)</b>; <b>fasting glucose ≥ 100</b>; <b>BP ≥ 140/90</b> <i>(the book's cutoff; many guidelines use 130/85)</i>; <b>triglycerides ≥ 150</b>; <b>HDL &lt; 40 (men) / &lt; 50 (women)</b> — or on drugs for any of these. Each speeds atherosclerosis, stroke and early death. It is diagnosed when <b>at least 3</b> of these are present (Fig. 56.5); the figure also shows darkened skin folds (neck, armpits), fatty liver, fatigue, and polycystic ovary syndrome (women) or erectile dysfunction (men).","bullets":["Waist <b>≥ 40 in men / ≥ 35 in women</b>","Fasting glucose <b>≥ 100</b> · BP <b>≥ 140/90</b>","Triglycerides <b>≥ 150</b> · HDL <b>&lt; 40 men / &lt; 50 women</b>","<b>≥ 3 features</b> = metabolic syndrome (Fig. 56.5); each ↑ atherosclerosis, stroke, early death","Also: dark skin folds (neck, armpits), fatty liver, fatigue, PCOS / ED"],"why":""},{"t":"Screening (Box 56.3)","tag":"","topic":"56-types-risk-and-screening","text":"test adults of <b>any age</b> with <b>BMI &gt; 25 (&gt; 23 in Asian Americans)</b> plus a risk factor: a <b>first-degree relative</b>, inactivity, high-risk ethnic group, <b>hypertension</b>, <b>HDL &lt; 35 or triglycerides &gt; 250</b>, <b>polycystic ovary syndrome</b>, cardiovascular disease. <b>Prediabetes → test yearly.</b> <b>GDM history → test every 3 years for life.</b> Everyone else starts at <b>35</b>, repeated at least every <b>3 years</b> if normal.","bullets":["<b>BMI &gt; 25 (&gt; 23 Asian)</b> + a risk factor → test at <b>any age</b>","Risks: <b>1st-degree relative</b>, inactive, ethnicity, <b>HTN</b>, HDL &lt; 35/TG &gt; 250, <b>PCOS</b>, CVD","<b>Prediabetes yearly</b> · <b>GDM every 3 yr</b> · everyone from <b>35</b>, every 3 yr"],"why":"Type 1 and type 2 end in the same complications but begin differently: type 1 is an empty factory (no insulin at all, so ketones form quickly and DKA is the danger), type 2 is a factory whose product is ignored (residual insulin often limits ketone formation, but DKA and mixed DKA/HHS can occur in type 2 as well; slow dehydration and silent chronic damage remain important risks). That is why so much of type 2 is found by <b>screening</b>, not symptoms."}]},{"k":"ac","gist":"Diagnosis: <b>A1C ≥ 6.5%</b>, <b>fasting glucose ≥ 126</b>, <b>2-hour OGTT ≥ 200</b>, or <b>random &gt; 200 with symptoms</b> (two abnormal results unless hyperglycemia is obvious). <b>Type 1</b> = autoimmune beta-cell destruction → absolute insulin deficiency. <b>Type 2</b> = insulin resistance, then declining insulin secretion.","terms":[{"t":"A1C (glycated hemoglobin)","see":"≥ 6.5% = diabetes · 5.7–6.4% = prediabetes · target &lt; 7% for most adults.","why":"Glucose attaches to hemoglobin (<b>glycosylation</b>) in proportion to how high it runs, and stays attached for the red cell’s life of about <b>120 days</b>.","means":"A <b>3-month average</b> that a careful day before the test cannot change. A1C 7 ≈ average glucose 154 mg/dL; each 1% ≈ 28–29 mg/dL. Anemia or blood loss can make it misleading."},{"t":"Type 1: absolute insulin deficiency","see":"Usually younger, abrupt onset, weight loss, ketones.","why":"An <b>autoimmune</b> attack destroys the pancreatic <b>beta cells</b>, so no insulin is made. Without insulin, fat is broken down into <b>ketones</b>.","means":"<b>Everyone with type 1 needs insulin</b>; missing it risks <b>DKA</b> within hours to days."},{"t":"Type 2: insulin resistance","see":"Usually adult, often overweight, gradual or no symptoms.","why":"Cells respond poorly to insulin (<b>resistance</b>), so the pancreas makes more; over years the <b>beta cells wear out</b> and secretion declines.","means":"Lifestyle change and oral or injectable drugs first; many eventually need <b>insulin</b>. Residual insulin usually limits ketones, but DKA can still occur."},{"t":"Fasting glucose and OGTT","see":"Fasting ≥ 126 mg/dL or 2-hour OGTT ≥ 200 mg/dL = diabetes.","why":"Fasting glucose shows how well <b>basal insulin</b> controls the liver’s overnight glucose output; the OGTT shows how well the body handles a glucose load.","means":"Confirm with a second abnormal result. <b>Meter readings</b> are less accurate than <b>lab glucose</b> — anemia falsely raises and polycythemia falsely lowers them."}],"cards":[{"t":"The numbers","tag":"","topic":"56-diagnosing-and-monitoring-glucose-a1c-cg","text":"<b>A1C</b>: normal 4–5.7% · prediabetes <b>5.7–6.4%</b> · diabetes <b>≥ 6.5%</b>. <b>Fasting glucose</b> (no calories for 8 hours): normal 74–100 · prediabetes <b>100–125</b> · diabetes <b>≥ 126</b>. <b>2-hour OGTT</b> (75 g glucose): normal &lt; 140 · prediabetes <b>140–199</b> · diabetes <b>≥ 200</b>. <b>Random glucose &gt; 200</b> with classic symptoms or a hyperglycemic crisis. Fig. 56.1 gives <b>74–106</b> as the normal fasting range — the reference range the book's questions quote; a low is still treated at <b>&lt; 70</b>.","bullets":["<b>A1C</b>: &lt; 5.7 · <b>5.7–6.4</b> prediabetes · <b>≥ 6.5</b> diabetes","<b>Fasting</b>: &lt; 100 · <b>100–125</b> · <b>≥ 126</b>","<b>OGTT 2-h</b>: &lt; 140 · <b>140–199</b> · <b>≥ 200</b>","<b>Random &gt; 200</b> + symptoms","Fig. 56.1 fasting reference range <b>74–106</b> (quoted in the book's questions); treat lows at <b>&lt; 70</b>"],"why":""},{"t":"Confirming it","tag":"","topic":"56-diagnosing-and-monitoring-glucose-a1c-cg","text":"without obvious hyperglycemia, <b>two abnormal results</b> are needed (same sample or two samples) to rule out lab error. The OGTT is sensitive but used mainly for <b>gestational</b> diabetes. Screening usually uses <b>A1C plus fasting glucose</b>.","bullets":["No obvious hyperglycemia → <b>2 abnormal results</b>","OGTT mainly for <b>GDM</b> · screening = <b>A1C + fasting glucose</b>"],"why":""},{"t":"A1C","tag":"","topic":"56-diagnosing-and-monitoring-glucose-a1c-cg","text":"glucose binds hemoglobin (<b>glycosylation</b>): the higher glucose runs, the more is bound. Reflects about <b>120 days</b> (the red cell lifespan) and is <b>not changed by what was eaten the day before</b>. Check at least <b>twice a year</b> when stable, <b>every 3 months</b> after a therapy change or when out of target. Target: <b>&lt; 7%</b> for most nonpregnant adults without significant lows; self-management glucose targets are <b>set individually</b> (diabetes duration, age and life expectancy, other illnesses, severity of heart disease, hypoglycemia unawareness). Average glucose by A1C (Table 56.4): 6 ≈ 126 mg/dL, <b>7 ≈ 154</b>, 8 ≈ 183, 9 ≈ 212, 10 ≈ 240, <b>11 ≈ 269</b>, <b>12 ≈ 298</b> — each 1% adds about 28–29 mg/dL.","bullets":["Glucose sticks to hemoglobin → <b>~120-day average</b>","Not affected by yesterday's meals","<b>Twice a year</b> if stable; <b>every 3 months</b> after change","Target <b>&lt; 7%</b>; glucose targets <b>individualized</b> (duration, age, illnesses, CVD, unawareness)","Table 56.4: 6 ≈ 126 · <b>7 ≈ 154</b> · 8 ≈ 183 · 9 ≈ 212 · 10 ≈ 240 · <b>11 ≈ 269</b> · <b>12 ≈ 298</b> (+28–29 per 1%)"],"why":"A1C works because glucose sticks to hemoglobin and stays stuck for the life of the red cell — a 3-month memory that cannot be faked by a careful day before the appointment. A fingerstick is a snapshot and CGM is a trend recording. Interstitial readings can lag or disagree with symptoms, so assess the person and obtain BGM promptly when indicated; calibration and treatment-decision rules depend on the actual device."}]},{"k":"ph","gist":"<b>Risk for unstable blood glucose</b> — hypoglycemia once treatment starts, hyperglycemic crises with illness — plus the <b>need for self-management skills</b>; long term, <b>vascular and nerve damage</b>.","terms":[],"cards":[{"t":"For every antidiabetic drug","tag":"","topic":"56-antidiabetic-drugs-non-insulin","text":"teach the <b>signs of hypoglycemia</b> — hunger, headache, tremors, sweating, confusion — because many lower glucose even when it isn't high; and <b>check with the provider or pharmacist before any OTC drug, vitamin or supplement</b>.","bullets":["Teach <b>hypoglycemia signs</b> (hunger, headache, tremor, sweating, confusion)","<b>No OTC/vitamins/supplements</b> without asking"],"why":""},{"t":"Who and why injected","tag":"","topic":"56-insulin-types-timing-injection-and-stora","text":"all type 1 and <b>20–30% of type 2</b>. Insulin is a small <b>protein</b> destroyed in the GI tract, so it is <b>injected</b> (or inhaled). Older adults: poor vision, coordination or memory raise <b>dosing errors</b>. Concentrations U-100, U-200, U-300 and <b>U-500</b> (only for very large doses). <b>Insulin is a High-Alert drug.</b> <b>Analogs</b> (e.g., lispro) are human insulin with an altered structure that changes absorption and duration. The insulin type, injection technique and site all change its action, so the type is <b>changed only under the diabetes provider's supervision</b>.","bullets":["All type 1, <b>20–30%</b> type 2","Protein → digested → <b>injected</b>","U-100 usual; <b>U-500</b> for huge doses · <b>High-Alert drug</b>","<b>Analogs</b> (lispro) = altered human insulin","Type, technique, site change action → <b>change type only with the provider</b>"],"why":""}]},{"k":"gs","gist":"Reach <b>individualized glucose targets</b> (A1C &lt; 7% for most adults) with <b>medical nutrition therapy</b>, <b>150 minutes of activity a week</b> and drugs — <b>metformin first line</b> in type 2, <b>insulin for everyone with type 1</b> — and teach <b>survival skills</b> first.","terms":[{"t":"Metformin","see":"First-line oral drug for type 2.","why":"Lowers the <b>liver’s glucose production</b> and improves insulin sensitivity; it does not force insulin out, so it rarely causes lows on its own.","means":"Take <b>with food</b>; <b>no alcohol</b>. Kidney limits go by <b>eGFR</b>: contraindicated <b>below 30</b>, not started at <b>30–45</b>. Around <b>iodinated contrast</b> (eGFR 30–60 or other risk factors) it is stopped and restarted after a <b>48-hour eGFR recheck</b>; around <b>surgery</b> it is held while intake is restricted — both to prevent <b>lactic acidosis</b>."},{"t":"Sulfonylureas (glipizide)","see":"Oral drug taken with or just before meals.","why":"Force the beta cells to <b>release insulin</b> whether or not glucose is high.","means":"<b>Hypoglycemia</b> risk, especially with missed meals, kidney disease or in older adults."},{"t":"GLP-1 agonists and SGLT2 inhibitors","see":"Semaglutide (often once weekly) · empagliflozin.","why":"<b>GLP-1</b>: less glucagon, slower stomach emptying, more fullness. <b>SGLT2</b>: the kidney excretes glucose and sodium in the urine.","means":"GLP-1: nausea, report severe abdominal pain (<b>pancreatitis</b>). SGLT2: dehydration, <b>UTI and genital yeast infections</b>, ketoacidosis risk."},{"t":"Basal–bolus insulin","see":"Long-acting once a day plus rapid-acting with meals.","why":"Copies the pancreas: <b>basal</b> insulin (glargine, NPH) covers between meals and overnight; <b>bolus</b> rapid-acting (lispro) covers each meal.","means":"Fasting glucose shows whether basal is right; after-meal glucose shows the bolus. <b>Insulin is a high-alert drug</b> — double-check doses."}],"cards":[{"t":"When and how","tag":"","topic":"56-antidiabetic-drugs-non-insulin","text":"drugs are added for type 2 when <b>diet, activity and stress management</b> don't reach targets — always <b>with</b> them, never instead. Start at the <b>lowest effective dose</b> and increase; often more than one class. Choice depends on cost, side effects, ability to manage doses (once-daily or weekly helps adherence). Beta cells decline over time, so many eventually need <b>insulin</b> — indicated when 2–3 agents (including a GLP-1 agonist) fail, or <b>A1C &gt; 10% with symptoms</b>.","bullets":["Add when lifestyle isn't enough — <b>with</b>, not instead","Start low, increase; often combined","<b>Insulin</b> when 2–3 agents fail or <b>A1C &gt; 10% with symptoms</b>"],"why":""},{"t":"Metformin (biguanide) — first line","tag":"","topic":"56-antidiabetic-drugs-non-insulin","text":"<b>lowers liver glucose production</b>, reduces intestinal glucose absorption and <b>improves insulin sensitivity</b>. <b>Take with food</b> (GI upset is common). <b>No alcohol</b> (lactic acidosis). <i>The textbook says it is not for anyone with kidney disease and is held 24 hours before iodinated contrast or surgery, restarting when kidney function is normal.</i> <b>Current labeling</b> goes by <b>eGFR</b>: contraindicated <b>below 30</b>, not started at <b>30–45</b>. <b>Iodinated contrast</b>: stop it at or before the procedure when eGFR is <b>30–60</b>, with liver disease, alcoholism or heart failure, or with intra-arterial contrast; <b>recheck eGFR 48 hours later</b> and restart if kidney function is stable. <b>Surgery</b>: hold it while food and fluids are restricted, per the order or protocol (<a href=\"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=bfd6ec0f-8264-4877-aa6d-f347f53bc426\">metformin prescribing information</a>, sections 2.4–2.5 and 5.1). Both rules guard against <b>lactic acidosis</b> and acute kidney injury.","bullets":["<b>First line</b> type 2: ↓ liver glucose, ↓ absorption, ↑ sensitivity","<b>With food</b> (GI upset) · <b>no alcohol</b> (lactic acidosis)","By <b>eGFR</b>: contraindicated <b>&lt; 30</b>; don’t start at <b>30–45</b>","Contrast (eGFR 30–60 or other risk): stop at/before → <b>recheck eGFR at 48 h</b> → restart if stable · surgery: hold while intake is restricted"],"why":"Sort the drugs by <b>where they act</b> and the warnings write themselves. Liver (metformin) → lactic acid if kidneys can't clear it. Beta cell (sulfonylureas) → lows, because insulin is forced out whether or not glucose is high. Gut and stomach (GLP-1, DPP-4, amylin, acarbose) → nausea, gas, pancreatitis. Kidney (SGLT2) → whatever leaves in the urine: water, sodium, and sugar that feeds bacteria and yeast. Receptor (TZD) → fluid retention and heart failure."},{"t":"Timing by type","tag":"","topic":"56-insulin-types-timing-injection-and-stora","text":"<b>Rapid-acting</b> analogs — aspart (onset 10–20 min, peak 1–3 h, lasts 3–5 h), glulisine (10–15 min, peak 1–1.5 h, 3–5 h), <b>lispro</b> (15–30 min, peak 0.5–2.5 h, 3–6 h). <b>Short-acting regular</b>: onset <b>30–60 min</b>, peak <b>1–5 h</b>, lasts <b>6–10 h</b>. <b>Intermediate NPH</b>: onset 1–2 h, peak <b>6–14 h</b>, lasts 16–24 h. <b>Long-acting glargine</b> (onset 70 min, <b>no peak</b>, 18–24 h) and <b>detemir</b> (onset 1–2 h, no peak, 12–24 h). <b>Ultra-long degludec</b>: onset 30–90 min, <b>no peak</b>, 24+ h.","bullets":["<b>Rapid</b> (lispro, aspart, glulisine): onset <b>10–30 min</b>, peak ~<b>0.5–3 h</b>, 3–6 h","<b>Regular</b>: onset <b>30–60 min</b>, peak <b>1–5 h</b>, 6–10 h","<b>NPH</b>: onset 1–2 h, peak <b>6–14 h</b>, 16–24 h","<b>Glargine</b> (onset 70 min), <b>detemir</b> (1–2 h), <b>degludec</b> (30–90 min): <b>no peak</b>, 12–24 h (degludec 24+)"],"why":""},{"t":"Basal and bolus","tag":"","topic":"56-insulin-types-timing-injection-and-stora","text":"regimens copy the pancreas: <b>basal</b> insulin (NPH, glargine, detemir, degludec) about <b>50%</b> of the daily dose to cover between meals and overnight, plus <b>prandial</b> rapid-acting or regular before meals. Lower starting doses for older or very thin patients. The fasting (before-breakfast) glucose shows whether <b>basal</b> is right.","bullets":["<b>Basal ~50%</b> (NPH, glargine, detemir, degludec) + <b>mealtime</b> rapid/regular","Lower start: older, very thin","<b>Fasting glucose</b> judges the basal dose"],"why":""},{"t":"The approach","tag":"","topic":"56-eating-and-exercise-with-diabetes","text":"<b>medical nutrition therapy</b> for everyone, planned with the <b>registered dietitian nutritionist (RDN)</b>, built around <b>culture, money, food access and lifestyle</b>. <b>Consistent timing and amounts</b> help control glucose; insulin users eat in step with their insulin's action. No ideal split of carbohydrate, protein and fat — it is individualized. Overweight: <b>losing 5–10% of body weight</b> markedly improves A1C; weight-loss drugs for <b>BMI ≥ 27</b> (≥ 25 in Asian individuals). Screen for <b>food insecurity</b> and refer. The RDN sees each patient <b>yearly</b> (more often with low health literacy); share diet teaching with <b>whoever prepares the meals</b>, and teach how to adjust food: <b>illness</b> → sick-day rules (fluids every hour; if solids won't stay down, carbohydrate as liquids or soft foods, <b>at least 150 g a day</b>); <b>exercise</b> → unplanned activity needs <b>about 10–15 g of carbohydrate per hour</b>, planned activity a lower insulin dose; <b>social events</b> → alcohol only with food; <b>delayed meals</b> → a late meal while insulin or a sulfonylurea is working causes lows, so carry a carbohydrate snack and glucose.","bullets":["<b>MNT</b> with the <b>RDN</b>; fit culture, money, food access","<b>Consistent timing + amounts</b>; insulin users eat with insulin action","No ideal macro split · <b>5–10% weight loss</b> → better A1C","Weight-loss drugs <b>BMI ≥ 27</b> (≥ 25 Asian) · screen <b>food insecurity</b>","RDN <b>yearly</b>; teach <b>whoever cooks</b>","Ill → sick-day fluids + <b>≥ 150 g carb/day</b> · unplanned exercise → <b>10–15 g carb/hr</b>","Alcohol <b>with food</b> · late meal → carry a <b>carb snack + glucose</b>"],"why":""},{"t":"Why and how much","tag":"","topic":"56-eating-and-exercise-with-diabetes","text":"activity improves <b>insulin sensitivity</b>, glucose control, lipids (raises HDL), BP and heart function, and prevents or delays type 2. Aim for <b>at least 150 minutes a week of moderate aerobic activity over 5 days</b>, <b>no more than 2 days in a row without it</b>, and <b>resistance exercise twice a week</b>. <b>5–10 minute warm-up and cool-down</b>.","bullets":["↑ <b>insulin sensitivity</b>, ↓ BP, ↑ HDL","<b>150 min/week over 5 days</b>, <b>≤ 2 days off in a row</b>, <b>resistance 2×/week</b>","<b>5–10 min warm-up + cool-down</b>"],"why":"Ketones in the urine mean the cells are already starved of insulin — exercise would only add more stress hormones and push glucose and ketones higher, toward DKA. Without ketones, the same exercise works like extra insulin, which is why the danger flips to hypoglycemia for up to a day afterward. The ketone check is what tells you which way exercise will push."}]},{"k":"ta","gist":"Check glucose <b>no more than 30 minutes before meals</b>; give <b>rapid-acting insulin within 10 minutes of eating</b> (regular 20–30 minutes before); inject <b>subcutaneously</b>, rotating <b>within one area</b>; teach meter use, injection, <b>hypoglycemia treatment</b> and <b>sick-day rules</b> with <b>teach-back</b>.","terms":[],"cards":[{"t":"Site and absorption","tag":"","topic":"56-insulin-types-timing-injection-and-stora","text":"<b>abdomen absorbs fastest</b> and is preferred — <b>except within 2 inches of the navel</b>; other usual areas are the upper arms, thighs and buttocks (Fig. 56.7). <b>Rotate within one area</b> (not area to area) so absorption is steady day to day; rotating lets each spot <b>heal completely</b> before it is used again. Longer-acting and larger doses absorb less predictably. <b>Heat, massage and exercising the injected limb speed absorption</b>; <b>scar tissue slows it</b> (and hurts less, which tempts reuse).","bullets":["<b>Abdomen fastest</b>, preferred — <b>not within 2 in of navel</b>","Also upper arms, thighs, buttocks (Fig. 56.7)","<b>Rotate within one area</b> (each spot heals before reuse)","<b>Heat, massage, exercise ↑ absorption</b>; <b>scars ↓</b>"],"why":""},{"t":"Depth and angle","tag":"","topic":"56-insulin-types-timing-injection-and-stora","text":"<b>subcutaneous</b> — IM is faster and not used routinely. Lightly pinch and inject at <b>90°</b>; <b>45° for very thin or frail older adults</b>. <b>No aspiration.</b> Overweight patients can use <b>4–5 mm needles at 90° without pinching</b>. Insulin syringe needles come in <b>28, 29, 30 and 31 gauge</b> and <b>6, 8 and 12.7 mm</b> lengths.","bullets":["<b>Subcut</b>, not IM","<b>90°</b> with light pinch; <b>45° if very thin/frail</b>","<b>Don't aspirate</b> · 4–5 mm needle at 90° without pinch if overweight","Syringe needles: <b>28–31 gauge</b>, <b>6, 8 or 12.7 mm</b> long"],"why":""},{"t":"Lag time before meals","tag":"","topic":"56-insulin-types-timing-injection-and-stora","text":"<b>rapid-acting</b>: within <b>10 minutes before</b> eating when glucose is in range — or just before, or even right after the meal. <b>Regular</b>: <b>20–30 minutes before</b> eating. Glucose <b>high</b> → lengthen the lag; glucose <b>low</b> → inject right before eating (delay rapid-acting until after the meal).","bullets":["<b>Rapid</b>: <b>≤ 10 min before</b> (up to right after) the meal","<b>Regular</b>: <b>20–30 min before</b>","High glucose → longer lag · low glucose → inject at/after the meal"],"why":""},{"t":"Inspect before every dose","tag":"","topic":"56-insulin-types-timing-injection-and-stora","text":"look for <b>clumping, frosting, precipitate, or change in clarity or color</b> = lost potency → use another vial or pen. <b>NPH is uniformly cloudy after gentle rolling; every other insulin should be clear.</b> Needles and syringes are <b>single use</b>.","bullets":["Clumping, frosting, particles, color change → <b>discard</b>","<b>NPH = evenly cloudy</b> after rolling; <b>all others clear</b>","Needles <b>single use</b>"],"why":"Insulin types differ only in how fast they get from the injection site into the blood, so everything that changes blood flow at the site — heat, massage, exercise, scar tissue — changes the dose the patient actually receives. That is why rotation stays within one area, why the abdomen is preferred (steady blood flow), and why a hot shower after an injection can cause an unexpected low."},{"t":"Blood glucose monitoring (BGM)","tag":"","topic":"56-diagnosing-and-monitoring-glucose-a1c-cg","text":"a meter and capillary blood. Targets: <b>before meals 80–130</b>, <b>peak after meals &lt; 180</b>. Test more often with symptoms, <b>hypoglycemic unawareness</b>, illness, around <b>exercise</b>, gastroparesis, drug changes, steroids, pregnancy. Insulin users on multiple doses or a pump: <b>3 or more times a day</b>; fewer injections, non-insulin drugs or no drugs: a <b>daily</b> check helps judge therapy.","bullets":["Targets: <b>before meals 80–130</b>, <b>after meals &lt; 180</b>","More often: symptoms, <b>unawareness</b>, illness, <b>exercise</b>, gastroparesis, drug changes, steroids","Multiple injections/pump: <b>≥ 3×/day</b> · others: <b>daily</b>"],"why":""},{"t":"Survival skills","tag":"","topic":"56-teaching-self-management","text":"simple pathophysiology; <b>how to take insulin or the drug</b>; <b>recognize, treat and prevent hypo- and hyperglycemia</b>; basic diet (<b>meals at consistent times</b> and in step with the insulin, consistent carbohydrate amounts, and the fast carbohydrate that treats a low); <b>glucose and ketone monitoring</b>; <b>sick-day rules</b>; where to buy and <b>how to store</b> supplies; <b>when to call</b> the provider.","bullets":["Simple patho · <b>taking the drug</b> · <b>highs + lows</b>","Basic diet: <b>regular meal times + consistent carbs</b>, fast carbs for lows · <b>glucose + ketones</b> · <b>sick days</b>","Supplies + <b>storage</b> · <b>when to call</b>"],"why":"Diabetes is managed by the patient roughly 99% of the time — every meal, every dose, every walk is a decision made at home. Teaching is therefore not a discharge task but the main treatment, and the most important thing to check is not what the patient heard but what they can <b>do</b>: draw up the dose, read the meter, treat a low."},{"t":"How to teach","tag":"","topic":"56-teaching-self-management","text":"written or picture handouts, step-by-step discussion, <b>hands-on</b> practice, and <b>teach-back</b>. In acute illness teach only <b>survival skills</b>; save detail for follow-up. Break skills into <b>small achievable tasks</b> (first just drawing up an accurate dose) to build <b>self-efficacy</b> — mastering injection reduces fear.","bullets":["Handouts + steps + <b>hands-on</b> + <b>teach-back</b>","Acutely ill → <b>survival skills only</b>","<b>Small tasks → self-efficacy</b>"],"why":""}]},{"k":"eo","gist":"Glucose in target (<b>before meals 80–130</b>, <b>after meals &lt; 180</b>) and A1C falling toward goal <b>without hypoglycemia</b>; the client <b>demonstrates</b> drawing up and injecting a dose and using the meter, and can state the signs of highs and lows and when to call.","terms":[],"cards":[{"t":"Using the results","tag":"","topic":"56-diagnosing-and-monitoring-glucose-a1c-cg","text":"after-meal checks show the effect of a meal; checks around exercise show how to exercise safely. If readings are <b>out of range for 3 days</b> with no change in food, drugs or activity, make the agreed adjustment.","bullets":["After meals → meal effect · around exercise → safety","<b>Out of range 3 days</b> with no change → adjust per plan"],"why":""},{"t":"Ready for home (Box 56.15)","tag":"","topic":"56-teaching-self-management","text":"the patient (or significant other) can tell <b>why</b> the drug is prescribed, <b>name, dose and frequency</b>, how meals relate to its action, the diet plan; <b>prepare and inject insulin accurately</b>; test glucose and <b>urine ketones</b> (and when); <b>store insulin</b>; list <b>hypoglycemia symptoms</b> and the <b>carbs that treat them</b>; list <b>hyperglycemia symptoms</b>; what to eat and drink when <b>ill</b> (<b>8–12 oz of sugar-free, caffeine-free fluid every hour</b>; if solids won't stay down, the meal's carbohydrate as liquids or soft foods, <b>at least 150 g a day</b>; regular meal times; never skip insulin); <b>when to call</b> (frequent lows, signs of highs); and <b>foot care</b>.","bullets":["States <b>why</b>, <b>name, dose, frequency</b>, meal timing","<b>Injects accurately</b>; tests <b>glucose + ketones</b>; <b>stores insulin</b>","Lists <b>low signs + treatment</b>, <b>high signs</b>, sick-day eating (<b>fluid hourly</b>, carbs as liquids, <b>≥ 150 g/day</b>), <b>when to call</b>, <b>foot care</b>"],"why":""}]}]},{"id":"hypoglycemia","ch":"56","sys":"Hormones & glucose","name":"Hypoglycemia","patient":"A client on insulin is shaky, sweaty and slow to answer an hour after a late lunch tray never came.","topics":["56-hypoglycemia-the-15-15-rule"],"report":["The client’s blood glucose is 48 mg/dL; diaphoretic, confused and unable to swallow safely.","Type 2 diabetes on insulin glargine and lispro; received lispro at noon and the lunch tray was delayed.","Severe (level 3) hypoglycemia — the client needs assistance and cannot take anything by mouth. I gave glucagon per protocol and positioned the client on the side; recheck due in 15 minutes.","Requesting an order for IV dextrose if it stays low, and a review of the insulin doses."],"guide":[{"key":"56:2","name":"Hypoglycemia, DKA & HHS"}],"nodes":[{"id":"dm-acute","name":"Lows, DKA & HHS"},{"id":"insulin","name":"Insulin, glucagon & glucose"}],"drugs":[{"id":"glucagon","name":"Glucagon"},{"id":"d50","name":"Dextrose 50% (D50)"}],"videos":[{"id":"OoiX6jx48L8","title":"The 15:15 rule (Dish on Diabetes)","see":"15 g of fast carbohydrate, recheck in 15 minutes, repeat until the glucose is back in range"},{"id":"ZUlx6F63gj0","title":"How to use glucagon (Mayo Clinic)","see":"The rescue for a person too low to swallow safely — what is in the kit and how it is given"},{"id":"NXd0uSeIV6c","title":"Diabetes complications: hypoglycemia, DKA, HHS (Level Up RN)","see":"How to tell the three apart — onset, labs, ketones — and treatment, including potassium"}],"steps":[{"k":"rc","gist":"Blood glucose <b>below 70 mg/dL</b> with <b>adrenergic (neurogenic) signs</b> — tremor, palpitations, anxiety, diaphoresis, hunger — progressing to <b>neuroglycopenic signs</b>: confusion, behavior change, seizures, loss of consciousness.","terms":[{"t":"Blood glucose below 70 mg/dL","see":"Fingerstick or lab glucose under 70; under 54 is clinically significant (level 2).","why":"Normally insulin release falls at about 83 mg/dL and glucagon and epinephrine rise at about 67 — the body’s defense. Insulin given by injection or a sulfonylurea keeps working regardless, so glucose keeps falling.","means":"Below 70 → treat. <b>Severe</b> (level 3) is defined by <b>needing another person’s help</b>, not by a number."},{"t":"Tremor, palpitations and anxiety (adrenergic)","see":"Shaky hands, pounding or fast heart, nervousness.","why":"Falling glucose triggers a <b>sympathetic surge</b>: <b>epinephrine</b> acts on beta receptors in the heart and muscle.","means":"The <b>early warning</b>. <b>Beta blockers</b> blunt these signs, so a client on one may show few of them."},{"t":"Diaphoresis, hunger and tingling (cholinergic)","see":"Sweating, sudden hunger, tingling around the mouth or fingers.","why":"Sweat glands are sympathetic but use <b>acetylcholine</b>, which is why sweating can persist even with a beta blocker; hunger and tingling are also cholinergic signals.","means":"Sweating with cool, clammy skin is a strong clue — the opposite of the warm, dry skin of hyperglycemia."},{"t":"Cool, clammy skin","see":"Pale, cool and moist skin.","why":"<b>Epinephrine constricts skin vessels</b> while the sweat glands are active.","means":"A <b>typical</b> sign of hypoglycemia, but a skin finding can’t confirm or rule out anything on its own — <b>check the glucose</b> and assess for other concerning findings."},{"t":"Confusion and behavior change (neuroglycopenia)","see":"Difficulty thinking, slurred speech, irritability, combativeness, unusual behavior.","why":"<b>Neurons depend on a continuous glucose supply</b> and store only minutes’ worth. When glucose falls, brain cells run out of energy and stop working normally.","means":"The client may no longer be able to treat themselves or <b>swallow safely</b>, which changes the route of treatment. Can be mistaken for intoxication or a stroke — <b>check the glucose</b>."},{"t":"Seizures and loss of consciousness","see":"Unresponsive or seizing.","why":"Severe brain <b>energy failure</b>; untreated, it can cause brain damage or death.","means":"<b>Severe hypoglycemia</b>: nothing by mouth; side-lying, protect the airway; <b>glucagon or IV dextrose</b> now and <b>get emergency help</b> (rapid response in the hospital, 911 at home)."},{"t":"Hypoglycemia unawareness","see":"Low glucose with few or no warning symptoms.","why":"After years of diabetes or frequent lows, the <b>counterregulatory epinephrine response weakens</b>, so the early warning signs no longer appear.","means":"These clients check glucose more often. Meter checks use the <b>fingertip, not alternate sites</b> (forearm, thigh), which lag behind; <b>CGM with low alerts</b> is recommended for people at high risk of hypoglycemia. Older adults are at higher risk."}],"cards":[{"t":"Symptoms (Box 56.10)","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"<b>neurogenic (the early warning)</b> — adrenergic: <b>shaky, pounding heart, nervous</b>; cholinergic: <b>sweaty, hungry, tingling</b>. <b>Neuroglycopenic (the brain running out)</b>: weakness, fatigue, <b>difficulty thinking, confusion, behavior change</b>, emotional instability, <b>seizures, loss of consciousness</b>, brain damage, death. Skin is typically <b>cool and clammy</b>, and ketones are usually negative — but skin findings can’t confirm or rule out a low or another emergency: <b>check the glucose</b> and assess the whole picture.","bullets":["<b>Early (neurogenic)</b>: <b>shaky, pounding heart, anxious, sweaty, hungry, tingling</b>","<b>Late (brain)</b>: <b>confusion</b>, behavior change, <b>seizures, unconsciousness</b>, death","Typically <b>cool, clammy</b> skin, ketones usually negative → <b>confirm with a glucose check</b>"],"why":""},{"t":"Older adults","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"slower kidney clearance of sulfonylureas and insulin, <b>weaker epinephrine and glucagon responses</b>, frequent unawareness. Family checks glucose for unsteadiness, light-headedness, poor concentration, trembling or sweating; <b>bedtime snack</b> if appetite is poor.","bullets":["↓ clearance + ↓ counter-hormones + unawareness","Family checks glucose for unsteadiness, trembling, sweating; <b>bedtime snack</b>"],"why":""}]},{"k":"ac","gist":"The <b>brain depends on a continuous glucose supply</b> and cannot store it, so hypoglycemia quickly causes neurologic dysfunction. Usual cause: <b>insulin or a sulfonylurea</b> not matched to food intake or activity.","terms":[],"cards":[{"t":"What happens","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"below <b>70 mg/dL</b> the body releases balancing hormones and fires the autonomic nervous system. Normally insulin falls at about <b>83</b> and glucagon and epinephrine switch on at about <b>67</b> — before symptoms. The <b>brain can't make glucose</b> and stores only minutes' worth, so low glucose quickly becomes a brain problem.","bullets":["<b>&lt; 70</b> → hormones + autonomic alarm","Normal defense: insulin ↓ at ~<b>83</b>, glucagon/epinephrine ↑ at ~<b>67</b>","<b>Brain can't make or store glucose</b> → fast brain injury"],"why":""},{"t":"Causes","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"too much insulin for the food and activity; insulin at the <b>wrong time</b> or the <b>wrong type</b>; <b>missed or delayed meals</b>; <b>gastroparesis</b>; <b>alcohol</b> (liver stops releasing glucose); <b>kidney failure</b> (insulin cleared slowly); <b>exercise</b>. At risk: everyone on <b>insulin or sulfonylureas</b> (alone or with metformin), especially older adults and those with liver or kidney impairment.","bullets":["Too much insulin, <b>wrong time/type</b>","<b>Missed/late meals</b>, <b>gastroparesis</b>, <b>alcohol</b>, <b>kidney failure</b>, <b>exercise</b>","At risk: <b>insulin + sulfonylureas</b>; older, liver/kidney disease"],"why":""}]},{"k":"ph","gist":"<b>Airway and route</b>: can the client swallow safely? Altered LOC, seizures or an unsafe swallow = <b>severe hypoglycemia</b> requiring assistance — a medical emergency.","terms":[],"cards":[{"t":"Severity and unawareness","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"<b>mild</b>: alert and able to self-treat. <b>Severe</b>: needs <b>another person's</b> help. Long-standing diabetes can bring <b>hypoglycemic unawareness</b> — no warning symptoms — so these patients check glucose more often, and meter checks use the <b>fingertip, not alternate sites</b> such as the forearm or thigh (<a href=\"https://www.fda.gov/medical-devices/in-vitro-diagnostics/blood-glucose-monitoring-devices\">FDA: blood glucose monitoring devices</a>). This is about where a meter sample comes from — <b>continuous glucose monitoring (CGM)</b> with low alerts is recommended for people at high risk of hypoglycemia (<a href=\"https://doi.org/10.2337/dc26-S006\">ADA 2026 Standards, section 6</a>). <b>Beta blockers mask</b> the warning signs.","bullets":["<b>Mild</b> = self-treats · <b>severe</b> = needs help","<b>Unawareness</b> → check more; meter checks at the <b>fingertip, not alternate sites</b>; <b>CGM</b> recommended","<b>Beta blockers mask</b> warnings"],"why":""}]},{"k":"gs","gist":"<b>Oral fast-acting carbohydrate</b> if alert with a safe swallow; <b>glucagon or IV dextrose</b> if not; then <b>complex carbohydrate + protein</b>, and identify the cause to prevent recurrence.","terms":[],"cards":[{"t":"The 15-15 rule","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"glucose <b>&lt; 70</b> or symptoms → <b>15 g of fast carbohydrate</b> (<b>30 g if &lt; 50</b>), liquid if they can swallow — <b>avoid high-potassium choices like orange juice</b> in the hospital. <b>Recheck in 15 minutes</b>; still low → <b>repeat</b>. Once above the low range → a <b>complex carbohydrate with protein</b> (crackers with nut butter) to prevent a repeat. <b>Chocolate and fatty sweets absorb slowly</b> — use glucose.","bullets":["<b>&lt; 70</b> → <b>15 g</b> fast carb (<b>30 g if &lt; 50</b>)","<b>Recheck 15 min</b> → repeat if still low","Then <b>complex carb + protein</b>","<b>No chocolate</b> (fat slows it); in hospital avoid <b>OJ</b> (potassium)"],"why":"Fast sugar works because glucose needs no digestion — it goes straight from the gut into the blood. Fat in chocolate slows stomach emptying and delays it, and complex carbohydrates have to be broken down first; that is exactly why they are used <b>after</b> the low is fixed, to keep glucose up while the fast sugar runs out."},{"t":"15 g examples (Box 56.11)","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"glucose tablets or gel · <b>½ cup (120 mL) juice or regular soda</b> · <b>5 hard candies</b> · <b>4 sugar cubes or 4 teaspoons sugar</b> · <b>1 tablespoon honey or syrup</b>. Symptoms can <b>persist after glucose is back to normal</b> — go by the 15-minute recheck, then a small complex-carbohydrate and protein snack.","bullets":["Glucose tabs/gel · <b>½ cup juice or regular soda</b> · <b>5 hard candies</b>","<b>4 tsp sugar</b> · <b>1 Tbsp honey/syrup</b>","Symptoms may <b>outlast the low</b> → go by the recheck"],"why":""}]},{"k":"ta","gist":"<b>Below 70 → 15 g</b> fast carbohydrate (<b>30 g below 50</b>), <b>recheck in 15 minutes</b>, repeat until resolved. Unable to swallow → <b>nothing by mouth</b>, side-lying, <b>glucagon</b> or <b>IV dextrose</b> per protocol, and <b>get emergency help right away</b>; any repeat glucagon dose follows the product label or protocol.","terms":[],"cards":[{"t":"In the hospital","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"check glucose <b>no more than 30 minutes before</b> a meal and give rapid-acting insulin <b>just before</b> the meal; coordinate trays and insulin. Monitor before antidiabetic drugs, before meals, at bedtime and with symptoms. Inpatient lows come from the <b>wrong insulin type</b>, insulin <b>not matched to the timing of food</b>, or a <b>changed eating plan without a dose change</b>; protocols give oral carbohydrate if the patient is alert and can swallow, otherwise <b>IV dextrose or glucagon</b>.","bullets":["Check <b>≤ 30 min before</b> meals; <b>rapid insulin just before</b> eating","Check before drugs, meals, bedtime, with symptoms","Inpatient causes: <b>wrong type</b>, <b>food-timing mismatch</b>, <b>diet change without dose change</b>"],"why":""},{"t":"Can't swallow — glucagon and dextrose","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"<b>glucagon</b> (the main balancing hormone) is first-line for severe lows. It can cause <b>vomiting → turn the patient on their side</b>. <b>Concentrated IV dextrose</b> (e.g., D50) is <b>hyperosmolar</b> — give carefully to avoid <b>extravasation</b> and tissue damage. Both wear off: check glucose <b>every 15 minutes until resolved</b>, then monitor for hours; target <b>70–110</b>. <b>Critical rescue</b>: glucagon → <b>emergency help / notify the provider immediately</b> → a repeat dose only as the protocol or product label directs. <i>The textbook gives a repeat in 10 minutes;</i> that interval is not universal — BAQSIMI’s label, for example, says 15 minutes (<a href=\"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=32ba41fa-4158-40af-8cb2-03693c248994\">BAQSIMI prescribing information</a>, sections 2.1–2.2).","bullets":["<b>Glucagon</b> first-line; <b>side-lying</b> (vomiting)","<b>IV dextrose</b> is hyperosmolar → <b>watch for extravasation</b>","Effects wear off → glucose <b>q15 min</b>, then for hours; target <b>70–110</b>"],"why":""},{"t":"Moderate and severe at home","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"<b>moderate</b> (cold clammy pale skin, rapid pulse, rapid shallow breathing, mood change, drowsiness; usually &lt; 50): <b>30 g</b> fast carbohydrate, glucagon may be needed, recheck in 15 minutes, repeat if &lt; 60, then a snack. <b>Severe</b> (can't swallow, confused, combative, unconscious, seizing): <b>nothing by mouth</b>, turn on the side, and the family gives <b>glucagon IM, subcut or nasal</b>. <i>The textbook describes a second dose in 10 minutes if still unconscious, then calling 911.</i> <b>Current product labels</b>: get <b>emergency help immediately after giving glucagon</b>, and give any repeat dose only as <b>that product’s</b> instructions say — for <b>BAQSIMI</b> nasal glucagon, after <b>15 minutes</b> with no response, from a <b>new device</b>, while waiting for help (<a href=\"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=32ba41fa-4158-40af-8cb2-03693c248994\">BAQSIMI prescribing information</a>, sections 2.1–2.2). Call the provider; a small meal once awake and not nauseated.","bullets":["<b>Moderate</b>: <b>30 g</b>, maybe glucagon, recheck 15 min","<b>Severe</b>: nothing by mouth, side-lying → <b>glucagon</b> (IM/subcut/nasal) → <b>call 911 right away</b>","Repeat dose per the <b>product label</b> (BAQSIMI: <b>15 min</b>, new device) — the book’s “10 min, then 911” is not universal","Small meal once awake and not nauseated"],"why":""}]},{"k":"eo","gist":"<b>Recheck every 15 minutes</b> until out of the low range, then <b>complex carbohydrate + protein</b>. Anticipate <b>recurrence</b> with sulfonylureas or long-acting insulin, and evaluate teaching of the 15-15 rule and glucagon.","terms":[],"cards":[{"t":"Prevention and teaching","tag":"","topic":"56-hypoglycemia-the-15-15-rule","text":"personal hypoglycemia plan; <b>teach the family the 15-15 rule and how to give glucagon</b>; <b>medical alert bracelet</b>; <b>always carry glucagon, a carb source and a meter</b>; regular meal timing (<b>a meal delayed more than 30 minutes</b> raises risk on some regimens); test <b>before driving</b>; exercise when insulin isn't peaking; alcohol only with food; call the provider if lows occur <b>more than twice a week</b>.","bullets":["Family learns <b>15-15 + glucagon</b>; <b>medical alert</b>","Always carry <b>glucagon, carbs, meter</b>","<b>Meal delayed &gt; 30 min</b> → risk","Test <b>before driving</b> · lows <b>&gt; 2×/week → call provider</b>"],"why":""}]}]},{"id":"dka","ch":"56","sys":"Hormones & glucose","name":"Diabetic ketoacidosis (DKA)","patient":"A 22-year-old with type 1 diabetes has had the flu for two days, skipped insulin because she wasn’t eating, and is now vomiting and breathing deeply.","topics":["56-dka-and-hhs-the-hyperglycemic-emergencie"],"report":["The client with type 1 diabetes has a glucose of 512 mg/dL, deep rapid respirations, fruity breath and vomiting; HR 124, BP 94/60, drowsy but oriented.","Two days of flu-like illness; skipped insulin because she was not eating.","Suspected DKA with hypovolemia; potassium and acid–base status not yet known.","Please evaluate now. I have started a large-bore IV; requesting a BMP with potassium, serum ketones and a blood gas, a fluid bolus order and the DKA insulin protocol."],"guide":[{"key":"56:2","name":"Hypoglycemia, DKA & HHS"}],"nodes":[{"id":"dm-acute","name":"Lows, DKA & HHS"},{"id":"k-acidbase","name":"Potassium & acid–base"},{"id":"fluids","name":"Water follows solute"},{"id":"insulin","name":"Insulin, glucagon & glucose"}],"drugs":[{"id":"regular","name":"Regular insulin"}],"videos":[{"id":"NXd0uSeIV6c","title":"Diabetes complications: hypoglycemia, DKA, HHS (Level Up RN)","see":"How to tell the three apart — onset, labs, ketones — and treatment, including potassium"},{"id":"r2tXTjb7EqU","title":"Diabetic ketoacidosis pathophysiology (Alila Medical Media)","see":"No insulin → fat burned → ketoacids and osmotic diuresis → acidosis and dehydration"},{"id":"L-osEc07vMs","title":"Osmosis and water potential (Amoeba Sisters)","see":"Water moving toward the side with more dissolved particles — the rule behind dumping, osmotic diarrhea and HHS"}],"steps":[{"k":"rc","gist":"<b>Polyuria, polydipsia</b>, <b>nausea, vomiting and abdominal pain</b>, <b>fruity breath</b>, <b>Kussmaul respirations</b>, and signs of <b>hypovolemia</b> — tachycardia, weak pulse, poor skin turgor, dry mucous membranes, postural hypotension — with mental status from alert to coma. <b>Sudden</b> onset, often with illness.","terms":[{"t":"Kussmaul respirations","see":"Deep, rapid, labored breathing.","why":"Ketoacids lower the blood pH (<b>metabolic acidosis</b>). The respiratory center responds by <b>blowing off CO₂</b>, which is an acid in the blood, to push the pH back up — <b>respiratory compensation</b>.","means":"A sign of <b>significant acidosis</b>. Breathing will slow as the acidosis is corrected; confusion with Kussmaul breathing means <b>shock and coma can follow quickly</b>."},{"t":"Fruity (acetone) breath","see":"A sweet, fruity odor on the breath.","why":"<b>Acetone</b>, one of the ketone bodies, is volatile and is exhaled through the lungs.","means":"Tells you <b>ketones</b> are high — check serum ketones."},{"t":"Polyuria leading to dehydration","see":"Large urine output early, then <b>oliguria</b> as volume runs out; thirst.","why":"Very high glucose spills into the urine and pulls water and electrolytes with it (<b>osmotic diuresis</b>). Vomiting adds to the losses.","means":"The fluid deficit can be several liters — the reason <b>fluids come first</b> in treatment."},{"t":"Hypovolemia: tachycardia, weak pulse, postural hypotension, flat neck veins","see":"Fast thready pulse, dizzy when sitting up, sunken eyes, poor turgor, dry mucous membranes.","why":"Osmotic diuresis and vomiting <b>shrink the circulating volume</b>; the heart speeds up to maintain output.","means":"Risk for <b>hypovolemic shock</b> — monitor BP, pulse and respirations every 15 minutes until stable, and hourly urine output."},{"t":"Nausea, vomiting and abdominal pain","see":"Diffuse abdominal pain, sometimes severe enough to look like a surgical abdomen.","why":"Associated with the <b>ketoacidosis</b> itself, along with dehydration and electrolyte shifts; it usually resolves as the acidosis is corrected.","means":"Vomiting <b>worsens dehydration and potassium loss</b> and prevents oral intake — the reason sick-day rules say to call the provider for persistent vomiting."},{"t":"Altered mental status","see":"Drowsy, confused, progressing to coma.","why":"<b>Acidosis, hyperosmolality and reduced brain perfusion</b> from dehydration impair brain function.","means":"Protect the <b>airway</b>; a worsening level of consciousness is an emergency. Also watch for new headache or confusion during treatment — <b>cerebral edema</b>."}],"cards":[{"t":"What you see","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"<b>polyuria, polydipsia, polyphagia</b>, <b>fruity breath</b>, <b>vomiting, abdominal pain</b>, weakness; dehydration — weight loss, dry skin, <b>sunken soft eyeballs</b>, poor turgor, oliguria with high specific gravity, weak rapid pulse, <b>flat neck veins</b>, postural hypotension. <b>Kussmaul respirations</b>; mental status from alert to coma. <b>Confusion or Kussmaul breathing → shock and coma can come quickly.</b>","bullets":["<b>3 Ps</b>, <b>fruity breath</b>, <b>vomiting, abdominal pain</b>","Dehydration: <b>sunken eyes</b>, poor turgor, flat neck veins, weak fast pulse, orthostasis","<b>Kussmaul</b>; alert → coma","Confusion/Kussmaul → <b>shock + coma soon</b>"],"why":""}]},{"k":"ac","gist":"<b>Insulin deficiency</b> plus stress hormones → <b>hyperglycemia</b> (cells can’t take up glucose; the liver keeps releasing it), <b>ketoacidosis</b> (fat broken down into ketoacids — current criteria: ketones with <b>pH &lt; 7.3 and/or bicarbonate &lt; 18</b>) and <b>osmotic diuresis</b>. Most common trigger: <b>infection or illness</b>, or <b>missed insulin</b>.","terms":[{"t":"Ketones and metabolic acidosis","see":"Ketones positive with <b>pH &lt; 7.3 and/or bicarbonate &lt; 18</b> (current adult criteria); the textbook’s examples are pH &lt; 7.35 and bicarbonate &lt; 15. Wide anion gap.","why":"Without insulin, fat cells release fatty acids, and the <b>liver converts them into ketone bodies</b>, which are acids. They use up the blood’s <b>bicarbonate</b> buffer faster than the body can replace it, so the pH falls.","means":"Treatment continues until the <b>ketoacidosis resolves</b> (ketones <b>&lt; 0.6 mmol/L AND</b> either <b>pH ≥ 7.3 OR bicarbonate ≥ 18</b>), <b>not just until glucose improves</b>."},{"t":"Hyperglycemia","see":"Often &gt; 300 mg/dL — but DKA can occur at <b>lower glucose</b>, especially with SGLT2 inhibitors (euglycemic DKA).","why":"No insulin means cells cannot take up glucose, while <b>glucagon, cortisol and epinephrine</b> make the liver keep producing it.","means":"A glucose below 300 does <b>not</b> rule out DKA — the ketones and acidosis define it."},{"t":"Potassium: high or normal at first, but depleted","see":"Serum K⁺ may read high on admission.","why":"Acidosis and lack of insulin <b>shift potassium out of the cells</b> into the blood, while osmotic diuresis and vomiting <b>lose it in the urine</b>. So the serum level hides a large <b>total-body deficit</b>. Insulin drives potassium <b>back into the cells</b>, so the serum level can <b>fall fast</b> once treatment starts.","means":"<b>Check K⁺ before insulin.</b> If K⁺ is <b>&lt; 3.5</b>, replace it and <b>delay insulin until it is above 3.5</b> (current adult consensus). Continuous cardiac monitoring — low K⁺ causes dysrhythmias."},{"t":"Elevated BUN and creatinine","see":"BUN &gt; 30, creatinine &gt; 1.5.","why":"Dehydration reduces blood flow to the kidneys (<b>prerenal</b> injury).","means":"Should improve with fluids; monitor urine output hourly before and during potassium replacement."},{"t":"Triggers","see":"Infection, illness, missed or reduced insulin, insulin pump failure, new type 1 diabetes.","why":"Illness releases <b>stress hormones</b> that raise glucose and insulin needs; skipping insulin “because I’m not eating” removes the only brake on ketone production.","means":"Find and treat the cause (cultures, history). Teach <b>never to stop basal insulin when ill</b>."}],"cards":[{"t":"What it is","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"<b>uncontrolled hyperglycemia + metabolic acidosis + ketones</b>, from <b>insulin deficiency</b> plus burning fat and protein for fuel and a surge of stress hormones. <b>Most common trigger: infection or illness.</b> Onset is <b>sudden</b>.","bullets":["<b>Hyperglycemia + acidosis + ketones</b>","No insulin + fat/protein burned + stress hormones","Trigger: <b>infection/illness</b> · <b>sudden</b> onset"],"why":""},{"t":"Textbook examples (Table 56.9 — see update)","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"glucose <b>&gt; 300</b>; serum ketones <b>positive</b>; <b>pH &lt; 7.35</b>; <b>HCO₃⁻ &lt; 15</b>; sodium low, normal or high; <b>BUN &gt; 30 and creatinine &gt; 1.5</b> from dehydration; urine ketones positive; potassium may start <b>high</b> (shift) despite total-body loss.","bullets":["Glucose <b>&gt; 300</b>, <b>ketones +</b>, <b>pH &lt; 7.35</b>, <b>HCO₃⁻ &lt; 15</b>","BUN <b>&gt; 30</b>, creatinine <b>&gt; 1.5</b> (dehydration)","K⁺ may start <b>high</b> despite depletion"],"why":""},{"t":"Current diagnostic distinction","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"The textbook table describes typical values. Current adult consensus requires diabetes/history or glucose ≥ 200 mg/dL <b>plus ketones and metabolic acidosis</b>; DKA can also occur with lower glucose (including SGLT2-associated cases). A glucose below the book’s &gt; 300 example does not rule it out. <a href=\"https://link.springer.com/article/10.1007/s00125-024-06183-8\">2024 adult consensus</a>, Diagnostic criteria for DKA.","bullets":["Book numbers are <b>examples</b>, not rule-out thresholds","<b>Diabetes/hyperglycemia + ketones + acidosis</b>","<b>Euglycemic DKA exists</b>, especially with SGLT2 drugs"],"why":""}]},{"k":"ph","gist":"1. <b>Fluid volume deficit</b> and risk of <b>hypovolemic shock</b>. 2. <b>Acidosis</b> and <b>electrolyte imbalance</b> — especially <b>potassium</b>, which falls fast once insulin starts. 3. Altered LOC and airway risk. During treatment: <b>hypoglycemia</b> and <b>cerebral edema</b>.","terms":[],"cards":[{"t":"Monitoring","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"first: <b>airway, LOC, hydration, electrolytes, glucose</b>. <b>BP, pulse and respirations every 15 minutes until stable</b>; <b>urine output, temperature and mental status hourly</b>; CVP every 30 minutes if present; then vital signs every 4 hours once stable. Glucose results decide when to switch from saline to dextrose.","bullets":["<b>Airway, LOC, hydration, lytes, glucose</b> first","VS <b>q15 min until stable</b> · <b>UO, temp, mental status hourly</b>","Then VS q4h"],"why":""}]},{"k":"gs","gist":"<b>Restore volume first</b> with IV fluids, then correct ketoacidosis with <b>IV insulin per protocol once K⁺ is known and ≥ 3.5</b>, <b>replace potassium</b>, add <b>dextrose</b> when glucose reaches 250 while insulin continues, and <b>treat the trigger</b>.","terms":[],"cards":[{"t":"Fluids","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"<b>first goal: restore blood volume</b> — about <b>15–20 mL/kg in the first hour</b>. Then <b>hypotonic</b> fluid at 4–14 mL/kg/hr. <b>When glucose reaches 250 → D5 in 0.45% saline</b>, to prevent <b>hypoglycemia</b> and <b>cerebral edema</b> from osmolarity falling too fast. Up to <b>6–10 L in 24 hours</b>; watch for <b>fluid overload</b> (heart failure, pulmonary edema) via BP, I&amp;O and daily weight.","bullets":["<b>15–20 mL/kg</b> first hour → then hypotonic 4–14 mL/kg/hr","<b>Glucose 250 → D5½NS</b> (prevents lows + <b>cerebral edema</b>)","Up to <b>6–10 L/24 h</b>; watch <b>overload</b>"],"why":""},{"t":"Insulin","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"Use the <b>ordered DKA protocol</b> after reviewing potassium and starting appropriate fluid resuscitation. IV regular insulin is standard for severe/complicated DKA; selected mild cases may use a supervised subcutaneous protocol. Continue insulin until ketoacidosis resolves, not merely until glucose improves; dextrose may be needed while insulin continues. Overlap prescribed basal insulin during transition. <b>Current resolution:</b> plasma ketones <b>&lt; 0.6 mmol/L</b> plus venous <b>pH ≥ 7.3 OR bicarbonate ≥ 18 mmol/L</b>; glucose ideally &lt; 200 mg/dL. Do not use anion-gap closure or urine ketones alone to end treatment. <a href=\"https://link.springer.com/article/10.1007/s00125-024-06183-8\">2024 adult consensus</a>, Insulin; Criteria for resolution.","bullets":["Use <b>ordered protocol</b>; review <b>K⁺ before insulin</b>","Normalizing glucose alone does <b>not</b> resolve ketoacidosis","Ketones <b>&lt; 0.6</b> + <b>pH ≥ 7.3 OR HCO₃⁻ ≥ 18</b>","Overlap prescribed basal insulin during transition"],"why":""}]},{"k":"ta","gist":"IV access; isotonic saline about <b>15–20 mL/kg in the first hour</b>; <b>check K⁺ before insulin</b> — replace if &lt; 3.5 and hold insulin until it is above 3.5; <b>IV regular insulin</b> per protocol; switch to <b>D5½NS at glucose 250</b>; VS <b>every 15 minutes</b> until stable; <b>hourly</b> urine output, mental status and glucose; continuous cardiac monitoring.","terms":[],"cards":[{"t":"Potassium and bicarbonate","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"Total-body potassium is depleted even when the initial serum value is high. <b>Current adult consensus:</b> if K⁺ is <b>&lt; 3.5 mmol/L</b>, replace potassium and <b>delay insulin until K⁺ &gt; 3.5 mmol/L</b>. Continue prescribed electrolyte/ECG monitoring and consider renal function and urine output before replacement. Insulin and correction of the metabolic disturbance can lower serum K⁺ rapidly. Bicarbonate is not routine; the current consensus considers it for severe acidosis (pH &lt; 7.0), per orders. <a href=\"https://link.springer.com/article/10.1007/s00125-024-06183-8\">2024 adult consensus</a>, Potassium; Bicarbonate.","bullets":["<b>Check K⁺ before insulin</b>","K⁺ <b>&lt; 3.5 → replace; delay insulin until &gt; 3.5</b>","Monitor <b>ECG, electrolytes, renal function/UO</b>","<b>No routine bicarbonate</b>; severe-acidosis orders only"],"why":""}]},{"k":"eo","gist":"Ketoacidosis <b>resolved</b>: ketones <b>&lt; 0.6 mmol/L AND</b> either <b>pH ≥ 7.3 OR HCO₃⁻ ≥ 18</b> (glucose ideally &lt; 200); K⁺ in range; <b>adequate urine output</b> and stable BP; mental status at baseline; basal insulin overlapped before the drip stops; the client can state <b>sick-day rules</b> and when to call.","terms":[],"cards":[{"t":"Sick-day rules","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"<b>tell the provider you are ill</b>; check glucose <b>every 2–4 hours</b>; <b>test for ketones even if glucose is in range</b>, especially when vomiting; <b>do not stop essential basal insulin</b>; follow the prescribed sick-day adjustments. Other diabetes medicines may need temporary interruption during dehydration, vomiting or fasting: obtain the drug-specific plan rather than continuing every drug automatically; <b>8–12 oz (240–360 mL) of sugar-free, caffeine-free fluid every hour awake</b> (sugar-containing fluids if glucose is below target); keep regular meal times; if solids won't stay down, replace the meal's carbohydrate with easier foods or liquids (<b>at least 150 g of carbohydrate a day</b> prevents starvation ketosis); rest.","bullets":["Tell the provider · glucose <b>q2–4h</b> · <b>ketones even if glucose OK</b>","<b>Continue essential basal insulin</b>; other drugs need an <b>individual sick-day plan</b>","<b>8–12 oz sugar-free, caffeine-free fluid every hour</b> awake","Can't eat → carb-containing liquids, <b>≥ 150 g carb/day</b>"],"why":"Both emergencies are dehydration emergencies first, which is why <b>fluids come before insulin</b>: insulin pulls glucose — and water with it — into the cells, and given to a patient with an empty circulation it can collapse the blood pressure. DKA involves enough absolute or relative insulin deficiency to allow ketoacids to accumulate. In HHS, residual insulin usually limits ketogenesis while hyperglycemia and dehydration progress. They can overlap; neither condition is classified from diabetes type alone."},{"t":"When to call","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"<b>persistent nausea and vomiting</b>; can't keep food or fluids down; <b>moderate or large ketones</b>; glucose <b>&gt; 250 not responding</b> or still high after <b>two supplemental insulin doses</b>; persistent hypoglycemia; temperature <b>101.5°F (38.6°C)</b> or rising, or fever <b>&gt; 24 hours</b>; illness <b>longer than 1–2 days</b>.","bullets":["<b>Vomiting won't stop</b>, can't keep fluids down","<b>Moderate/large ketones</b> · glucose <b>&gt; 250</b> not responding or after <b>2 extra doses</b>","Fever <b>≥ 101.5°F</b> or &gt; 24 h · ill <b>&gt; 1–2 days</b>"],"why":""},{"t":"DKA teaching","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"check glucose <b>every 2 hours</b> while anorexia, nausea or vomiting continue or glucose stays <b>&gt; 250</b>; check <b>ketones when glucose &gt; 250</b>; drink at least <b>2 L a day</b>, more with infection; with nausea, sip liquids with <b>glucose and electrolytes</b> (regular soda, diluted juice, sports drinks); take extra rapid or regular insulin as the provider directs.","bullets":["Glucose <b>q2h</b> while sick or <b>&gt; 250</b> · <b>ketones &gt; 250</b>","<b>≥ 2 L/day</b>; nausea → <b>regular soda, diluted juice, sports drinks</b>"],"why":""}]}]},{"id":"hhs","ch":"56","sys":"Hormones & glucose","name":"Hyperglycemic-hyperosmolar state (HHS)","patient":"A 78-year-old with type 2 diabetes from a nursing home has been drinking little for days with a UTI and is now confused and very drowsy.","topics":["56-dka-and-hhs-the-hyperglycemic-emergencie"],"report":["The 78-year-old client is newly confused and very drowsy; lab glucose 840 mg/dL, dry mucous membranes, HR 112, BP 98/56, urine output 15 mL/hr. No Kussmaul breathing.","Type 2 diabetes on metformin; UTI symptoms for 4 days with poor oral intake.","Suspected HHS with severe dehydration, possibly triggered by infection.","Please evaluate now. Requesting serum osmolality, a BMP, ketones, a urinalysis and culture, and IV fluid orders; I am doing hourly neuro checks."],"guide":[{"key":"56:2","name":"Hypoglycemia, DKA & HHS"}],"nodes":[{"id":"dm-acute","name":"Lows, DKA & HHS"},{"id":"fluids","name":"Water follows solute"}],"drugs":[{"id":"regular","name":"Regular insulin"}],"videos":[{"id":"NXd0uSeIV6c","title":"Diabetes complications: hypoglycemia, DKA, HHS (Level Up RN)","see":"How to tell the three apart — onset, labs, ketones — and treatment, including potassium"},{"id":"r2tXTjb7EqU","title":"Diabetic ketoacidosis pathophysiology (Alila Medical Media)","see":"No insulin → fat burned → ketoacids and osmotic diuresis → acidosis and dehydration"},{"id":"L-osEc07vMs","title":"Osmosis and water potential (Amoeba Sisters)","see":"Water moving toward the side with more dissolved particles — the rule behind dumping, osmotic diarrhea and HHS"}],"steps":[{"k":"rc","gist":"<b>Profound dehydration</b> that develops <b>gradually over days</b>, glucose often <b>&gt; 600</b>, and <b>neurologic changes</b> — confusion, lethargy, seizures, focal deficits, coma — <b>without Kussmaul breathing or fruity breath</b>. Usually an <b>older adult</b> with type 2 diabetes and an illness.","terms":[{"t":"Severe dehydration","see":"Dry mucous membranes, poor turgor, tachycardia, hypotension, low urine output; often larger fluid losses than DKA.","why":"Days of <b>osmotic diuresis</b> from very high glucose. Older adults have a <b>blunted thirst</b> response and may be unable to get fluids, so they cannot keep up with the losses.","means":"<b>Fluids are the main treatment.</b> Assess every older adult for dehydration, diabetic or not."},{"t":"Confusion, seizures and focal deficits","see":"Lethargy to coma, seizures, temporary one-sided weakness that can look like a stroke.","why":"Very high glucose makes the blood <b>hyperosmolar</b>, which <b>pulls water out of brain cells</b> (cellular dehydration). Coma is likely once osmolarity exceeds <b>350 mOsm/L</b> (normal 270–300).","means":"Hourly <b>neuro checks</b> (LOC, pupils). Report changes immediately. Brain recovery <b>lags hours behind</b> normal glucose."},{"t":"Extremely high glucose (often &gt; 600)","see":"The meter may read “HI”; confirm with a lab glucose.","why":"Without the vomiting and Kussmaul breathing of DKA, there is no early alarm, so glucose climbs for days. As dehydration lowers kidney blood flow, the kidneys <b>excrete less glucose</b>, so it rises even higher.","means":"Lower glucose <b>gradually</b> (about 50–70 mg/dL per hour) — a fast drop shifts water into brain cells."},{"t":"No Kussmaul breathing or fruity breath","see":"Normal breathing pattern; ketones absent or mild.","why":"<b>Some insulin is still being made</b> — not enough to control glucose, but enough to <b>limit fat breakdown and ketone production</b>.","means":"Separates HHS from DKA — but mixed DKA/HHS presentations occur, so check ketones and pH."}],"cards":[{"t":"Why older adults","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"blunted <b>thirst</b>, poor <b>urine concentration</b> and <b>diuretics</b> → assess <b>all</b> older adults for dehydration, diabetic or not. Triggers: <b>infection</b>, poor fluid intake, <b>MI, sepsis, pancreatitis, stroke</b>, and drugs — <b>glucocorticoids, diuretics, phenytoin, beta blockers, calcium channel blockers</b>.","bullets":["↓ <b>thirst</b>, ↓ concentrating, <b>diuretics</b>","Triggers: <b>infection</b>, low intake, MI, sepsis, pancreatitis, stroke","Drugs: <b>steroids, diuretics, phenytoin, beta blockers, CCBs</b>"],"why":""},{"t":"The brain","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"confusion to coma, <b>seizures</b>, reversible paralysis; <b>coma once osmolarity &gt; 350</b> (normal <b>270–300 mOsm/L</b>). Brain recovery lags hours behind normal glucose.","bullets":["Confusion → coma, <b>seizures</b>, paralysis","<b>Coma &gt; 350 mOsm/L</b> (normal <b>270–300</b>)"],"why":""}]},{"k":"ac","gist":"<b>Residual insulin</b> prevents significant ketosis while <b>hyperglycemia, hyperosmolality</b> (often &gt; 320 mOsm/L) and dehydration progress. Triggers: <b>infection</b>, poor fluid intake, <b>MI, stroke, sepsis</b>, and drugs such as <b>glucocorticoids and diuretics</b>.","terms":[{"t":"Serum osmolality elevated","see":"Often &gt; 320 mOsm/L (normal 270–300); &gt; 350 → coma risk.","why":"Osmolality measures the <b>particles dissolved</b> in the blood. Glucose and sodium are concentrated in a <b>shrinking volume of water</b>.","means":"The level tracks with the mental status. It should fall <b>slowly</b> — if it falls too fast, water rushes into brain cells and causes <b>cerebral edema</b>."},{"t":"Triggers in older adults","see":"Infection (UTI, pneumonia), MI, stroke, glucocorticoids, diuretics.","why":"Illness raises <b>stress hormones</b> and glucose; diuretics and poor intake add to the dehydration.","means":"Look for and treat the cause — cultures, ECG, medication review."}],"cards":[{"t":"What it is","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"Severe hyperglycemia, hyperosmolality and dehydration <b>without significant ketoacidosis</b>. Residual insulin limits ketogenesis; <b>mild ketones and mixed DKA/HHS presentations can occur</b>. It often evolves gradually in older adults with type 2, but neither age nor diabetes type excludes either crisis. Table 56.9 gives older example values, not universal current diagnostic criteria. <a href=\"https://link.springer.com/article/10.1007/s00125-024-06183-8\">2024 adult consensus</a>, Diagnostic criteria for HHS.","bullets":["<b>Severe dehydration + hyperosmolality</b>","Without <b>significant</b> ketoacidosis; <b>overlap can occur</b>","Often gradual/type 2; not limited to that group"],"why":""}]},{"k":"ph","gist":"1. <b>Severe fluid volume deficit</b> and risk of shock. 2. <b>Neurologic compromise</b> from hyperosmolality — airway, seizures, falls. 3. During treatment: <b>cerebral edema</b> if osmolality falls too fast, and <b>hypokalemia</b> once insulin starts.","terms":[],"cards":[]},{"k":"gs","gist":"Rehydrate <b>gradually over 36–72 hours</b>, start <b>insulin only after adequate fluids</b>, lower glucose by about <b>50–70 mg/dL per hour</b>, watch the brain hourly, and <b>treat the trigger</b>.","terms":[],"cards":[{"t":"Fluids first","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"goal: rehydrate and normalize glucose over <b>36–72 hours</b>. <b>Current adult consensus</b>: start with <b>isotonic saline or a balanced crystalloid</b>, then adjust the fluid to the clinical status and laboratory trends; <b>half-normal saline</b> is reserved for specific situations, such as serum osmolality <b>not falling despite adequate fluids</b> (<a href=\"https://link.springer.com/article/10.1007/s00125-024-06183-8\">2024 adult consensus</a>). <i>The textbook gives normal saline in shock or severe hypotension, otherwise half-normal saline, at 1 L/hr until CVP rises or BP and urine output are adequate, then 100–200 mL/hr, with half the deficit replaced in the first 12 hours.</i> Check for <b>cerebral edema hourly</b> (abrupt mental change, abnormal neuro signs, coma). <b>No improvement, or deterioration at any point → reassess and report</b> (fluid status, osmolality, glucose, sodium and other causes); the book links worsening after improvement to osmolarity falling too fast. <b>Slow, steady neurologic improvement</b> is the goal.","bullets":["<b>Isotonic saline or balanced crystalloid</b> first, then by status + labs; <b>½NS only for specific cases</b> (e.g., osmolality not falling)","Book: NS if shock, otherwise ½NS; 1 L/hr → 100–200 mL/hr; half the deficit in 12 h","<b>Cerebral edema check hourly</b>","No improvement or worse → <b>reassess + report</b>, not a single cause"],"why":""}]},{"k":"ta","gist":"<b>Isotonic saline or a balanced crystalloid</b> first, then fluids adjusted to clinical status and lab trends — <b>half-normal saline only in specific situations</b>, such as osmolality not falling despite adequate fluids; <b>hourly neuro checks</b> (LOC, pupils, seizures) — report changes immediately; IV insulin only after fluids; <b>electrolytes every 1–2 hours</b> with <b>continuous cardiac monitoring</b>; strict intake and output.","terms":[],"cards":[{"t":"Critical rescue and insulin","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"changes in <b>LOC, pupils</b> (size, shape, reaction) or <b>seizures → notify the provider immediately</b>. <b>IV insulin only after adequate fluids</b>: bolus, then infusion until glucose reaches <b>250</b>, lowering <b>50–70 mg/dL per hour</b>. Potassium drops quickly → <b>electrolytes every 1–2 hours</b> and <b>continuous cardiac monitoring</b>.","bullets":["<b>LOC, pupil changes, seizures → notify now</b>","<b>Insulin after fluids</b>; drip until <b>250</b>; ↓ <b>50–70/hr</b>","<b>Lytes q1–2h</b>, <b>continuous ECG</b> (K⁺ drops)"],"why":""}]},{"k":"eo","gist":"<b>Slow, steady neurologic improvement</b>. No improvement or any deterioration → <b>reassess and report</b> (fluid status, osmolality, glucose, sodium, other causes) rather than assuming one cause; adequate BP and urine output; glucose and osmolality falling gradually; K⁺ in range.","terms":[],"cards":[{"t":"Sick-day rules","tag":"","topic":"56-dka-and-hhs-the-hyperglycemic-emergencie","text":"<b>tell the provider you are ill</b>; check glucose <b>every 2–4 hours</b>; <b>test for ketones even if glucose is in range</b>, especially when vomiting; <b>do not stop essential basal insulin</b>; follow the prescribed sick-day adjustments. Other diabetes medicines may need temporary interruption during dehydration, vomiting or fasting: obtain the drug-specific plan rather than continuing every drug automatically; <b>8–12 oz (240–360 mL) of sugar-free, caffeine-free fluid every hour awake</b> (sugar-containing fluids if glucose is below target); keep regular meal times; if solids won't stay down, replace the meal's carbohydrate with easier foods or liquids (<b>at least 150 g of carbohydrate a day</b> prevents starvation ketosis); rest.","bullets":["Tell the provider · glucose <b>q2–4h</b> · <b>ketones even if glucose OK</b>","<b>Continue essential basal insulin</b>; other drugs need an <b>individual sick-day plan</b>","<b>8–12 oz sugar-free, caffeine-free fluid every hour</b> awake","Can't eat → carb-containing liquids, <b>≥ 150 g carb/day</b>"],"why":"Both emergencies are dehydration emergencies first, which is why <b>fluids come before insulin</b>: insulin pulls glucose — and water with it — into the cells, and given to a patient with an empty circulation it can collapse the blood pressure. DKA involves enough absolute or relative insulin deficiency to allow ketoacids to accumulate. In HHS, residual insulin usually limits ketogenesis while hyperglycemia and dehydration progress. They can overlap; neither condition is classified from diabetes type alone."}]}]},{"id":"dm-foot","ch":"56","sys":"Hormones & glucose","name":"Diabetic foot ulcer and chronic complications","patient":"A client with 15 years of type 2 diabetes has a painless sore under the ball of the foot and cannot feel the monofilament on either foot.","topics":["56-foot-care-kidneys-and-preventing-injury","56-chronic-complications-vessels-eyes-nerve"],"report":["The client has a 2 cm open ulcer under the first metatarsal head of the right foot with redness spreading 3 cm around it and purulent drainage; temperature 100.8°F, glucose 286 mg/dL.","Type 2 diabetes for 15 years with peripheral neuropathy; walks barefoot at home.","Infected diabetic foot ulcer with loss of protective sensation; possible spreading infection.","Please evaluate today. Requesting wound culture, CBC, an offloading device and a podiatry or wound care consult."],"guide":[{"key":"56:3","name":"Complications, foot care & self-management"}],"nodes":[{"id":"dm-chronic","name":"Diabetes complications & foot care"}],"drugs":[],"videos":[{"id":"jOuGD3jyKNA","title":"Detecting diabetic retinopathy with a dilated eye exam (National Eye Institute)","see":"Why the yearly dilated exam finds retinal damage before vision is lost"},{"id":"LBvCHu2KyHQ","title":"How and why to perform foot checks (Parkview Health)","see":"A daily look at tops, soles and between the toes — because neuropathy hides injuries"},{"id":"JJzASQwGW3I","title":"Diabetic foot screening (Royal College of Podiatry)","see":"The monofilament test for protective sensation and checking the foot pulses"}],"steps":[{"k":"rc","gist":"<b>Loss of protective sensation</b>, burning or tingling in a <b>stocking pattern</b>, <b>foot deformities</b> (claw toes, prominent metatarsal heads), <b>dry cracked skin</b>, <b>calluses</b>, <b>weak pedal pulses</b> with hair loss, and <b>painless ulcers</b> at pressure points.","terms":[{"t":"Loss of protective sensation","see":"Cannot feel the <b>10-g monofilament</b>; doesn’t notice a stone in the shoe or a burn.","why":"<b>Sensory neuropathy</b>: chronic hyperglycemia damages nerves directly (glucose becomes <b>sorbitol</b>, which collects in nerves) and through damaged small vessels that leave nerves <b>hypoxic</b>.","means":"The main cause of foot ulcers. <b>Can’t feel it anywhere = high ulcer risk</b> → exam every 1–6 months depending on risk category."},{"t":"Paresthesias in a stocking pattern","see":"Burning, tingling or pain starting in the toes and moving up both feet; later numbness.","why":"The <b>longest nerves</b> are damaged first, so symptoms start at the toes and are <b>bilateral and symmetric</b>.","means":"<b>Pain comes first, then numbness</b> — a foot that stops hurting is not getting better."},{"t":"Claw toes, hammertoes and prominent metatarsal heads","see":"Toes curled up, high arch, weight on the balls of the feet.","why":"<b>Motor neuropathy</b> weakens the small muscles of the foot, so the stronger muscles pull the toes into deformity. The fat pad under the metatarsal heads thins, creating <b>pressure points</b>.","means":"Pressure points → <b>calluses → ulcers</b>. Needs fitted shoes with a high, wide toe box."},{"t":"Dry, cracked skin","see":"Fissures, especially on the heels.","why":"<b>Autonomic neuropathy</b> stops the sweat glands, so the skin dries and cracks.","means":"Cracks are an entry point for bacteria. Moisturize — <b>but not between the toes</b> (moisture there breeds fungus)."},{"t":"Weak pedal pulses, hair loss and claudication","see":"Faint dorsalis pedis or posterior tibial pulses, shiny hairless skin, calf pain with walking.","why":"<b>Peripheral artery disease</b>: diabetes speeds <b>atherosclerosis</b> in large vessels, reducing blood flow to the feet.","means":"<b>Poor perfusion is the main cause of poor healing.</b> A vascular consult may be needed."},{"t":"Painless ulcer","see":"Open wound under the metatarsal heads or great toe, or on the tops of claw toes — often with little pain.","why":"Repeated pressure on an area the client <b>cannot feel</b> breaks the skin down, and the client keeps walking on it.","means":"<b>Offload</b> the foot — walking on it enlarges the wound. Look for infection: redness, warmth, drainage, odor, rising glucose."},{"t":"Charcot foot","see":"Warm, red, swollen foot; the arch collapses into a “rocker bottom.”","why":"Without sensation, small fractures and joint injuries go <b>unnoticed</b> and the client keeps walking, so the bones of the foot break down.","means":"Can be mistaken for infection or a clot. Needs offloading and specialist care."}],"cards":[{"t":"Assessment (Box 56.8)","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"history of ulcer or amputation; <b>dry, cracked skin</b>, ulcers, thick or ingrown nails, tinea pedis, fungal nails; circulation — <b>claudication</b>, <b>dorsalis pedis and posterior tibial pulses</b>, prolonged capillary refill (the box prints \"greater than 25 seconds\", which looks like a misprint — normal refill is under about 3 seconds <i>(not in this chapter)</i>), <b>hair loss on the top of the foot</b>; deformity — calluses, corns, prominent metatarsal heads, <b>claw or hammertoes</b>, bunions, Charcot foot; strength — ankle and great-toe motion; sensation — numbness, burning, tingling and <b>Semmes-Weinstein monofilament at 10 points on each foot</b>. Professional foot exam <b>at least yearly</b>.","bullets":["Skin, nails, fungus · pulses (<b>DP, PT</b>), <b>prolonged cap refill</b> (box's \"&gt; 25 s\" looks like a misprint), <b>hair loss</b>","Calluses, <b>claw/hammertoes</b>, bunions, Charcot","<b>Monofilament 10 points per foot</b>; full exam <b>at least yearly</b>"],"why":""},{"t":"Peripheral neuropathy (DPN)","tag":"","topic":"56-chronic-complications-vessels-eyes-nerve","text":"progressive, <b>bilateral, permanent</b> nerve damage: sensory fibers → <b>pain first, then numbness</b>; motor fibers → weakness and <b>foot deformities</b>. Causes: hyperglycemia and high lipids, damaged vessels (nerve <b>hypoxia</b>), genes, smoking and alcohol; excess glucose becomes <b>sorbitol</b>, which collects in nerves. Table 56.1: <b>paresthesias</b> (burning, tingling from the toes up), <b>dysesthesias</b>, <b>loss of sensation</b>; high arch, <b>claw toes, hammertoes</b>, weight shifted to the metatarsal heads and toe tips.","bullets":["<b>Bilateral, progressive, permanent</b>: <b>pain → numbness</b>; motor → weakness, deformities","Nerve <b>hypoxia</b> + <b>sorbitol</b> buildup","Burning/tingling from <b>toes up</b> · claw toes, hammertoes → pressure on <b>metatarsal heads</b>"],"why":"Neuropathy is why the diabetic foot is so dangerous: sensory loss removes the warning (a stone in the shoe never hurts), motor loss deforms the foot and creates pressure points, autonomic loss dries and cracks the skin, and poor perfusion keeps the wound from healing. Each nerve type takes away one layer of protection — so foot care has to replace every layer by deliberate habit."},{"t":"Autonomic neuropathy","tag":"","topic":"56-chronic-complications-vessels-eyes-nerve","text":"<b>heart and vessels (CAN)</b>: <b>orthostatic hypotension and syncope</b> (falls), exercise intolerance, <b>painless MI</b>. <b>Skin</b>: no sweating → dry, cracking skin. <b>GI</b>: reflux, <b>gastroparesis</b> (early fullness, bloating, nausea, vomiting; a cause of <b>hypoglycemia</b> because food arrives later than the insulin), bacterial overgrowth, <b>constipation — the most common GI problem</b> — alternating with diarrhea, nocturnal diarrhea, sweating while eating (Table 56.1). <b>Bladder</b>: incomplete emptying, <b>retention → UTIs</b>; frequency and urgency first, later no sense of fullness and incontinence. <b>Erectile dysfunction</b>. <b>Loss of hypoglycemia warning signs</b>.","bullets":["<b>CAN</b>: <b>orthostatic hypotension, syncope</b>, <b>painless MI</b>, exercise intolerance","Skin: no sweating → <b>cracks</b>","GI: <b>gastroparesis</b> (→ <b>lows</b>: food late, insulin on time), <b>constipation most common</b>, diarrhea, sweating while eating","Bladder: <b>retention → UTIs</b> → later incontinence","<b>ED</b> · <b>lost low-glucose warning signs</b>"],"why":""}]},{"k":"ac","gist":"Chronic hyperglycemia <b>thickens basement membranes</b> and damages small vessels (<b>retinopathy, nephropathy, neuropathy</b>) and speeds <b>atherosclerosis</b> in large vessels (<b>MI, stroke, PAD</b>). In the foot: <b>neuropathy causes the ulcer; poor perfusion keeps it from healing</b>; high glucose weakens white cells.","terms":[{"t":"Microvascular vs macrovascular damage","see":"Small vessels: eyes, kidneys, nerves. Large vessels: heart, brain, legs.","why":"High glucose <b>thickens capillary basement membranes</b> and is directly toxic to cells; small-vessel ischemia causes <b>tissue hypoxia</b>. In large vessels it speeds <b>plaque</b> formation.","means":"Every <b>1-point drop in A1C</b> markedly reduces eye and kidney damage. BP and lipid control matter as much as glucose for the large vessels."},{"t":"Albuminuria","see":"Urine albumin 30–299 mg/24 h — the earliest sign of nephropathy.","why":"High pressure inside the glomerulus damages the filter, so <b>albumin leaks</b> into the urine.","means":"Screen <b>yearly</b>; ACE inhibitors or ARBs slow progression (monitor potassium); avoid nephrotoxins such as NSAIDs and contrast without hydration."},{"t":"Infection risk","see":"Wounds that get infected and heal slowly.","why":"High glucose <b>impairs white blood cells</b>, reduces tissue oxygen and <b>feeds bacteria</b>; infection releases stress hormones that <b>raise glucose further</b>.","means":"An unexplained rise in glucose can be the <b>first sign</b> of a foot infection."}],"cards":[{"t":"The mechanism","tag":"","topic":"56-chronic-complications-vessels-eyes-nerve","text":"chronic hyperglycemia <b>thickens basement membranes</b>, glucose is directly <b>toxic</b> to cells, and small-vessel ischemia causes <b>tissue hypoxia</b>. Hyperglycemia is the main cause of <b>microvascular</b> damage and speeds <b>macrovascular</b> disease. Smoking, inactivity, obesity, hypertension and high lipids add to it. <b>Every 1-point drop in A1C</b> markedly reduces kidney and eye complications.","bullets":["↑ glucose → <b>thick basement membranes</b>, <b>glucose toxicity</b>, small-vessel <b>hypoxia</b>","Main cause of <b>micro</b>vascular damage; speeds <b>macro</b>vascular","<b>Each 1-point A1C drop</b> → far fewer kidney + eye complications"],"why":""},{"t":"Why feet are lost","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"most amputations follow a <b>foot ulcer</b>, and 5-year mortality after amputation is high. <b>Neuropathy is the main cause of ulcers; poor perfusion is the main cause of poor healing.</b> Motor neuropathy → <b>claw toes</b>, thinned fat pad under the <b>metatarsal heads</b>, pressure points → calluses → ulcers. <b>Charcot foot</b>: warm, swollen, painful; the arch collapses into a <b>\"rocker bottom\"</b>. Autonomic → dry, cracked skin. Sensory → numbness, injuries unnoticed. <b>PAD</b> slows healing.","bullets":["Most amputations follow a <b>foot ulcer</b>","<b>Neuropathy → ulcers</b>; <b>poor perfusion → no healing</b>","Claw toes, thin fat pad → <b>pressure → calluses → ulcers</b>","<b>Charcot</b>: warm, swollen, <b>rocker bottom</b>"],"why":""},{"t":"Stroke and infection","tag":"","topic":"56-chronic-complications-vessels-eyes-nerve","text":"stroke risk is <b>2–4 times higher</b>, with more severe carotid atherosclerosis; hypertension, high lipids, nephropathy, peripheral vascular disease, alcohol and tobacco raise it further. Vascular changes plus high glucose <b>weaken white cells</b>, impair tissue oxygen and feed microbes → <b>more infections</b>, which turn serious fast and can lead to <b>sepsis</b>.","bullets":["Stroke <b>2–4×</b> risk (↑ more with HTN, lipids, nephropathy, PVD, alcohol, tobacco)","High glucose <b>weakens WBCs</b>, feeds microbes → <b>infections turn serious fast</b>, sepsis"],"why":""},{"t":"Nephropathy","tag":"","topic":"56-chronic-complications-vessels-eyes-nerve","text":"diabetes is the <b>leading cause of end-stage kidney disease</b> in the US. Hyperglycemia raises pressure in kidney vessels; the <b>glomerulus leaks albumin</b>; narrowed vessels starve kidney cells → CKD. <b>Hypertension speeds it</b>. Shown by rising <b>albumin excretion</b> and falling <b>GFR</b>; delayed by glucose control.","bullets":["<b>Leading cause of ESKD</b>","↑ glomerular pressure → <b>leaks albumin</b> → hypoxic kidney cells → CKD","<b>Hypertension speeds it</b> · watch <b>albumin + GFR</b>"],"why":""},{"t":"Retinopathy","tag":"","topic":"56-chronic-complications-vessels-eyes-nerve","text":"blindness is <b>25 times more common</b>; after <b>20 years</b> nearly everyone has some retinopathy, with <b>few symptoms until vision is lost</b>. <b>Nonproliferative</b>: leaky, blocked vessels, edema, hard exudates, hemorrhages — slow, rarely blinding. <b>Proliferative</b>: hypoxic retina grows <b>new fragile vessels</b> (neovascularization) that <b>bleed</b> → vision loss. <b>Macular edema</b> is the main cause of vision loss. Also earlier <b>cataracts</b> and more <b>open-angle glaucoma</b>. High glucose blurs vision temporarily — <b>check refraction only once glucose is normal</b>. Prevent with glucose, BP and lipid control and <b>yearly eye exams</b>.","bullets":["Blindness <b>25×</b>; nearly all after <b>20 years</b>; <b>silent</b> until vision is lost","<b>Nonproliferative</b>: leaky vessels, slow · <b>proliferative</b>: <b>fragile new vessels bleed</b>","<b>Macular edema</b> = main cause of vision loss","Earlier <b>cataracts</b>, more <b>glaucoma</b>","High glucose blurs vision → <b>refraction once glucose normal</b>","<b>Yearly eye exam</b>"],"why":""}]},{"k":"ph","gist":"<b>Impaired tissue integrity</b> with <b>risk for infection and amputation</b>; <b>risk for injury</b> (burns, unnoticed wounds, falls from neuropathy and orthostatic hypotension); <b>reduced peripheral perfusion</b>.","terms":[],"cards":[{"t":"Risk factors","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"neuropathy, <b>male sex</b>, poor glucose control, cardiovascular, eye or kidney complications; poor gait, calluses, deformities, limited joint motion, severe nail problems, PAD, and <b>any prior ulcer or amputation</b>.","bullets":["Neuropathy, <b>men</b>, poor control, other complications","Calluses, deformity, PAD, <b>prior ulcer/amputation</b>"],"why":""}]},{"k":"gs","gist":"<b>Offload</b> pressure, keep the wound <b>moist and débrided</b>, <b>control glucose</b>, treat infection, and protect both feet with <b>daily inspection</b>, proper footwear and regular podiatry care.","terms":[],"cards":[{"t":"Wound care","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"standards: a <b>moist wound environment</b>, <b>débridement</b> of dead tissue, and <b>offloading</b> — <b>no shoe on the affected foot</b>; total-contact casts, half shoes, cast walkers, wheelchairs, crutches. Patients without sensation keep walking on painless ulcers, enlarging them. <b>Ulcers recur unless weight is permanently redistributed.</b>","bullets":["<b>Moist</b> environment + <b>débridement</b> + <b>offloading</b>","No shoe on that foot; <b>total-contact cast</b>","Painless → keep walking → bigger ulcer","<b>Recurs</b> unless weight permanently redistributed"],"why":""},{"t":"Footwear","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"fitted by an experienced fitter (podiatrist): <b>½–⅝ inch longer than the longest toe</b>, <b>heels under 2 inches</b>; <b>change shoes at midday and again in the evening</b>. Soft, seamless, padded, moisture-absorbing socks — <b>white</b>, so blood or drainage shows. No tight stockings or constricting bands. Toe deformities → <b>custom shoes with high, wide toe boxes</b>; break new shoes in slowly with frequent checks.","bullets":["Shoes <b>½–⅝ in longer</b> than longest toe; <b>heels &lt; 2 in</b>","<b>Change shoes midday + evening</b>","<b>White</b>, seamless, padded socks","Deformities → <b>wide, deep toe box</b>; break in slowly"],"why":""}]},{"k":"ta","gist":"Monofilament and pulse checks; <b>no weight on the ulcer</b>; wound care per order; inspect <b>daily, including between the toes</b>; teach: never barefoot, check bath water with the wrist or a thermometer, no heating pads, <b>don’t self-treat corns</b>, cut nails straight across, report any sore at once.","terms":[],"cards":[{"t":"Teaching (Box 56.9)","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"<b>inspect feet daily</b>, including <b>between the toes</b> (mirror on the floor for the soles); wash daily in <b>lukewarm</b> water and <b>dry thoroughly</b>; moisturize — <b>but not between the toes</b>; clean cotton socks daily; <b>alternate shoes</b> day to day, breathable leather or cloth; <b>check shoes for pebbles</b> and torn linings; buy shoes <b>later in the day</b>; <b>socks for warmth</b>; <b>cut nails straight across</b> and file; <b>check bath water with the wrist or a thermometer</b>; never hot-water bottles, heating pads or heaters; <b>don't self-treat corns, calluses, blisters or ingrown nails</b>; <b>never barefoot</b>; no open-toed sandals or thong straps; <b>don't cross legs</b>; see the provider <b>at once</b> for blisters, sores or infection (dry sterile dressing, <b>no tape on skin</b>). First check that the patient can see and reach every part of the foot; if not, <b>teach a family member</b> to inspect and care for it.","bullets":["<b>Inspect daily, between toes</b> (mirror for soles)","<b>Lukewarm</b> wash, <b>dry well</b>, lotion <b>not between toes</b>","Alternate shoes, <b>check inside</b>, buy <b>later in day</b>","<b>Nails straight across</b> · <b>test water with wrist</b>","<b>No heating pads</b>, <b>no self-treating corns</b>, <b>never barefoot</b>, no sandals, <b>don't cross legs</b>","Sores → provider <b>now</b>; dry sterile dressing, no tape","Can't see or reach the feet → <b>teach family</b>"],"why":""},{"t":"How injuries happen","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"<b>walking barefoot</b>, <b>ill-fitting shoes</b>, <b>heat</b> (hot water bottles, heating pads, hot baths) and <b>chemical burns</b> from OTC corn removers. Pressure ulcers: <b>sole and ball</b> from walking, <b>top and sides</b> from shoes; typically at the <b>great toe, under the metatarsal heads, and on tops of claw toes</b>. Infection is common, hard to treat, and raises glucose further.","bullets":["<b>Barefoot</b>, tight shoes, <b>heat</b>, <b>corn removers</b>","Sole/ball = walking · top/sides = shoes","Infection → <b>higher glucose → more infection</b>"],"why":""}]},{"k":"eo","gist":"The ulcer <b>shrinks and heals</b> without infection; glucose in target; the client or a family member <b>demonstrates daily foot inspection</b>, wears fitted shoes and keeps foot exams on the schedule for the risk category.","terms":[],"cards":[{"t":"Monofilament and risk categories (Table 56.7)","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"a <b>10-g</b> nylon monofilament: <b>can't feel it anywhere = high ulcer risk</b>. Category 0 (sensation intact, no PAD or deformity): <b>yearly exam</b>, footwear teaching. Category 1 (no protective sensation ± deformity): <b>every 3–6 months</b>, consider a specialist. Categories 2–3 (no sensation <b>plus PAD</b>, or <b>prior ulcer/amputation</b>): <b>every 1–3 months</b>, specialist, <b>prescription footwear</b>, vascular consult.","bullets":["<b>10-g</b> monofilament not felt = <b>high risk</b>","<b>0</b>: yearly · <b>1</b>: q3–6 months · <b>2–3</b>: q1–3 months + prescription shoes"],"why":""},{"t":"Screening and targets","tag":"","topic":"56-foot-care-kidneys-and-preventing-injury","text":"<b>yearly urine albumin</b>: type 1 after <b>5 years</b>, type 2 <b>from diagnosis</b>. <b>Persistent albuminuria 30–299 mg/24 h</b> = earliest nephropathy (type 1) and a marker in type 2. Keep <b>BP below 140/80</b> (the kidney section's target; the cardiovascular section gives &lt; 140/90); control glucose and cholesterol; <b>stop smoking</b>. Once albuminuria appears, the focus is BP, glucose and <b>avoiding nephrotoxic drugs</b>.","bullets":["<b>Yearly urine albumin</b> (type 1 after 5 yr; type 2 from diagnosis)","<b>30–299 mg/24 h</b> = earliest nephropathy","<b>BP &lt; 140/80</b> (kidney section), glucose, lipids, <b>no smoking</b>","Albuminuria → BP, glucose, <b>no nephrotoxins</b>"],"why":"Kidney damage and insulin interact in a way that surprises students: the kidney also <b>clears insulin</b>, so as kidney function falls, each dose lasts longer and hypoglycemia becomes more common — the \"improving\" glucose in a patient with worsening kidneys is often a warning, not a success."}]}]},{"id":"dm-surgery","ch":"56","sys":"Hormones & glucose","name":"Diabetes in the hospital and around surgery","patient":"A client with type 2 diabetes on metformin and glipizide is scheduled for a hip replacement tomorrow and will be NPO after midnight.","topics":["56-diabetes-in-the-hospital-and-around-surg"],"report":["Post-op day 1 after hip replacement: glucose 248 mg/dL this morning after readings in the 140s; temperature 99.9°F and new burning on urination.","Type 2 diabetes; metformin and glipizide held before surgery; on basal insulin with a correction scale.","Unexpected rise in glucose — possible infection, such as a UTI.","Requesting a urinalysis and culture, a CBC, and a review of the insulin regimen."],"guide":[{"key":"56:3","name":"Complications, foot care & self-management"},{"key":"56:1","name":"Insulin & diabetes drugs"}],"nodes":[{"id":"dm-rx","name":"Insulin & diabetes drugs"},{"id":"insulin","name":"Insulin, glucagon & glucose"},{"id":"k-acidbase","name":"Potassium & acid–base"}],"drugs":[{"id":"metformin","name":"Metformin"},{"id":"glipizide","name":"Glipizide"},{"id":"glargine","name":"Insulin glargine"},{"id":"lispro","name":"Insulin lispro"}],"videos":[{"id":"uRRBUcO9KiA","title":"Blood glucose monitoring (Open RN nursing skills)","see":"The full bedside check, step by step, from hand hygiene and patient identification to the reading"}],"steps":[{"k":"rc","gist":"<b>Hyperglycemia</b> from illness and surgical stress, <b>hypoglycemia</b> when NPO on mealtime insulin or a sulfonylurea, an <b>unexpected glucose rise</b> (possible infection), and <b>atypical cardiac signs</b> — a silent MI — in clients with neuropathy.","terms":[{"t":"Stress hyperglycemia","see":"Glucose rising during illness or after surgery even without eating.","why":"Surgery and illness release <b>cortisol, epinephrine and glucagon</b> (counterregulatory hormones), which raise glucose and make cells <b>resistant to insulin</b>.","means":"Insulin needs often go <b>up</b> around surgery, even while the client eats nothing. High glucose raises <b>infection</b> risk and slows <b>healing</b>."},{"t":"Unexpected rise in a controlled client","see":"Glucose suddenly higher with no change in diet or drugs.","why":"The stress hormones of an infection raise glucose, often <b>before a fever appears</b>.","means":"Look for <b>infection</b>: UTI, pneumonia, cellulitis, wound infection."},{"t":"Hypoglycemia when NPO","see":"Low glucose in a client not eating.","why":"Mealtime insulin or a <b>sulfonylurea</b> keeps lowering glucose with <b>no food</b> coming in.","means":"When NPO, <b>hold mealtime (nutritional) doses</b> and premixed insulin; keep <b>basal</b> insulin (often reduced) and give <b>correction doses</b> and any IV insulin <b>as prescribed</b> — NPO doesn’t cancel the correction plan."},{"t":"Silent MI","see":"ECG changes or a new dysrhythmia without chest pain; unexplained hypotension or dyspnea.","why":"<b>Autonomic neuropathy</b> damages the nerves that carry cardiac pain.","means":"<b>Continuous ECG</b> for older adults, long-standing diabetes and heart disease; report ECG or potassium changes."},{"t":"Hypokalemia during IV insulin","see":"Falling K⁺, muscle weakness, ECG changes.","why":"Insulin moves <b>potassium into the cells</b> along with glucose.","means":"Monitor <b>K⁺ and cardiac rhythm</b> while IV insulin and glucose run."}],"cards":[{"t":"Why glucose rises","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"illness, less activity, <b>held antidiabetic drugs</b>, <b>corticosteroids or antipsychotics</b>, changed nutrition. Inpatient hyperglycemia means <b>more infections, longer stays, more ICU care and higher mortality</b>; admission glucose <b>&gt; 198</b> predicts worse outcomes. <b>Hypoglycemia</b> also raises mortality.","bullets":["Illness, inactivity, <b>held drugs</b>, <b>steroids, antipsychotics</b>, diet changes","High glucose → infections, longer stays, <b>↑ death</b>; admission <b>&gt; 198</b> = worse","<b>Lows</b> also ↑ mortality"],"why":""},{"t":"Unexpected rise = look for infection","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"balancing hormones often raise glucose <b>before a fever appears</b>. When a patient's controlled glucose <b>rises unexpectedly</b>, check for <b>infection</b> — UTI, pneumonia, cellulitis, wound infection.","bullets":["Glucose rises <b>before fever</b>","<b>Unexpected rise → look for infection</b> (UTI, pneumonia, cellulitis, wound)"],"why":""}]},{"k":"ac","gist":"Surgery is a <b>controlled injury</b>: stress hormones raise glucose and insulin needs, and the client is at risk of <b>DKA or HHS</b>, <b>dehydration and kidney injury</b>, <b>aspiration</b> (gastroparesis), <b>ileus and urinary retention</b> (autonomic neuropathy) and <b>cardiac events</b>.","terms":[{"t":"Metformin before contrast or surgery","see":"Held around iodinated contrast or surgery, per the order or protocol.","why":"Metformin is cleared by the kidneys. If contrast, anesthesia or dehydration impairs kidney function, it builds up and can cause <b>lactic acidosis</b>.","means":"<b>Contrast</b> (eGFR 30–60 or other risk factors): stop at or before the procedure, <b>recheck eGFR at 48 hours</b>, restart if kidney function is stable. <b>Surgery</b>: hold while food and fluids are restricted. <i>The textbook teaches a 24-hour hold and restarting when kidney function is normal.</i>"},{"t":"Pre-op glucose above 200","see":"Glucose ≥ 200 mg/dL before surgery.","why":"High glucose impairs white blood cells and <b>collagen formation</b>.","means":"More wound <b>infection</b> and poor healing — report it before surgery."}],"cards":[{"t":"Why it is riskier","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"anesthesia and surgery release <b>counterregulatory hormones</b> → hyperglycemia and <b>ketoacidosis</b> risk; <b>HHS</b> after surgery carries high mortality; diuresis → dehydration and <b>acute kidney injury</b>. Diabetes adds hypertension, ischemic heart disease, stroke, <b>MI</b> and cardiomyopathy risk; <b>urinary retention</b>; <b>gastroparesis and reflux (aspiration with anesthesia)</b>; <b>paralytic ileus</b> from autonomic neuropathy.","bullets":["Stress hormones → <b>↑ glucose</b>, <b>DKA</b>, <b>HHS</b>, <b>AKI</b>","↑ MI, stroke; <b>urinary retention</b>","<b>Gastroparesis → aspiration</b>; <b>ileus</b>"],"why":""}]},{"k":"ph","gist":"<b>Unstable blood glucose</b> in both directions; <b>risk for infection</b> and poor wound healing; risk for <b>acute kidney injury</b>, <b>aspiration</b>, <b>hypokalemia</b> and a <b>silent MI</b>.","terms":[],"cards":[{"t":"Targets","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"<b>critically ill: 140–180</b> (continuous <b>IV insulin drip</b> works best in ICU). <b>Non-critical: before meals &lt; 140, random &lt; 180</b>, with scheduled <b>basal + mealtime + correction</b> subcutaneous insulin. <b>Review the regimen below 100; change it below 70.</b>","bullets":["<b>ICU: 140–180</b> (IV drip)","<b>Floor: pre-meal &lt; 140, random &lt; 180</b> (basal + meal + correction)","Review <b>&lt; 100</b>, change <b>&lt; 70</b>"],"why":""}]},{"k":"gs","gist":"Keep glucose <b>140–180</b> in critical care, or <b>before meals &lt; 140 and random &lt; 180</b> on the unit, with <b>basal + mealtime + correction</b> insulin; adjust oral drugs before surgery; recognize infection and cardiac changes early.","terms":[],"cards":[{"t":"Before surgery","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"<b>sulfonylureas stopped 1 day before</b>; <b>metformin held</b> per the order or protocol while food and fluids are restricted (<i>the textbook: at least 24 hours before, restarted when kidney function is normal</i>); <b>other oral drugs stopped the day of surgery</b>; long-acting insulin may be switched to <b>intermediate-acting 1–2 days before</b>. Pre-op glucose <b>&lt; 200</b> (higher = more infection and poor healing).","bullets":["<b>Sulfonylureas: stop 1 day before</b>","<b>Metformin: hold per order/protocol</b> while intake is restricted (book: ≥ 24 h before)","Other orals: stop <b>day of surgery</b> · long-acting → NPH 1–2 days before","Pre-op glucose <b>&lt; 200</b>"],"why":""},{"t":"NPO patients","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"give <b>basal</b> insulin (often at a <b>reduced</b> dose) — it controls baseline glucose. <b>Hold mealtime (nutritional) doses</b> of rapid- or short-acting insulin, and <b>amylin analogs and incretin mimetics</b> (they cause lows without food). NPO does <b>not</b> cancel the rest of the plan: give <b>prescribed correction doses</b> and any <b>IV insulin</b> as ordered (<a href=\"https://doi.org/10.2337/dc26-S016\">ADA 2026 Standards, section 16</a>). <b>Don't give premixed insulins</b> (they contain rapid or short insulin).","bullets":["NPO: <b>give basal</b> (often reduced)","<b>Hold mealtime</b> rapid/short doses, amylin, incretins","<b>Correction</b> doses and <b>IV insulin</b> still <b>as prescribed</b>","<b>No premixed</b> insulin"],"why":""}]},{"k":"ta","gist":"Stop <b>sulfonylureas 1 day before</b>; hold <b>metformin</b> per the order or protocol; <b>basal insulin</b> (often reduced) while NPO, <b>hold mealtime doses and premixed insulin</b> but give <b>correction insulin as prescribed</b>; <b>hourly glucose</b> with IV insulin, glucose and potassium during surgery; monitor <b>K⁺ and continuous ECG</b> after; post-op liquids with carbohydrate, <b>not sugar-free</b>.","terms":[],"cards":[{"t":"During surgery","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"IV <b>insulin, glucose and potassium</b> with <b>hourly</b> capillary glucose; target <b>140–180</b>; about <b>5 g glucose per hour</b> to prevent hypoglycemia, ketosis and protein breakdown; stress may raise insulin needs.","bullets":["IV <b>insulin + glucose + K⁺</b>, <b>hourly</b> glucose, <b>140–180</b>","~<b>5 g glucose/hour</b>"],"why":""},{"t":"Insulin and analgesia","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"continue glucose and insulin infusions until stable and eating; short-term insulin may be needed even for patients on oral agents. <b>Opioids slow the gut and change glucose</b>; in older adults they risk confusion, ileus, hypoventilation, hypotension and retention — <b>PCA</b> reduces respiratory problems and confusion.","bullets":["Infusions until eating · maybe short-term insulin","<b>Opioids</b> → ileus, confusion, hypoventilation → <b>PCA</b> helps"],"why":""},{"t":"Monitoring","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"autonomic neuropathy or vascular disease → watch for <b>hypotension and respiratory arrest</b>. <b>Beta blockers mask hypoglycemia</b> → monitor closely. <b>Hyperkalemia</b> in kidney failure; <b>hypokalemia</b> worsened by intraoperative insulin and glucose → <b>cardiac rhythm and K⁺</b>. <b>Continuous ECG</b> for older patients, long-standing type 1 and heart disease — ECG or K⁺ changes may be a <b>silent MI</b>. Fluid balance for <b>acute kidney injury</b> (hydrate well with nephrotoxic antibiotics); raised blood protein or nitrogen makes fluid management harder — check central venous or pulmonary artery pressure as needed.","bullets":["Neuropathy → <b>hypotension, respiratory arrest</b>","<b>Beta blockers mask lows</b>","K⁺ high (kidney failure) or <b>low</b> (insulin + glucose) → rhythm + K⁺","<b>Continuous ECG</b> → <b>silent MI</b> · I&amp;O for <b>AKI</b>","↑ blood protein/nitrogen → harder fluid balance → CVP/PA pressure"],"why":""}]},{"k":"eo","gist":"Glucose in target <b>without hypoglycemia</b> (review the regimen below 100, change it below 70); no wound or urinary infection; metformin restarted only as the order or protocol directs (kidney function stable, eating again); eating at least <b>150–200 g of carbohydrate a day</b>.","terms":[],"cards":[{"t":"Post-op nutrition","tag":"","topic":"56-diabetes-in-the-hospital-and-around-surg","text":"clear or full liquids: about <b>200 g of carbohydrate a day</b> in equal portions — <b>not sugar free</b>. <b>25–35 kcal/kg/day</b>. Advance to solids as fast as tolerated; once eating, at least <b>150–200 g of carbohydrate daily</b> to prevent lows. <b>TPN</b> can cause severe hyperglycemia → glucose at least <b>every 6 hours</b>.","bullets":["Liquids: ~<b>200 g carb/day</b>, <b>not sugar-free</b>","<b>25–35 kcal/kg/day</b>","Eating → <b>≥ 150–200 g carb/day</b>","<b>TPN</b> → glucose <b>q6h</b>"],"why":""}]}]}];
window.CJ_GUIDE = [{"key":"45:0","name":"GI changes with aging","conds":["gi-aging-exam"]},{"key":"45:1","name":"Organs by quadrant (Table 45.1)","conds":["gi-aging-exam"]},{"key":"46:0","name":"Healthy mouth & oral care (Boxes 46.1–46.2)","conds":["stomatitis"]},{"key":"46:1","name":"GERD","conds":["gerd"]},{"key":"46:2","name":"Hiatal hernia","conds":["gerd"]},{"key":"47:0","name":"Gastritis & peptic ulcer disease","conds":["gastritis","ugib"]},{"key":"47:1","name":"Upper GI bleeding & gastric cancer","conds":["ugib","gastric-cancer"]},{"key":"53:0","name":"Pancreas, thyroid & parathyroid","conds":["endo-aging"]},{"key":"53:1","name":"Endocrine changes with aging","conds":["endo-aging"]},{"key":"53:2","name":"24-hour urine test","conds":["endo-testing"]},{"key":"55:0","name":"Hypothyroidism & myxedema coma","conds":["hypothyroid"]},{"key":"55:1","name":"Hyperthyroidism, thyroidectomy & thyroid storm","conds":["hyperthyroid","thyroid-storm"]},{"key":"55:2","name":"Parathyroid disorders & calcium","conds":["hypopara","hyperpara"]},{"key":"56:0","name":"Diagnosing & monitoring diabetes","conds":["dm-new"]},{"key":"56:1","name":"Insulin & diabetes drugs","conds":["dm-new","dm-surgery"]},{"key":"56:2","name":"Hypoglycemia, DKA & HHS","conds":["hypoglycemia","dka","hhs"]},{"key":"56:3","name":"Complications, foot care & self-management","conds":["dm-foot","dm-surgery"]}];
